// Gerado a partir de MENU-AW139.html (app "ndl").
window.AW139_EMBEDDED = {"style": "\n  @import url('https://fonts.cdnfonts.com/css/din-condensed');\n\n  :host{\n    --bg-0: #0a1430;\n    --bg-1: #102050;\n    --panel: #102a4a;\n    --panel-2: #143462;\n    --line: #2e5fa8;\n    --line-bright: #4f8fe6;\n    --amber: #ffc400;\n    --amber-dim: #cc8800;\n    --green: #2bff7e;\n    --green-dim: #00b34d;\n    --red: #ff3b3b;\n    --red-dim: #d61f1f;\n    --text: #eaf4ff;\n    --text-dim: #9fc4ff;\n    --text-faint: #6f9adb;\n    --white: #ffffff;\n    --mono: 'JetBrains Mono', 'Courier New', monospace;\n    --disp: 'DIN Condensed', 'Oswald', 'Arial Narrow', sans-serif;\n  }\n\n  *{ box-sizing: border-box; }\n  html,body{\n    margin:0; padding:0;\n    width: 100%;\n    max-width: 100vw;\n    background: #ffffff;\n    color: var(--text);\n    font-family: var(--mono);\n    min-height:100vh;\n    min-height: 100dvh;\n    overflow-x: hidden;\n    -webkit-font-smoothing: antialiased;\n  }\n\n  /* impede que qualquer imagem, svg ou elemento fixo ultrapasse a largura da tela,\n     independentemente do tamanho do device */\n  img, svg{ max-width: 100%; }\n\n  :host{ --topbar-h: 46px; }\n  .scope{\n    max-width: 760px;\n    width: 100%;\n    margin: 0 auto;\n    padding: calc(var(--topbar-h) + 12px + env(safe-area-inset-top)) calc(16px + env(safe-area-inset-right)) calc(60px + env(safe-area-inset-bottom)) calc(16px + env(safe-area-inset-left));\n  }\n\n  /* ---------- Barra fixa de navega\u00e7\u00e3o + alerta ---------- */\n  .topbar{\n    position: fixed;\n    top: 0; left: 0; right: 0;\n    z-index: 500;\n    background: rgba(10,20,48,0.96);\n    backdrop-filter: blur(6px);\n    -webkit-backdrop-filter: blur(6px);\n    border-bottom: 1px solid var(--line-bright);\n    padding-top: env(safe-area-inset-top);\n  }\n  .topbar-row{\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 10px;\n    padding: 8px 10px;\n  }\n  .ndl-back-btn{\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    flex-shrink: 0;\n    background: rgba(255,255,255,0.12);\n    border: 1px solid rgba(255,255,255,0.35);\n    color: #fff;\n    font-family: inherit;\n    font-size: 13px;\n    font-weight: 700;\n    letter-spacing: 0.02em;\n    padding: 8px 14px;\n    border-radius: 5px;\n    cursor: pointer;\n  }\n  .topnav-select{\n    flex-shrink: 0;\n    background: var(--bg-1);\n    border: 1px solid var(--line);\n    color: var(--text-dim);\n    font-family: var(--mono);\n    font-size: 12.5px;\n    font-weight: 700;\n    padding: 7px 8px;\n    border-radius: 7px;\n    cursor: pointer;\n    max-width: 55%;\n  }\n  .topbar-alert{\n    display: block;\n    width: calc(100% - 20px);\n    box-sizing: border-box;\n    background: linear-gradient(180deg, #7a1a1a 0%, #4a0e0e 55%, #380a0a 100%);\n    color: var(--white);\n    font-size: clamp(9px, 3.1vw, 12.5px);\n    font-weight: 700;\n    letter-spacing: 0.02em;\n    text-align: center;\n    white-space: nowrap;\n    overflow: hidden;\n    padding: 7px 10px;\n    margin: 0 10px 8px 10px;\n    border-radius: 7px;\n    border: 1px solid #7a1414;\n    text-shadow:\n      0 1px 0 rgba(255,255,255,0.25),\n      0 -1px 1px rgba(0,0,0,0.55);\n    box-shadow:\n      inset 0 1px 0 rgba(255,255,255,0.22),\n      inset 0 -2px 3px rgba(0,0,0,0.5),\n      0 3px 6px rgba(0,0,0,0.45),\n      0 1px 0 rgba(255,255,255,0.06);\n  }\n\n  /* ---------- Bot\u00e3o Novo Voo (canto inferior direito da capa) ---------- */\n  .novo-voo-btn{\n    flex-shrink: 0;\n    z-index: 5;\n    background: rgba(255,255,255,0.08);\n    color: var(--green);\n    border: 1px solid currentColor;\n    font-family: var(--mono);\n    font-weight: 700;\n    font-size: 11.5px;\n    letter-spacing: 0.05em;\n    text-transform: uppercase;\n    padding: 8px 12px;\n    border-radius: 8px;\n    cursor: pointer;\n    transition: all .15s;\n  }\n  .novo-voo-btn.dirty{ color: var(--red); }\n  .novo-voo-btn:active{ transform: translateY(1px); }\n\n  .topo-btn{\n    background: var(--bg-1);\n    border: 1px solid var(--line-bright);\n    color: var(--text-dim);\n    font-family: var(--mono);\n    font-size: 13px;\n    font-weight: 700;\n    letter-spacing: 0.08em;\n    text-transform: uppercase;\n    padding: 10px 30px;\n    border-radius: 9px;\n    cursor: pointer;\n    transition: all .15s;\n    box-shadow:\n      0 6px 14px rgba(0,0,0,0.4),\n      inset 0 1px 0 rgba(255,255,255,0.06);\n  }\n  .topo-btn:hover{ border-color: var(--amber); color: var(--amber); }\n  .topo-btn:active{ transform: translateY(1px); }\n\n  /* ---------- Panels ---------- */\n  .panel{\n    background: linear-gradient(165deg, var(--panel) 0%, var(--panel-2) 55%, #0a1c3c 100%);\n    border: 1px solid rgba(120, 170, 230, 0.4);\n    border-radius: 14px;\n    padding: 18px;\n    margin-bottom: 16px;\n    position: relative;\n    box-shadow:\n      0 22px 42px rgba(0,0,0,0.6),\n      0 10px 20px rgba(0,0,0,0.45),\n      0 2px 0 rgba(120,170,230,0.2),\n      inset 0 2px 0 rgba(255,255,255,0.12),\n      inset 0 -3px 6px rgba(0,0,0,0.4),\n      inset 0 0 0 1px rgba(255,255,255,0.04);\n  }\n  @media (min-width: 600px){\n    .panel{ margin-bottom: 22px; padding: 20px 22px; }\n  }\n  @media (min-width: 900px){\n    .panel{ margin-bottom: 28px; padding: 24px 26px; }\n  }\n  .panel::before{\n    content:'';\n    position:absolute; top:0; left:0; right:0; height:2px;\n    border-radius: 14px 14px 0 0;\n    background: linear-gradient(90deg, transparent, var(--line-bright), transparent);\n    opacity: 0.6;\n  }\n  .panel::after{\n    content: '';\n    position: absolute; bottom: 0; left: 0; right: 0; height: 14px;\n    border-radius: 0 0 14px 14px;\n    background: linear-gradient(180deg, transparent, rgba(0,0,0,0.3));\n    pointer-events: none;\n  }\n  .panel.result{\n    border-color: var(--line-bright);\n    background: linear-gradient(165deg, #1a4585 0%, #17407a 40%, #0a1c3c 100%);\n    box-shadow:\n      0 24px 46px rgba(0,0,0,0.65),\n      0 10px 20px rgba(0,0,0,0.45),\n      0 2px 0 rgba(120,170,230,0.3),\n      inset 0 2px 0 rgba(255,255,255,0.16),\n      inset 0 -3px 6px rgba(0,0,0,0.35),\n      0 0 0 1px rgba(79,143,230,0.25);\n  }\n  .panel.result > .panel-label::after{\n    content: 'RESULTADO';\n    margin-left: auto;\n    font-family: var(--disp);\n    font-size: 10.5px;\n    letter-spacing: 0.12em;\n    color: var(--line-bright);\n    background: rgba(79,143,230,0.15);\n    padding: 3px 8px;\n    border-radius: 4px;\n  }\n  .panel-label{\n    font-size: clamp(15px, 4.6vw, 18.5px);\n    font-weight: 700;\n    letter-spacing: 0.1em;\n    color: var(--text-faint);\n    text-transform: uppercase;\n    margin-bottom: 14px;\n    display:flex; align-items:center; gap:8px;\n    flex-wrap: wrap;\n  }\n  .panel-label .num{\n    color: var(--amber);\n    font-family: var(--disp);\n    font-size: 1.55em;\n    letter-spacing: 0.02em;\n  }\n\n  /* ---------- Inputs ---------- */\n  .input-row{\n    display:grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 14px;\n    margin-bottom: 4px;\n  }\n  .field{ display:flex; flex-direction:column; gap:8px; }\n  .field label{\n    font-size: 15.1px; letter-spacing:0.1em; color: var(--text-dim);\n    text-transform: uppercase;\n  }\n  .field-value{\n    font-family: var(--disp);\n    font-size: clamp(28px, 9vw, 43.1px);\n    color: var(--white);\n    letter-spacing: 0.02em;\n  }\n  .field-value .unit{ font-size: 20.1px; color: var(--text-dim); font-family: var(--mono); margin-left:4px;}\n\n  input[type=range]{\n    -webkit-appearance: none;\n    width: 100%;\n    height: 28px;\n    background: transparent;\n    margin: 2px 0;\n  }\n  input[type=range]::-webkit-slider-runnable-track{\n    height: 4px;\n    background: var(--line-bright);\n    border-radius: 2px;\n  }\n  input[type=range]::-webkit-slider-thumb{\n    -webkit-appearance:none;\n    width: 16px; height:16px;\n    margin-top: -6px;\n    background: var(--amber);\n    border-radius: 50%;\n    box-shadow: 0 0 0 4px rgba(255,196,0,0.18), 0 0 10px rgba(255,196,0,0.6);\n    cursor:pointer;\n    border: 1px solid #4a3500;\n  }\n  input[type=range]::-moz-range-track{\n    height:4px; background:var(--line-bright); border-radius:2px;\n  }\n  input[type=range]::-moz-range-thumb{\n    width:16px; height:16px; background: var(--amber); border-radius:50%; border:none;\n    box-shadow: 0 0 10px rgba(255,196,0,0.6);\n  }\n\n  .quickset{\n    display:flex; gap:6px; flex-wrap:wrap; margin-top:10px;\n  }\n  .quickset-title{\n    font-size: 13px;\n    color: var(--text-faint);\n    letter-spacing: 0.06em;\n    margin-bottom: 8px;\n  }\n  .quickset-grid{\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 6px;\n  }\n  .quickset-grid .qbtn{\n    width: 100%;\n    min-height: 42px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n  }\n  @media (max-width: 480px){\n    .quickset-grid{ grid-template-columns: repeat(2, 1fr); }\n  }\n  .qbtn{\n    background: transparent;\n    border: 1px solid var(--line-bright);\n    color: var(--text-dim);\n    font-family: var(--mono);\n    font-size: 15.1px;\n    letter-spacing: 0.06em;\n    padding: 7px 11px;\n    border-radius: 7px;\n    cursor:pointer;\n    transition: all .15s;\n    line-height: 1.3;\n    box-shadow:\n      0 4px 10px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.05);\n  }\n  .qbtn:hover{ border-color: var(--amber); color: var(--amber); }\n  .qbtn.active{ border-color: var(--amber); color: var(--bg-0); background: var(--amber); }\n  .qbtn:active{ transform: translateY(1px); }\n\n  /* flight type flag (MEDEVAC / Treinamento) */\n  .flighttype-toggle{\n    display:flex; gap:0; border-radius: 12px; overflow:hidden;\n    border: 1px solid var(--line-bright);\n    box-shadow:\n      0 10px 22px rgba(0,0,0,0.45),\n      0 3px 7px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.12),\n      inset 0 -2px 4px rgba(0,0,0,0.25);\n  }\n  .ft-btn{\n    flex:1;\n    background: var(--bg-1);\n    border: none;\n    color: var(--text-dim);\n    font-family: var(--mono);\n    cursor:pointer;\n    padding: 16px 10px;\n    display:flex; flex-direction:column; align-items:center; gap:4px;\n    transition: all .15s;\n    border-right: 1px solid var(--line-bright);\n  }\n  .ft-btn:last-child{ border-right:none; }\n  .ft-btn:active{ transform: translateY(1px); }\n\n  /* em telas pequenas, empilha MEDEVAC acima de Treinamento; em telas grandes,\n     mant\u00e9m lado a lado como j\u00e1 era */\n  @media (max-width: 480px){\n    .flighttype-toggle{ flex-direction: column; }\n    .ft-btn{ border-right: none; border-bottom: 1px solid var(--line-bright); }\n    .ft-btn:last-child{ border-bottom: none; }\n  }\n  .ft-btn-title{\n    font-family: var(--disp);\n    font-size: clamp(17px, 5.6vw, 24px);\n    letter-spacing: 0.04em;\n    text-transform: uppercase;\n    display: block;\n    width: 100%;\n    text-align: center;\n    white-space: nowrap;\n  }\n  .ft-btn-sub{\n    font-size: clamp(9.5px, 2.6vw, 11px);\n    letter-spacing: 0.02em;\n    color: var(--text-faint);\n    display: block;\n    width: 100%;\n    text-align: center;\n    white-space: nowrap;\n  }\n  .ft-btn.active{\n    background: #1e1605;\n    color: var(--white);\n    box-shadow: inset 0 0 0 2px var(--amber);\n  }\n  .ft-btn.active .ft-btn-title{ color: var(--amber); }\n  .ft-btn.active .ft-btn-sub{ color: var(--text); }\n\n  /* helideck position selector */\n  .deck-pos-row{\n    display:flex; gap:6px; margin-top: 6px; flex-wrap: wrap;\n  }\n  .deck-pos-btn{\n    flex:1; min-width: 95px;\n    background: var(--bg-1);\n    border: 1px solid var(--line);\n    color: var(--text-dim);\n    font-family: var(--mono);\n    font-size: clamp(12px, 3.6vw, 14.4px);\n    padding: 10px 8px;\n    border-radius: 7px;\n    cursor:pointer;\n    text-align:center;\n    letter-spacing: 0.04em;\n    line-height: 1.3;\n    text-transform: uppercase;\n    transition: all .15s;\n    box-shadow:\n      0 5px 12px rgba(0,0,0,0.4),\n      0 2px 4px rgba(0,0,0,0.3),\n      inset 0 1px 0 rgba(255,255,255,0.06),\n      inset 0 -1px 0 rgba(0,0,0,0.2);\n  }\n  .deck-pos-btn:active{\n    transform: translateY(1px);\n    box-shadow:\n      0 2px 6px rgba(0,0,0,0.4),\n      inset 0 1px 0 rgba(255,255,255,0.06),\n      inset 0 -1px 0 rgba(0,0,0,0.2);\n  }\n  .deck-pos-btn.active{\n    border-color: var(--amber);\n    color: var(--white);\n    background: #1e1605;\n    box-shadow: inset 0 0 0 1px var(--amber);\n  }\n  .deck-pos-btn[data-pos=\"plataforma\"]{\n    font-size: 13px;\n    letter-spacing: 0.02em;\n    padding: 7px 4px;\n    line-height: 1.5;\n  }\n\n  /* ---------- Annex menu (circuitos por tipo) ---------- */\n  .annex-menu{\n    display:grid;\n    grid-template-columns: repeat(2, 1fr);\n    gap: 8px;\n  }\n  @media (max-width: 480px){\n    .annex-menu{ grid-template-columns: 1fr; }\n  }\n  .annex-btn{\n    background: var(--bg-1);\n    border: 1px solid var(--line);\n    border-radius: 8px;\n    color: var(--text-dim);\n    font-family: var(--mono);\n    cursor:pointer;\n    padding: 14px 14px;\n    display:flex; flex-direction:column; gap:4px;\n    text-align:left;\n    transition: all .15s;\n    box-shadow:\n      0 6px 14px rgba(0,0,0,0.4),\n      0 2px 4px rgba(0,0,0,0.3),\n      inset 0 1px 0 rgba(255,255,255,0.06),\n      inset 0 -1px 0 rgba(0,0,0,0.2);\n  }\n  .annex-btn:hover{\n    border-color: var(--amber);\n  }\n  .annex-btn:active{\n    background: #1e1605;\n    transform: translateY(1px);\n    box-shadow:\n      0 3px 8px rgba(0,0,0,0.4),\n      inset 0 1px 0 rgba(255,255,255,0.06),\n      inset 0 -1px 0 rgba(0,0,0,0.2);\n  }\n  .annex-btn-title{\n    font-family: var(--disp);\n    font-size: clamp(17px, 5.2vw, 22px);\n    color: var(--white);\n    letter-spacing: 0.02em;\n    text-transform: uppercase;\n  }\n  .annex-btn-sub{\n    font-size: 13px;\n    color: var(--text-faint);\n    letter-spacing: 0.04em;\n  }\n  .annex-btn.is-placeholder .annex-btn-sub::after{\n    content: ' \u00b7 sem imagem anexada';\n    color: var(--amber-dim);\n  }\n  .annex-btn{ align-items: center; justify-content: center; text-align: center; }\n  .annex-modal-body.annex-empty{ min-height: 45vh; }\n  .annex-next-wrap{ display: flex; justify-content: center; gap: 8px; padding: 6px 0 2px; }\n  .annex-next-btn{\n    background: var(--bg-1);\n    border: 1px solid var(--amber);\n    border-radius: 5px;\n    color: var(--amber);\n    font-family: var(--mono);\n    font-size: 9.5px;\n    letter-spacing: 0.1em;\n    line-height: 1;\n    padding: 4px 10px;\n    cursor: pointer;\n  }\n  .annex-next-btn:active{ transform: translateY(1px); background: #1e1605; }\n  .annex-modal-body img + img{ margin-top: 2px; }\n  .annex-btn-title{ text-align: center; width: 100%; }\n\n  /* ---------- Annex image modal ---------- */\n  .annex-modal-overlay{\n    display:none;\n    position:fixed; top:0; left:0; right:0; bottom:0;\n    background: rgba(5,10,20,0.82);\n    z-index: 1000;\n    padding: 20px;\n    overflow-y: auto;\n  }\n  .annex-modal-overlay.open{ display:flex; align-items:flex-start; justify-content:center; }\n  .annex-modal{\n    background: var(--panel);\n    border: 1px solid var(--line-bright);\n    border-radius: 6px;\n    max-width: 720px;\n    width: 100%;\n    margin-top: 20px;\n    overflow:hidden;\n  }\n  .annex-modal-header{\n    display:flex; align-items:center; justify-content:space-between;\n    padding: 14px 18px;\n    border-bottom: 1px solid var(--line);\n    font-family: var(--disp);\n    font-size: 22px;\n    color: var(--white);\n    letter-spacing: 0.02em;\n    text-transform: uppercase;\n    position: sticky; top:0;\n    background: var(--panel);\n  }\n  .annex-modal-close{\n    background: transparent;\n    border: 1px solid var(--line-bright);\n    color: var(--text-dim);\n    border-radius: 4px;\n    width: 32px; height:32px;\n    font-size: 16px;\n    cursor:pointer;\n    flex-shrink:0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n  .annex-modal-close:hover{ border-color: var(--amber); color: var(--amber); }\n  .annex-modal-body{\n    padding: 16px;\n  }\n  .annex-modal-body img{\n    width: 100%;\n    height: auto;\n    border-radius: 4px;\n    display:block;\n  }\n  .annex-modal-placeholder{\n    padding: 40px 20px;\n    text-align:center;\n    color: var(--text-dim);\n    font-size: 15px;\n    line-height: 1.6;\n  }\n  .annex-modal-placeholder .ph-icon{\n    font-size: 40px;\n    margin-bottom: 14px;\n    color: var(--text-faint);\n  }\n\n  /* ---------- Checklists (campo 02) ---------- */\n  .clist-clear-btn{\n    background: transparent;\n    border: 1px solid var(--red-dim);\n    color: var(--red);\n    font-family: var(--mono);\n    font-size: 13px;\n    letter-spacing: 0.08em;\n    text-transform: uppercase;\n    padding: 8px 22px;\n    border-radius: 7px;\n    cursor: pointer;\n    transition: all .15s;\n    box-shadow:\n      0 4px 10px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.05);\n  }\n  .clist-clear-btn:hover{ background: rgba(255,59,59,0.12); }\n  .clist-clear-btn:active{ background: rgba(255,59,59,0.22); transform: translateY(1px); }\n  .clist-clear-btn.clist-clean{\n    border-color: var(--green-dim);\n    color: var(--green);\n  }\n  .clist-clear-btn.clist-clean:hover{ background: rgba(43,255,126,0.1); }\n\n  .clist-row{\n    display: flex;\n    gap: 10px;\n    flex-wrap: wrap;\n  }\n  .clist-btn{\n    flex: 1;\n    min-width: 150px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    gap: 8px;\n    padding: 22px 12px;\n    border-radius: 12px;\n    border: 2px solid var(--red-dim);\n    background: linear-gradient(160deg, rgba(255,59,59,0.16), var(--bg-1) 65%);\n    color: var(--white);\n    cursor: pointer;\n    text-align: center;\n    transition: all .15s;\n    box-shadow:\n      0 10px 22px rgba(0,0,0,0.45),\n      0 3px 7px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.12),\n      inset 0 -2px 4px rgba(0,0,0,0.25);\n  }\n  .clist-btn:active{ transform: translateY(1px); }\n  .clist-btn.clist-go{\n    border-color: var(--green-dim, #1c5c3a);\n    background: linear-gradient(160deg, rgba(0,200,110,0.18), var(--bg-1) 65%);\n  }\n  .clist-btn-title{\n    font-family: var(--disp);\n    font-size: clamp(16px, 5vw, 20px);\n    letter-spacing: 0.03em;\n    text-transform: uppercase;\n    line-height: 1.2;\n  }\n  .clist-btn-count{\n    font-size: 13px;\n    letter-spacing: 0.06em;\n    color: var(--text-dim);\n  }\n  .clist-btn.clist-go .clist-btn-title{ color: var(--green); }\n  .clist-btn.clist-go .clist-btn-count{ color: var(--green); }\n  .clist-btn:not(.clist-go) .clist-btn-title{ color: var(--red); }\n  .clist-btn:not(.clist-go) .clist-btn-count{ color: var(--red-dim); }\n\n  @media (max-width: 480px){\n    .clist-row{ flex-direction: column; }\n  }\n\n  /* itens dentro do modal de checklist */\n  .clist-item{\n    display: flex;\n    align-items: flex-start;\n    gap: 12px;\n    padding: 12px 4px;\n    border-bottom: 1px solid var(--line);\n    cursor: pointer;\n  }\n  .clist-item:last-child{ border-bottom: none; }\n  .clist-flag{\n    flex-shrink: 0;\n    width: 26px; height: 26px;\n    border-radius: 5px;\n    border: 2px solid var(--line-bright);\n    background: var(--bg-1);\n    display: flex; align-items:center; justify-content:center;\n    margin-top: 2px;\n    transition: all .15s;\n  }\n  .clist-flag::after{\n    content: '';\n    width: 14px; height: 14px;\n    border-radius: 2px;\n    background: transparent;\n  }\n  .clist-item.checked .clist-flag{\n    border-color: var(--green);\n    background: var(--green);\n  }\n  .clist-item.checked .clist-flag::after{\n    background: var(--bg-0);\n    clip-path: polygon(20% 45%, 38% 62%, 80% 18%, 92% 30%, 38% 86%, 8% 56%);\n  }\n  .clist-item-text{\n    font-size: 15px;\n    line-height: 1.5;\n    color: var(--text);\n  }\n  .clist-item.checked .clist-item-text{ color: var(--text-dim); }\n\n  /* ---------- Pouso / Assento (campo 06) \u2014 flags autom\u00e1ticas, somente leitura ---------- */\n  .pouso-assento-field{\n    margin-top: 14px;\n    padding-top: 12px;\n    border-top: 1px dashed var(--line);\n  }\n  .pouso-assento-label{\n    font-size: 16px;\n    font-weight: 700;\n    letter-spacing: 0.1em;\n    color: var(--text-faint);\n    text-transform: uppercase;\n    margin-bottom: 10px;\n    text-align: center;\n  }\n  .pouso-assento-flags{\n    display: flex;\n    justify-content: center;\n    gap: 32px;\n  }\n  .pouso-assento-flag{\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .pouso-assento-flag .clist-flag{\n    cursor: default;\n    margin-top: 0;\n  }\n  .pouso-assento-flag.checked .clist-flag{\n    border-color: var(--green);\n    background: var(--green);\n  }\n  .pouso-assento-flag.checked .clist-flag::after{\n    background: var(--bg-0);\n    clip-path: polygon(20% 45%, 38% 62%, 80% 18%, 92% 30%, 38% 86%, 8% 56%);\n  }\n  .pouso-assento-flag-text{\n    font-size: 14px;\n    font-weight: 700;\n    letter-spacing: 0.04em;\n    text-transform: uppercase;\n    color: var(--text-dim);\n  }\n  .pouso-assento-flag.checked .pouso-assento-flag-text{ color: var(--white); }\n\n  /* ---------- Compass / Diagram (drag-to-rotate) ---------- */\n  .compass-hint{\n    font-size: 14px; color: var(--text-dim); letter-spacing: 0.06em;\n  }\n\n  /* ---------- Diagram ---------- */\n  .diagram-wrap{\n    display:flex; justify-content:center;\n    padding: 6px 0 4px;\n  }\n  svg#deckSvg{\n    width:100%; max-width: 460px; height:auto;\n  }\n\n  .legend{\n    display:flex; justify-content:center; gap:10px;\n    font-size: 13px; font-weight: 700; color: var(--text-dim); letter-spacing: 0.05em;\n    margin-top: 4px; flex-wrap:wrap;\n  }\n  .legend > span{\n    display:inline-flex; align-items:center; gap:6px;\n    background: rgba(0,0,0,0.25);\n    border: 1px solid var(--line);\n    border-radius: 8px;\n    padding: 7px 12px;\n    box-shadow:\n      0 4px 10px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.05);\n  }\n  .swatch{ width:10px; height:10px; border-radius:2px; display:inline-block; }\n\n  /* ---------- Relat\u00f3rios (campo 10) ---------- */\n  .report-print-btn{\n    width: 100%;\n    background: linear-gradient(180deg, #244a75, #142a48);\n    border: 1px solid var(--line-bright);\n    color: var(--white);\n    font-family: var(--disp);\n    font-size: clamp(20px, 6.5vw, 25px);\n    font-weight: 700;\n    letter-spacing: 0.06em;\n    text-transform: uppercase;\n    padding: 16px;\n    border-radius: 12px;\n    cursor: pointer;\n    transition: all .15s;\n    box-shadow:\n      0 10px 22px rgba(0,0,0,0.45),\n      0 3px 7px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.12),\n      inset 0 -2px 4px rgba(0,0,0,0.25);\n  }\n  .report-print-btn:hover{ border-color: var(--amber); }\n  .report-print-btn:active{ transform: translateY(1px); }\n  .report-close-btn{\n    flex-shrink: 0;\n    width: 32px;\n    height: 32px;\n    border-radius: 9px;\n    background: var(--bg-1);\n    border: 1px solid var(--line);\n    color: var(--text-dim);\n    font-size: 15px;\n    line-height: 1;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: all .15s;\n    box-shadow:\n      0 4px 10px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.06);\n  }\n  .report-close-btn:hover{ border-color: var(--red-dim); color: var(--red); background: rgba(255,59,59,0.1); }\n  .report-close-btn:active{ transform: translateY(1px); }\n\n  .report-share-btn{\n    background: transparent;\n    border: 1px solid var(--green-dim);\n    color: var(--green);\n    font-family: var(--mono);\n    font-size: 13px;\n    letter-spacing: 0.06em;\n    text-transform: uppercase;\n    padding: 8px 26px;\n    border-radius: 10px;\n    cursor: pointer;\n    transition: all .15s;\n    box-shadow:\n      0 4px 10px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.05);\n  }\n  .report-share-btn:hover{ background: rgba(43,255,126,0.1); }\n  .report-share-btn:active{ transform: translateY(1px); }\n  .report-share-btn:disabled{ opacity: 0.4; cursor: not-allowed; }\n  .report-preview-wrap{\n    border: 1px solid var(--line);\n    border-radius: 12px;\n    overflow: hidden;\n    box-shadow:\n      0 8px 18px rgba(0,0,0,0.4),\n      inset 0 1px 0 rgba(255,255,255,0.05);\n  }\n  .report-preview-body{\n    max-height: 480px;\n    overflow-y: auto;\n    background: #fff;\n    color: #1a1a1a;\n    padding: 18px 16px;\n    font-family: 'Courier New', monospace;\n  }\n  .report-preview-body h3{\n    margin: 0 0 4px;\n    font-size: 15px;\n    color: #0a1430;\n  }\n  .report-preview-body .rp-meta{\n    font-size: 11px;\n    color: #555;\n    margin-bottom: 14px;\n  }\n  .report-preview-body .rp-section{\n    margin-top: 14px;\n    padding-top: 10px;\n    border-top: 1px solid #ddd;\n  }\n  .report-preview-body .rp-section-title{\n    font-size: 12.5px;\n    font-weight: 700;\n    color: #0a1430;\n    letter-spacing: 0.03em;\n    margin-bottom: 6px;\n    text-transform: uppercase;\n  }\n  .report-preview-body .rp-item{\n    display: flex;\n    justify-content: space-between;\n    gap: 10px;\n    font-size: 12px;\n    padding: 3px 0;\n    border-bottom: 1px dashed #eee;\n  }\n  .report-preview-body .rp-item .rp-label{ color: #444; }\n  .report-preview-body .rp-item .rp-value{ color: #111; font-weight: 500; text-align: right; }\n  .report-preview-body .rp-item .rp-value.rp-value-bold{ font-weight: 800; }\n\n\n  /* ---------- Verdict ---------- */\n  .verdict{\n    background: var(--panel);\n    border-radius: 4px;\n    padding: 20px 18px;\n    margin-bottom: 16px;\n    border: 1px solid var(--line);\n    position: relative;\n    overflow: hidden;\n  }\n  .verdict.go{\n    background: linear-gradient(135deg, rgba(43,255,126,0.14), var(--panel) 55%);\n    border-color: var(--green-dim);\n  }\n  .verdict.caution{\n    background: linear-gradient(135deg, rgba(255,196,0,0.16), var(--panel) 55%);\n    border-color: var(--amber-dim);\n  }\n  .verdict.no-go{\n    background: linear-gradient(135deg, rgba(255,59,59,0.18), var(--panel) 55%);\n    border-color: var(--red-dim);\n  }\n  .verdict-top{\n    display:flex; align-items:baseline; justify-content:space-between; gap:12px;\n    margin-bottom:10px;\n    flex-wrap: wrap;\n  }\n  .verdict-label{\n    font-family: var(--disp);\n    font-size: clamp(30px, 9.5vw, 43.1px);\n    letter-spacing: 0.02em;\n    text-transform: uppercase;\n    line-height: 1;\n  }\n  .verdict.go .verdict-label{ color: var(--green); }\n  .verdict.caution .verdict-label{ color: var(--amber); }\n  .verdict.no-go .verdict-label{ color: var(--red); }\n\n  .verdict-class{\n    font-size: 15.8px; letter-spacing: 0.1em; color: var(--text-dim);\n    text-align:right;\n  }\n  .verdict-class b{ color: var(--white); font-size: 18.6px; }\n\n  .verdict-reason{\n    font-size: 18px;\n    color: var(--text);\n    line-height: 1.55;\n  }\n  .verdict-reason b{ color: var(--white); }\n\n  .metrics{\n    display:grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 1px;\n    margin-top: 16px;\n    background: var(--line);\n    border-radius: 3px;\n    overflow: hidden;\n  }\n  .metrics.cols-4{\n    grid-template-columns: repeat(4, 1fr);\n  }\n  @media (max-width: 480px){\n    .metrics.cols-4{ grid-template-columns: repeat(2, 1fr); }\n  }\n  .metrics-centered{\n    display:flex;\n    justify-content:center;\n    margin-top: 16px;\n  }\n  .metrics-centered .metric{\n    background: rgba(0,0,0,0.25);\n    border: 1px solid var(--line);\n    border-radius: 8px;\n    padding: 14px 32px;\n    min-width: min(220px, 100%);\n    box-shadow:\n      0 6px 14px rgba(0,0,0,0.4),\n      0 2px 4px rgba(0,0,0,0.3),\n      inset 0 1px 0 rgba(255,255,255,0.06),\n      inset 0 -1px 0 rgba(0,0,0,0.2);\n  }\n\n  /* ---------- B\u00fassola de Setores (proa da UM + vento, campo 05) ---------- */\n  .sopdial{ margin-top: 4px; }\n  .sopdial-readouts{ display:flex; flex-direction:row; gap:8px; margin-bottom:14px; flex-wrap:wrap; }\n  .sopdial-readout{\n    background:#0c1119;\n    border:1px solid #24313f;\n    border-radius:12px;\n    padding:7px 8px 8px;\n    position:relative;\n    overflow:hidden;\n    flex: 1;\n    min-width: min(150px, 100%);\n    min-height: 88px;\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    box-sizing: border-box;\n    box-shadow:\n      0 8px 16px rgba(0,0,0,0.45),\n      0 2px 6px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.06),\n      inset 0 -1px 0 rgba(0,0,0,0.25);\n  }\n  .sopdial-proa-header{\n    display:flex;\n    align-items:center;\n    justify-content:space-between;\n    gap:5px;\n  }\n  .sopdial-mini-controls{\n    display:flex;\n    gap:4px;\n  }\n  .sopdial-mini-btn{\n    background: transparent;\n    border: 1px solid rgba(255,255,255,0.22);\n    color: #d8ac54;\n    font-family: 'Courier New', monospace;\n    font-size: 12px;\n    font-weight: 700;\n    width: 24px;\n    height: 24px;\n    min-width: 24px;\n    border-radius: 5px;\n    cursor: pointer;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    padding: 0;\n    line-height: 1;\n    transition: all .12s;\n    user-select: none;\n    -webkit-user-select: none;\n    touch-action: manipulation;\n  }\n  .sopdial-mini-btn:hover{ background: rgba(216,172,84,0.14); border-color: rgba(216,172,84,0.5); }\n  .sopdial-mini-btn:active{ background: rgba(216,172,84,0.28); border-color: #d8ac54; }\n  .sopdial-rlabel{\n    font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;\n    color:#a8bccb;font-weight:700;\n  }\n  .sopdial-rvalue{\n    font-family:'Courier New',monospace;\n    font-size:17px;font-weight:700;color:#d8ac54;\n    margin-top:2px;min-height:20px;\n    text-shadow:0 0 12px rgba(224,168,62,.45);\n    letter-spacing:.02em;\n  }\n  .sopdial-rsector{\n    font-size:9.5px;color:#9fb2c4;margin-top:1px;min-height:12px;\n  }\n  .sopdial-bottom-row{\n    display:flex;align-items:center;justify-content:flex-start;gap:8px;\n    margin-top:4px;\n    flex-wrap: wrap;\n  }\n  .sopdial-intensity{\n    background:#132030;\n    color:#d8ac54;\n    border:1px solid #2b3d4f;\n    border-radius:7px;\n    font-size:15px;font-weight:700;\n    font-family:'Courier New',monospace;\n    padding:5px 8px;\n    cursor:pointer;\n  }\n  .sopdial-dial-area{\n    position:relative; width:100%; aspect-ratio:1/1; touch-action:none; max-width: 380px; margin: 0 auto;\n    border-radius: 50%;\n    box-shadow:\n      0 14px 28px rgba(0,0,0,0.5),\n      0 4px 10px rgba(0,0,0,0.4),\n      inset 0 2px 3px rgba(255,255,255,0.12),\n      inset 0 -3px 6px rgba(0,0,0,0.5),\n      inset 0 0 0 6px #12202f;\n  }\n  .sopdial-dial-area svg{ width:100%; height:100%; display:block; touch-action: none; border-radius: 50%; }\n\n  .sopdial .sector-line{ stroke:#d8ac54; stroke-width:1.4; opacity:.85; }\n  .sopdial .sector-hit{ stroke:transparent; stroke-width:22; cursor:pointer; }\n  .sopdial .sector-hit:hover + .sector-line, .sopdial .sector-line.active{\n    stroke:#ffd478;stroke-width:2.2;opacity:1;\n    filter:drop-shadow(0 0 4px rgba(224,168,62,.55));\n  }\n  .sopdial .sector-dot{ fill:#d8ac54; }\n  .sopdial .sector-label{\n    font-size:10px;fill:#e7e2d5;text-anchor:middle;\n    font-weight:600;pointer-events:none;\n    paint-order:stroke;stroke:#0c1119;stroke-width:3px;\n  }\n  .sopdial .ship-drag{ cursor:grab; touch-action: none; }\n  .sopdial .ship-drag:active{ cursor:grabbing; }\n  .sopdial .wind-arrow-shaft{ stroke:#ffd23f; stroke-width:8; stroke-linecap:round; }\n  .sopdial .wind-arrow-head{ fill:#ffd23f; stroke:#7a5a00; stroke-width:1.8; }\n  .sopdial .wind-arrow-label{\n    font-size: 6.2px;\n    font-weight: 700;\n    letter-spacing: -0.3px;\n    fill: #4a3300;\n    font-family: 'Courier New', monospace;\n    pointer-events: none;\n  }\n  .sopdial .wind-arrow-hit{ stroke:transparent; stroke-width:26; cursor:grab; touch-action: none; }\n  .sopdial .wind-arrow-hit:active{ cursor:grabbing; }\n  .sopdial #sopWindArrowGroup.dragging .wind-arrow-shaft,\n  .sopdial #sopWindArrowGroup.dragging .wind-arrow-head{\n    filter:drop-shadow(0 0 6px rgba(255,210,63,.9));\n  }\n  .sopdial-controls{\n    display:flex;align-items:center;justify-content:center;gap:10px;\n    margin-top:16px;\n  }\n  .sopdial-controls button{\n    background: var(--bg-1);\n    border: 1px solid var(--line);\n    color: var(--text-dim);\n    font-family: var(--mono);\n    font-size:14px;font-weight:600;\n    padding:10px 16px;border-radius:9px;cursor:pointer;\n    transition: all .12s;\n  }\n  .sopdial-controls button:hover{ border-color: var(--amber); color: var(--amber); }\n  .sopdial-controls button:active{ transform:translateY(1px); background:#1e1605; border-color:var(--amber); color:var(--amber); }\n  .sopdial-hint{\n    text-align:center;font-size:11px;color:var(--text-faint);margin-top:10px;\n  }\n\n  .metric{\n    background: rgba(0,0,0,0.25);\n    padding: 10px 8px;\n    text-align:center;\n    border: 1px solid var(--line);\n    border-radius: 8px;\n    box-shadow:\n      0 4px 10px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.05);\n  }\n  .metric .m-label{ font-size: 11.5px; font-weight: 700; letter-spacing: 0.06em; color: var(--text-dim); text-transform:uppercase; line-height:1.3; }\n  .metric .m-value{ font-family: var(--disp); font-size: clamp(22px, 6.5vw, 31.6px); color: var(--white); margin-top: 4px; }\n  .metric .m-value.warn{ color: var(--amber); }\n  .metric .m-value.bad{ color: var(--red); }\n  .metric .m-value.good{ color: var(--green); }\n\n  /* ---------- Checklist ---------- */\n  .checklist{ list-style: none; margin:0; padding:0; font-size: 18px; line-height: 1.6; }\n  .checklist li{\n    display:flex; gap:10px; padding: 7px 0;\n    border-bottom: 1px solid var(--line);\n    color: var(--text);\n  }\n  .checklist li:last-child{ border-bottom:none; }\n  .checklist li .mark{ color: var(--amber); flex-shrink:0; }\n\n  .note{\n    font-size: 15.8px;\n    color: var(--text-dim);\n    line-height: 1.6;\n    margin-top: 12px;\n    padding-top: 12px;\n    border-top: 1px dashed var(--line);\n  }\n  .note b{ color: var(--amber-dim); color: var(--amber); }\n\n  footer{\n    text-align:center;\n    font-size: 14.4px;\n    color: var(--text-faint);\n    letter-spacing: 0.1em;\n    margin-top: 28px;\n    line-height: 1.8;\n  }\n\n  @media (max-width: 420px){\n    .input-row{ grid-template-columns: 1fr 1fr; gap: 10px; }\n    .field-value{ font-size: 34.5px; }\n  }\n\n  /* ---------- Cover ---------- */\n  /* ---------- Tripula\u00e7\u00e3o (Piloto / Co-Piloto), acima da capa ---------- */\n  .crew-row{\n    display: flex;\n    gap: 10px;\n    margin-top: 8px;\n    margin-bottom: 20px;\n  }\n  .crew-row .flog-field{ flex: 1; }\n\n  .cover{\n    position: relative;\n    border-radius: 14px;\n    margin-bottom: 18px;\n    border: 1px solid var(--line-bright);\n    box-shadow:\n      0 14px 28px rgba(0,0,0,0.45),\n      0 4px 10px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.10),\n      inset 0 -1px 0 rgba(0,0,0,0.25);\n  }\n  .cover img{\n    display:block;\n    width: 100%;\n    height: 260px;\n    object-fit: cover;\n    border-radius: 13px 13px 0 0;\n  }\n  .cover-overlay{\n    position: absolute;\n    left:0; right:0; bottom:0;\n    padding: 14px 16px 12px;\n    background: linear-gradient(180deg, rgba(10,20,48,0) 0%, rgba(10,20,48,0.92) 75%);\n    border-radius: 0 0 13px 13px;\n  }\n  .cover-title-row{\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 10px;\n  }\n  .cover-title{\n    font-family: var(--disp);\n    font-size: clamp(20px, 6.5vw, 30px);\n    color: var(--white);\n    letter-spacing: 0.03em;\n    text-transform: uppercase;\n    line-height: 1.1;\n  }\n  .cover-subtitle{\n    font-size: clamp(11px, 3.2vw, 14px);\n    color: var(--amber);\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n    margin-top: 2px;\n  }\n\n  /* ---------- Flight log fields (campo 01) ---------- */\n  .flog-row{\n    display:flex;\n    gap:10px;\n    flex-wrap:wrap;\n    margin-bottom: 12px;\n  }\n  .flog-row:last-child{ margin-bottom:0; }\n  .flog-field{\n    flex:1;\n    min-width: 64px;\n    display:flex;\n    flex-direction:column;\n    gap:6px;\n  }\n  .flog-field.flog-wide{ flex:1.6; min-width: 110px; }\n  .flog-field label{\n    font-size: 13px;\n    font-weight: 700;\n    letter-spacing: 0.08em;\n    color: var(--text-dim);\n    text-transform: uppercase;\n  }\n  .flog-field input{\n    background: var(--bg-1);\n    border: 1px solid var(--line);\n    color: var(--white);\n    font-family: var(--mono);\n    font-size: 18px;\n    padding: 9px 6px;\n    border-radius: 7px;\n    text-align: center;\n    width: 100%;\n    letter-spacing: 0.04em;\n    box-shadow:\n      0 4px 10px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.05),\n      inset 0 -1px 0 rgba(0,0,0,0.2);\n  }\n  .flog-field input:focus{ outline:none; border-color: var(--amber); }\n  .flog-field input.flog-text{ text-transform: uppercase; cursor:text; }\n  .flog-field input.flog-time{ cursor:pointer; }\n  .flog-field input.flog-computed{\n    cursor:default;\n    background: rgba(0,0,0,0.32);\n    border-style: dashed;\n  }\n  .flog-field input.flog-computed.flog-alert{ color: var(--red); border-color: var(--red-dim); }\n  .flog-field input.flog-time.flog-seq-warn{\n    border-color: var(--amber);\n    box-shadow: 0 0 0 1px var(--amber), 0 4px 10px rgba(0,0,0,0.35);\n  }\n  .flog-leg-label{\n    font-size: 13px;\n    letter-spacing: 0.1em;\n    color: var(--text-faint);\n    text-transform: uppercase;\n    margin: 2px 0 8px;\n  }\n  .flog-hr{\n    border: none;\n    border-top: 1px solid var(--line);\n    margin: 14px 0;\n  }\n  .flog-divider{\n    width: 1px;\n    align-self: stretch;\n    background: var(--line);\n    margin: 22px 2px 0;\n  }\n  .flog-clear-btn{\n    background: transparent;\n    border: 1px solid var(--red-dim);\n    color: var(--red);\n    font-family: var(--mono);\n    font-size: 13px;\n    letter-spacing: 0.08em;\n    text-transform: uppercase;\n    padding: 8px 22px;\n    border-radius: 7px;\n    cursor: pointer;\n    transition: all .15s;\n    box-shadow:\n      0 4px 10px rgba(0,0,0,0.35),\n      inset 0 1px 0 rgba(255,255,255,0.05);\n  }\n  .flog-clear-btn.flog-clean{\n    border-color: var(--green-dim);\n    color: var(--green);\n  }\n  .flog-clear-btn.flog-clean:hover{ background: rgba(43,255,126,0.1); }\n  .flog-clear-btn:hover{ background: rgba(255,59,59,0.12); }\n  .flog-clear-btn:active{ background: rgba(255,59,59,0.22); transform: translateY(1px); }\n\n\n    #panel-07 .wcc-wrap { position: relative; width: 100%; line-height: 0; background: #fff; border-radius: 6px; overflow: hidden; margin-bottom: 14px; }\n    #panel-07 .wcc-img  { display: block; width: 100%; height: auto; }\n    #panel-07 .wcc-svg  { position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; }\n    #panel-07 .wcc-row1 { display: flex; gap: 12px; margin-bottom: 12px; flex-wrap: wrap; }\n    #panel-07 .wcc-field { flex: 1; min-width: 160px; }\n    #panel-07 .wcc-field-label { font-size: 13px; color: var(--muted, #7f93a8); letter-spacing: .5px; margin-bottom: 5px; text-transform: uppercase; }\n    #panel-07 .wcc-field input, #panel-07 .wcc-field select {\n      background: #0a111c; border: 1px solid #1e3550; color: #c8d8e8;\n      font-size: 15px; padding: 10px 12px; border-radius: 6px; width: 100%; outline: none; box-sizing: border-box;\n    }\n    #panel-07 .wcc-btn-row { display: flex; justify-content: center; gap: 12px; margin-bottom: 14px; }\n    #panel-07 .wcc-btn-row .flog-clear-btn { min-width: 130px; text-align: center; }\n    #panel-07 .wcc-error { background: #1a0808; border: 1px solid #cc2222; border-radius: 6px; padding: 10px 14px; font-size: 12px; color: #ff6666; margin-bottom: 14px; text-align: center; display: none; }\n    #panel-07 .wcc-warning { background: #1a1508; border: 1px solid #cc8822; border-radius: 6px; padding: 10px 14px; font-size: 12px; color: #ffb84d; margin-bottom: 14px; text-align: center; display: none; }\n    #panel-07 .wcc-result { background: #0d1520; border: 1px solid #1a305044; border-left: 3px solid #1a3050; border-radius: 6px; padding: 14px 18px; }\n    #panel-07 .wcc-result.active { background: rgba(0,80,200,0.08); border-color: #0055cc88; border-left-color: #0055cc; }\n    #panel-07 .wcc-result-title {\n      font-size: 14px; font-weight: 800; color: #4fc3ff; letter-spacing: 2px; margin-bottom: 10px; text-align: center;\n      text-transform: uppercase;\n      text-shadow:\n        0 1px 0 #0a3a5c,\n        0 2px 0 #072a44,\n        0 3px 4px rgba(0,0,0,0.6),\n        0 0 14px rgba(79,195,255,0.5);\n    }\n    #panel-07 .wcc-result-inner { display: flex; gap: 20px; justify-content: center; flex-wrap: wrap; align-items: center; }\n    #panel-07 .wcc-result-col { text-align: center; }\n    #panel-07 .wcc-result-col + .wcc-result-col { border-left: 1px solid #1a3050; padding-left: 20px; }\n    #panel-07 .wcc-big-num { font-size: 32px; font-weight: 700; line-height: 1; }\n    #panel-07 .wcc-mid-num { font-size: 24px; font-weight: 700; }\n    #panel-07 .wcc-hint { font-size: 12px; color: #5a9aff; margin-top: 4px; }\n    #panel-07 .wcc-placeholder { font-size: 12px; color: #3a5a7a; text-align: center; padding: 8px 0; }\n    #panel-07 {\n      overflow: hidden;\n      border: 1px solid rgba(120, 170, 230, 0.55);\n      background: linear-gradient(165deg, #1a3f72 0%, #122c56 45%, #0a1c3c 100%);\n      box-shadow:\n        0 22px 42px rgba(0,0,0,0.6),\n        0 10px 20px rgba(0,0,0,0.45),\n        0 2px 0 rgba(120,170,230,0.25),\n        inset 0 2px 0 rgba(255,255,255,0.14),\n        inset 0 -3px 6px rgba(0,0,0,0.4),\n        inset 0 0 0 1px rgba(255,255,255,0.04);\n    }\n    #panel-07 .sopdial-readout { justify-content: flex-start; }\n    #panel-07 .wcc-limit-banner {\n      display: none;\n      margin-top: 14px;\n      padding: 14px 18px;\n      background: #2a0000;\n      border-top: 2px solid #ff0000;\n      border-bottom: 2px solid #ff0000;\n      color: #ff2222;\n      font-weight: 800;\n      font-size: 13px;\n      letter-spacing: .04em;\n      text-align: center;\n      text-transform: uppercase;\n      line-height: 1.5;\n      box-sizing: border-box;\n    }\n  \n/* sem foto de capa */\n.cover .cover-overlay{position:static;background:none;border-radius:13px}\n", "body": "\n\n<!-- ===================== BARRA FIXA: VOLTAR + \u00cdNDICE DE NAVEGA\u00c7\u00c3O + ALERTA ===================== -->\n<div class=\"topbar\" id=\"topbar\">\n  <div class=\"topbar-row\">\n    <button type=\"button\" class=\"ndl-back-btn\" id=\"ndlBackBtn\">&#8592; Voltar</button>\n    <select class=\"topnav-select\" id=\"topnavSelect\">\n      <option value=\"01\">01 \u2014 Registro de Hor\u00e1rios e Trajeto</option>\n      <option value=\"02\">02 \u2014 Checklists</option>\n      <option value=\"03\">03 \u2014 Tipo de Voo</option>\n      <option value=\"04\">04 \u2014 Posi\u00e7\u00e3o do helideque na UM</option>\n      <option value=\"05\">05 \u2014 Proa da UM &amp; Vento</option>\n      <option value=\"06\">06 \u2014 B\u00fassola (SLO e vento)</option>\n      <option value=\"07\">07 \u2014 Gr\u00e1fico de Componentes de Vento</option>\n      <option value=\"08\">08 \u2014 Limites de Movimento</option>\n      <option value=\"09\">09 \u2014 Circuitos de Tr\u00e1fego</option>\n      <option value=\"10\">10 \u2014 Relat\u00f3rios</option>\n    </select>\n  </div>\n  <div class=\"topbar-alert\" id=\"topbarAlert\" style=\"display:none;\">AUTORIZA\u00c7\u00c3O DO GESTOR PENDENTE</div>\n\n</div>\n\n\n<div class=\"scope\">\n\n  <!-- ===================== COVER ===================== -->\n  <div class=\"cover\">\n    <div class=\"cover-overlay\">\n      <div class=\"cover-title-row\">\n        <div class=\"cover-title\">NDL - Night Deck Landing</div>\n        <button type=\"button\" class=\"novo-voo-btn\" id=\"novoVooBtn\">Novo Voo</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- ===================== TRIPULA\u00c7\u00c3O (entre a capa e o campo 01) ===================== -->\n  <div class=\"crew-row\">\n    <div class=\"flog-field\">\n      <label for=\"crewPiloto\">Piloto</label>\n      <input type=\"text\" id=\"crewPiloto\" class=\"flog-text\">\n    </div>\n    <div class=\"flog-field\">\n      <label for=\"crewCoPiloto\">Co-Piloto</label>\n      <input type=\"text\" id=\"crewCoPiloto\" class=\"flog-text\">\n    </div>\n  </div>\n\n  <!-- ===================== FLIGHT LOG PANEL ===================== -->\n  <div class=\"panel\" id=\"panel-01\">\n    <div class=\"panel-label\"><span class=\"num\">01</span> Registro de Hor\u00e1rios e Trajeto</div>\n\n    <div class=\"flog-row\">\n      <div class=\"flog-field\" style=\"max-width:160px;\">\n        <label for=\"flogAcionamento\">Acionamento</label>\n        <input type=\"text\" id=\"flogAcionamento\" class=\"flog-time\" maxlength=\"5\" inputmode=\"numeric\">\n      </div>\n      <div class=\"flog-field\" style=\"max-width:160px; margin-left:auto;\">\n        <label for=\"flogCronometro\">Cron\u00f4metro</label>\n        <input type=\"text\" id=\"flogCronometro\" class=\"flog-computed\" readonly value=\"--:--:--\">\n      </div>\n    </div>\n\n    <hr class=\"flog-hr\">\n\n    <div class=\"flog-leg-label\">1\u00aa Perna</div>\n    <div class=\"flog-row\">\n      <div class=\"flog-field\">\n        <label for=\"flogOrigem1\">Origem</label>\n        <input type=\"text\" id=\"flogOrigem1\" class=\"flog-text\" maxlength=\"4\">\n      </div>\n      <div class=\"flog-field\">\n        <label for=\"flogDestino1\">Destino</label>\n        <input type=\"text\" id=\"flogDestino1\" class=\"flog-text\" maxlength=\"4\">\n      </div>\n      <div class=\"flog-divider\"></div>\n      <div class=\"flog-field\">\n        <label for=\"flogPartida1\">Partida</label>\n        <input type=\"text\" id=\"flogPartida1\" class=\"flog-time\" maxlength=\"5\" inputmode=\"numeric\">\n      </div>\n      <div class=\"flog-field\">\n        <label for=\"flogDecolagem1\">Decolagem</label>\n        <input type=\"text\" id=\"flogDecolagem1\" class=\"flog-time\" maxlength=\"5\" inputmode=\"numeric\">\n      </div>\n      <div class=\"flog-field\">\n        <label for=\"flogPouso1\">Pouso</label>\n        <input type=\"text\" id=\"flogPouso1\" class=\"flog-time\" maxlength=\"5\" inputmode=\"numeric\">\n      </div>\n      <div class=\"flog-field\">\n        <label for=\"flogCorte1\">Corte</label>\n        <input type=\"text\" id=\"flogCorte1\" class=\"flog-time\" maxlength=\"5\" inputmode=\"numeric\">\n      </div>\n    </div>\n\n    <hr class=\"flog-hr\">\n\n    <div class=\"flog-leg-label\">2\u00aa Perna</div>\n    <div class=\"flog-row\">\n      <div class=\"flog-field\">\n        <label for=\"flogOrigem2\">Origem</label>\n        <input type=\"text\" id=\"flogOrigem2\" class=\"flog-text\" maxlength=\"4\">\n      </div>\n      <div class=\"flog-field\">\n        <label for=\"flogDestino2\">Destino</label>\n        <input type=\"text\" id=\"flogDestino2\" class=\"flog-text\" maxlength=\"4\">\n      </div>\n      <div class=\"flog-divider\"></div>\n      <div class=\"flog-field\">\n        <label for=\"flogPartida2\">Partida</label>\n        <input type=\"text\" id=\"flogPartida2\" class=\"flog-time\" maxlength=\"5\" inputmode=\"numeric\">\n      </div>\n      <div class=\"flog-field\">\n        <label for=\"flogDecolagem2\">Decolagem</label>\n        <input type=\"text\" id=\"flogDecolagem2\" class=\"flog-time\" maxlength=\"5\" inputmode=\"numeric\">\n      </div>\n      <div class=\"flog-field\">\n        <label for=\"flogPouso2\">Pouso</label>\n        <input type=\"text\" id=\"flogPouso2\" class=\"flog-time\" maxlength=\"5\" inputmode=\"numeric\">\n      </div>\n      <div class=\"flog-field\">\n        <label for=\"flogCorte2\">Corte</label>\n        <input type=\"text\" id=\"flogCorte2\" class=\"flog-time\" maxlength=\"5\" inputmode=\"numeric\">\n      </div>\n    </div>\n\n    <hr class=\"flog-hr\">\n\n    <div class=\"flog-row\">\n      <div class=\"flog-field\" style=\"max-width:200px;\">\n        <label for=\"flogTempoDecolagem\" style=\"white-space:nowrap;\">Tempo para Decolagem</label>\n        <input type=\"text\" id=\"flogTempoDecolagem\" class=\"flog-computed\" readonly>\n      </div>\n    </div>\n\n    <div style=\"display:flex; justify-content:center; margin-top:14px;\">\n      <button type=\"button\" class=\"flog-clear-btn\" id=\"flogClearBtn\">Limpar</button>\n    </div>\n  </div>\n\n  <!-- ===================== CHECKLISTS PANEL ===================== -->\n  <div class=\"panel\" id=\"panel-02\">\n    <div class=\"panel-label\"><span class=\"num\">02</span> Checklists</div>\n\n    <div class=\"clist-row\">\n      <button type=\"button\" class=\"clist-btn\" id=\"clistBtnGestor\" data-clist=\"gestor\">\n        <span class=\"clist-btn-title\">Autoriza\u00e7\u00e3o do Gestor</span>\n        <span class=\"clist-btn-count\" id=\"clistCountGestor\">0/1</span>\n      </button>\n      <button type=\"button\" class=\"clist-btn\" id=\"clistBtnVoo\" data-clist=\"voo\">\n        <span class=\"clist-btn-title\">Prepara\u00e7\u00e3o para o Voo</span>\n        <span class=\"clist-btn-count\" id=\"clistCountVoo\">0/9</span>\n      </button>\n      <button type=\"button\" class=\"clist-btn\" id=\"clistBtnAeronave\" data-clist=\"aeronave\">\n        <span class=\"clist-btn-title\">Prepara\u00e7\u00e3o da Aeronave</span>\n        <span class=\"clist-btn-count\" id=\"clistCountAeronave\">0/6</span>\n      </button>\n    </div>\n\n    <div style=\"display:flex; justify-content:center; margin-top:14px;\">\n      <button type=\"button\" class=\"clist-clear-btn\" id=\"clistClearBtn\">Limpar</button>\n    </div>\n  </div>\n\n  <!-- ===================== FLIGHT TYPE PANEL ===================== -->\n  <div class=\"panel\" id=\"panel-03\">\n    <div class=\"panel-label\"><span class=\"num\">03</span> Tipo de Voo</div>\n    <div class=\"flighttype-toggle\" id=\"flightTypeToggle\">\n      <button class=\"ft-btn\" data-type=\"medevac\">\n        <span class=\"ft-btn-title\">MEDEVAC</span>\n        <span class=\"ft-btn-sub\">Limite de trav\u00e9s: 20 kt</span>\n      </button>\n      <button class=\"ft-btn\" data-type=\"treinamento\">\n        <span class=\"ft-btn-title\">Treinamento</span>\n        <span class=\"ft-btn-sub\">Limite de trav\u00e9s: 10 kt</span>\n      </button>\n    </div>\n  </div>\n\n  <!-- ===================== INPUT PANEL ===================== -->\n  <div class=\"panel\" id=\"panel-04\">\n    <div class=\"panel-label\"><span class=\"num\">04</span> Posi\u00e7\u00e3o do helideque na UM</div>\n    <div class=\"deck-pos-row\" id=\"deckPosRow\">\n      <button class=\"deck-pos-btn\" data-pos=\"plataforma\">Plataformas</button>\n      <button class=\"deck-pos-btn\" data-pos=\"fpso\">FPSO</button>\n      <button class=\"deck-pos-btn\" data-pos=\"popa\">Popa</button>\n      <button class=\"deck-pos-btn\" data-pos=\"meianau\">Meia-nau</button>\n      <button class=\"deck-pos-btn\" data-pos=\"proa\">Proa</button>\n      <button class=\"deck-pos-btn\" data-pos=\"superestrutura\">Acima da Superestr.</button>\n    </div>\n    <div class=\"note\" style=\"margin-top:14px; padding-top:10px;\">\n      Define a <b>classe certificada</b> do helideque (NORMAM-223/DPC): Plataformas/FPSO/FSU/navios-tanque convertidos \u2192 Classe 1 \u00b7 Popa/meia-nau \u2192 Classe 2 \u00b7 Proa/acima da superestrutura \u2192 Classe 3. O FPSO \u00e9 tratado como UM de classe 1 com helideque na popa, exigindo proa da UM e vento (dire\u00e7\u00e3o/intensidade) para o c\u00e1lculo do SLO e dos limites de movimento (item 6.8).\n    </div>\n\n    <div class=\"metrics-centered\">\n      <div class=\"metric\">\n        <div class=\"m-label\">Classe certificada da UM</div>\n        <div class=\"m-value\" id=\"baseClassOut\">\u2014</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"panel\" id=\"panel-05\">\n    <div class=\"panel-label\"><span class=\"num\">05</span> Proa da UM &amp; Vento \u2014 B\u00fassola de Setores</div>\n\n    <div class=\"sopdial\">\n      <div class=\"sopdial-readouts\">\n        <div class=\"sopdial-readout sopdial-readout-proa\">\n          <div class=\"sopdial-proa-header\">\n            <div class=\"sopdial-rlabel\">Proa da UM</div>\n            <div class=\"sopdial-mini-controls\">\n              <button type=\"button\" id=\"sopMiniMinus\" class=\"sopdial-mini-btn\" aria-label=\"Diminuir 1 grau\">&lt;</button>\n              <button type=\"button\" id=\"sopMiniZero\" class=\"sopdial-mini-btn\" aria-label=\"Zerar\">0</button>\n              <button type=\"button\" id=\"sopMiniPlus\" class=\"sopdial-mini-btn\" aria-label=\"Aumentar 1 grau\">&gt;</button>\n            </div>\n          </div>\n          <input type=\"text\" inputmode=\"numeric\" id=\"sopProaValue\" class=\"sopdial-rvalue\" value=\"000\u00b0\" maxlength=\"5\" autocomplete=\"off\" aria-label=\"Proa da UM\" style=\"background:transparent;border:none;padding:0;width:100%;\">\n          <div class=\"sopdial-rsector\" id=\"sopProaCompass\">Norte</div>\n        </div>\n        <div class=\"sopdial-readout sopdial-readout-wind\">\n          <div class=\"sopdial-proa-header\">\n            <div class=\"sopdial-rlabel\">Dire\u00e7\u00e3o do vento</div>\n            <div class=\"sopdial-mini-controls\">\n              <button type=\"button\" id=\"sopWindMiniMinus\" class=\"sopdial-mini-btn\" aria-label=\"Diminuir 1 grau\">&lt;</button>\n              <button type=\"button\" id=\"sopWindMiniZero\" class=\"sopdial-mini-btn\" aria-label=\"Zerar\">0</button>\n              <button type=\"button\" id=\"sopWindMiniPlus\" class=\"sopdial-mini-btn\" aria-label=\"Aumentar 1 grau\">&gt;</button>\n            </div>\n          </div>\n          <input type=\"text\" inputmode=\"numeric\" id=\"sopWindValue\" class=\"sopdial-rvalue\" value=\"\u2014\" maxlength=\"7\" autocomplete=\"off\" aria-label=\"Dire\u00e7\u00e3o do vento\" style=\"background:transparent;border:none;padding:0;width:100%;\">\n          <div class=\"sopdial-bottom-row\">\n            <div class=\"sopdial-rsector\" id=\"sopWindSector\">toque em um setor</div>\n            <select id=\"sopWindIntensity\" class=\"sopdial-intensity\"></select>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"sopdial-dial-area\">\n        <svg viewBox=\"0 0 460 460\" id=\"sopSvgRoot\">\n          <g id=\"sopWorldGroup\" transform=\"translate(30,30)\">\n            <circle cx=\"200\" cy=\"200\" r=\"188\" fill=\"#0c1119\" stroke=\"#22303e\" stroke-width=\"2\"/>\n            <g id=\"sopTicks\"></g>\n            <g id=\"sopCardinals\"></g>\n            <polygon points=\"200,10 192,26 208,26\" fill=\"#d8ac54\"/>\n            <circle cx=\"200\" cy=\"200\" r=\"182\" fill=\"transparent\" class=\"ship-drag ship-drag-hit\"/>\n            <g id=\"sopShipGroup\"></g>\n            <circle cx=\"200\" cy=\"200\" r=\"3.5\" fill=\"#d8ac54\"/>\n            <g id=\"sopWindArrowGroup\"></g>\n          </g>\n        </svg>\n      </div>\n    </div>\n  </div>\n\n  <!-- ===================== DIAGRAM / COMPASS ===================== -->\n  <div class=\"panel result\" id=\"panel-06\">\n    <div class=\"panel-label\"><span class=\"num\">06</span> B\u00fassola \u2014 proa da UM, SLO e vento</div>\n    <div class=\"diagram-wrap\">\n      <svg id=\"deckSvg\" viewBox=\"0 0 440 470\"></svg>\n    </div>\n    <div class=\"legend\">\n      <span><span class=\"swatch\" style=\"background:#2bff7e;opacity:.8\"></span>SLO \u2014 \u00e1rea livre (aproxima\u00e7\u00e3o v\u00e1lida)</span>\n      <span><span class=\"swatch\" style=\"background:#ff3b3b;opacity:.8\"></span>Setor restrito (n\u00e3o aproximar)</span>\n      <span><span class=\"swatch\" style=\"background:#ffc400\"></span>Vento / proa de aproxima\u00e7\u00e3o</span>\n    </div>\n\n    <div class=\"pouso-assento-field\">\n      <div class=\"pouso-assento-label\">Pouso / Assento</div>\n      <div class=\"pouso-assento-flags\">\n        <div class=\"pouso-assento-flag\" id=\"pouseAssentoEsquerda\">\n          <div class=\"clist-flag\"></div>\n          <div class=\"pouso-assento-flag-text\">Esquerda</div>\n        </div>\n        <div class=\"pouso-assento-flag\" id=\"pouseAssentoDireita\">\n          <div class=\"clist-flag\"></div>\n          <div class=\"pouso-assento-flag-text\">Direita</div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ===================== VERDICT ===================== -->\n  <div class=\"panel verdict\" id=\"verdictPanel\">\n    <div class=\"verdict-top\">\n      <div class=\"verdict-label\" id=\"verdictLabel\">\u2014</div>\n      <div class=\"verdict-class\">Classe operacional<br><b id=\"verdictClass\">\u2014</b></div>\n    </div>\n    <div class=\"verdict-reason\" id=\"verdictReason\">Ajuste os campos acima.</div>\n\n    <div class=\"metrics\">\n      <div class=\"metric\">\n        <div class=\"m-label\" style=\"font-weight:700;\">Vento de trav\u00e9s</div>\n        <div class=\"m-value\" id=\"metricCross\" style=\"font-size:22px;\">0 kt</div>\n      </div>\n      <div class=\"metric\">\n        <div class=\"m-label\" style=\"font-weight:700;\">Componente</div>\n        <div class=\"m-value\" id=\"metricComponent\" style=\"font-size:22px;\">\u2014</div>\n      </div>\n      <div class=\"metric\">\n        <div class=\"m-label\" style=\"font-weight:700;\">Limite (treino NDL)</div>\n        <div class=\"m-value\" id=\"metricLimit\" style=\"font-size:22px;\">10 kt</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ===================== WIND COMPONENT CHART (AW139 QRH) ===================== -->\n  <style>\n    #panel-07 .wcc-wrap { position: relative; width: 100%; line-height: 0; background: #fff; border-radius: 6px; overflow: hidden; margin-bottom: 14px; }\n    #panel-07 .wcc-img  { display: block; width: 100%; height: auto; }\n    #panel-07 .wcc-svg  { position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; }\n    #panel-07 .wcc-row1 { display: flex; gap: 12px; margin-bottom: 12px; flex-wrap: wrap; }\n    #panel-07 .wcc-field { flex: 1; min-width: 160px; }\n    #panel-07 .wcc-field-label { font-size: 13px; color: var(--muted, #7f93a8); letter-spacing: .5px; margin-bottom: 5px; text-transform: uppercase; }\n    #panel-07 .wcc-field input, #panel-07 .wcc-field select {\n      background: #0a111c; border: 1px solid #1e3550; color: #c8d8e8;\n      font-size: 15px; padding: 10px 12px; border-radius: 6px; width: 100%; outline: none; box-sizing: border-box;\n    }\n    #panel-07 .wcc-btn-row { display: flex; justify-content: center; gap: 12px; margin-bottom: 14px; }\n    #panel-07 .wcc-btn-row .flog-clear-btn { min-width: 130px; text-align: center; }\n    #panel-07 .wcc-error { background: #1a0808; border: 1px solid #cc2222; border-radius: 6px; padding: 10px 14px; font-size: 12px; color: #ff6666; margin-bottom: 14px; text-align: center; display: none; }\n    #panel-07 .wcc-warning { background: #1a1508; border: 1px solid #cc8822; border-radius: 6px; padding: 10px 14px; font-size: 12px; color: #ffb84d; margin-bottom: 14px; text-align: center; display: none; }\n    #panel-07 .wcc-result { background: #0d1520; border: 1px solid #1a305044; border-left: 3px solid #1a3050; border-radius: 6px; padding: 14px 18px; }\n    #panel-07 .wcc-result.active { background: rgba(0,80,200,0.08); border-color: #0055cc88; border-left-color: #0055cc; }\n    #panel-07 .wcc-result-title {\n      font-size: 14px; font-weight: 800; color: #4fc3ff; letter-spacing: 2px; margin-bottom: 10px; text-align: center;\n      text-transform: uppercase;\n      text-shadow:\n        0 1px 0 #0a3a5c,\n        0 2px 0 #072a44,\n        0 3px 4px rgba(0,0,0,0.6),\n        0 0 14px rgba(79,195,255,0.5);\n    }\n    #panel-07 .wcc-result-inner { display: flex; gap: 20px; justify-content: center; flex-wrap: wrap; align-items: center; }\n    #panel-07 .wcc-result-col { text-align: center; }\n    #panel-07 .wcc-result-col + .wcc-result-col { border-left: 1px solid #1a3050; padding-left: 20px; }\n    #panel-07 .wcc-big-num { font-size: 32px; font-weight: 700; line-height: 1; }\n    #panel-07 .wcc-mid-num { font-size: 24px; font-weight: 700; }\n    #panel-07 .wcc-hint { font-size: 12px; color: #5a9aff; margin-top: 4px; }\n    #panel-07 .wcc-placeholder { font-size: 12px; color: #3a5a7a; text-align: center; padding: 8px 0; }\n    #panel-07 {\n      overflow: hidden;\n      border: 1px solid rgba(120, 170, 230, 0.55);\n      background: linear-gradient(165deg, #1a3f72 0%, #122c56 45%, #0a1c3c 100%);\n      box-shadow:\n        0 22px 42px rgba(0,0,0,0.6),\n        0 10px 20px rgba(0,0,0,0.45),\n        0 2px 0 rgba(120,170,230,0.25),\n        inset 0 2px 0 rgba(255,255,255,0.14),\n        inset 0 -3px 6px rgba(0,0,0,0.4),\n        inset 0 0 0 1px rgba(255,255,255,0.04);\n    }\n    #panel-07 .sopdial-readout { justify-content: flex-start; }\n    #panel-07 .wcc-limit-banner {\n      display: none;\n      margin-top: 14px;\n      padding: 14px 18px;\n      background: #2a0000;\n      border-top: 2px solid #ff0000;\n      border-bottom: 2px solid #ff0000;\n      color: #ff2222;\n      font-weight: 800;\n      font-size: 13px;\n      letter-spacing: .04em;\n      text-align: center;\n      text-transform: uppercase;\n      line-height: 1.5;\n      box-sizing: border-box;\n    }\n  </style>\n\n  <div class=\"panel\" id=\"panel-07\">\n    <div class=\"panel-label\"><span class=\"num\">07</span> Gr\u00e1fico de Componentes de Vento</div>\n\n    <div class=\"wcc-wrap\">\n      <img id=\"wccChartImg\" class=\"wcc-img\" src=\"data:image/jpeg;base64,\" alt=\"AW139 Wind Component Chart\">\n      <svg id=\"wccSvgOverlay\" class=\"wcc-svg\" viewBox=\"0 0 1453 1340\"></svg>\n    </div>\n\n    <div class=\"sopdial-readouts\" style=\"margin-bottom:14px;\">\n      <div class=\"sopdial-readout\">\n        <div class=\"sopdial-proa-header\">\n          <div class=\"sopdial-rlabel\">Proa de Aproxima\u00e7\u00e3o</div>\n          <div class=\"sopdial-mini-controls\">\n            <button type=\"button\" id=\"wccHdgMiniMinus\" class=\"sopdial-mini-btn\" aria-label=\"Diminuir 1 grau\">&lt;</button>\n            <button type=\"button\" id=\"wccHdgMiniZero\" class=\"sopdial-mini-btn\" aria-label=\"Zerar\">0</button>\n            <button type=\"button\" id=\"wccHdgMiniPlus\" class=\"sopdial-mini-btn\" aria-label=\"Aumentar 1 grau\">&gt;</button>\n          </div>\n        </div>\n        <input type=\"text\" inputmode=\"numeric\" id=\"wccInpHdg\" class=\"sopdial-rvalue\" style=\"background:transparent;border:none;padding:0;width:100%;\">\n      </div>\n      <div class=\"sopdial-readout\">\n        <div class=\"sopdial-proa-header\">\n          <div class=\"sopdial-rlabel\">Dire\u00e7\u00e3o do Vento</div>\n          <div class=\"sopdial-mini-controls\">\n            <button type=\"button\" id=\"wccDirMiniMinus\" class=\"sopdial-mini-btn\" aria-label=\"Diminuir 1 grau\">&lt;</button>\n            <button type=\"button\" id=\"wccDirMiniZero\" class=\"sopdial-mini-btn\" aria-label=\"Zerar\">0</button>\n            <button type=\"button\" id=\"wccDirMiniPlus\" class=\"sopdial-mini-btn\" aria-label=\"Aumentar 1 grau\">&gt;</button>\n          </div>\n        </div>\n        <input type=\"text\" inputmode=\"numeric\" id=\"wccInpDir\" class=\"sopdial-rvalue\" style=\"background:transparent;border:none;padding:0;width:100%;\">\n        <div class=\"sopdial-bottom-row\" style=\"justify-content:flex-end;\">\n          <select id=\"wccInpSpd\" class=\"sopdial-intensity\"></select>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"wcc-btn-row\">\n      <button type=\"button\" class=\"flog-clear-btn\" id=\"wccCalcBtn\">Calcular</button>\n      <button type=\"button\" class=\"flog-clear-btn\" id=\"wccClearBtn\">Limpar</button>\n    </div>\n\n    <div class=\"wcc-error\" id=\"wccErrorBox\"></div>\n    <div class=\"wcc-warning\" id=\"wccWarningBox\"></div>\n\n    <div class=\"wcc-result\" id=\"wccPanelResult\">\n      <div class=\"wcc-result-title\">RESULTADOS</div>\n      <div id=\"wccResultContent\">\n        <div class=\"wcc-placeholder\">Preencha os campos acima e toque em CALCULAR</div>\n      </div>\n    </div>\n\n    <div class=\"wcc-limit-banner\" id=\"wccLimitBanner\"></div>\n  </div>\n\n  <!-- ===================== HELIDECK MOTION LIMITS (6.8) ===================== -->\n  <div class=\"panel result\" id=\"panel-08\">\n    <div class=\"panel-label\"><span class=\"num\">08</span> Limites de Movimento do Helideque</div>\n\n    <div class=\"note\" style=\"margin-bottom:14px;\">\n      Insira os valores de movimento da UM informados no Helideck Report (ou medidos a bordo). O app compara com os limites da NORMAM-223/DPC aplic\u00e1veis ao <b>tipo de voo</b> e \u00e0 <b>classe do helideque</b> j\u00e1 calculados acima, sempre em opera\u00e7\u00e3o <b>noturna</b>.\n    </div>\n\n    <div class=\"metrics\" style=\"margin-bottom:14px;\">\n      <div class=\"metric\">\n        <div class=\"m-label\">Tipo de voo</div>\n        <div class=\"m-value\" id=\"motionFlightTypeOut\" style=\"font-size:18px;\">\u2014</div>\n      </div>\n      <div class=\"metric\">\n        <div class=\"m-label\">Classe da UM</div>\n        <div class=\"m-value\" id=\"motionClassOut\" style=\"font-size:18px;\">\u2014</div>\n      </div>\n      <div class=\"metric\">\n        <div class=\"m-label\">Tabela aplic\u00e1vel</div>\n        <div class=\"m-value\" id=\"motionTableOut\" style=\"font-size:14px;\">\u2014</div>\n      </div>\n    </div>\n\n    <div class=\"quickset\" id=\"heliCategoryRow\" style=\"margin-bottom:14px;\">\n      <span style=\"font-size:13px;color:var(--text-faint);letter-spacing:.06em;align-self:center;margin-right:4px;\">CATEGORIA DO HELIC\u00d3PTERO:</span>\n      <button class=\"qbtn\" data-cat=\"A\">CATEGORIA A</button>\n      <button class=\"qbtn\" data-cat=\"B\">CATEGORIA B</button>\n    </div>\n\n    <div class=\"input-row\">\n      <div class=\"field\">\n        <label for=\"motionBC\">Pitch e Roll</label>\n        <div class=\"field-value\"><span id=\"motionBCVal\">0,0</span><span class=\"unit\">\u00b0</span></div>\n        <input type=\"range\" id=\"motionBC\" min=\"0\" max=\"60\" value=\"0\" step=\"1\">\n      </div>\n      <div class=\"field\">\n        <label for=\"motionInc\">Inclina\u00e7\u00e3o</label>\n        <div class=\"field-value\"><span id=\"motionIncVal\">0,0</span><span class=\"unit\">\u00b0</span></div>\n        <input type=\"range\" id=\"motionInc\" min=\"0\" max=\"60\" value=\"0\" step=\"1\">\n      </div>\n    </div>\n\n    <div class=\"input-row\" style=\"margin-top:14px;\">\n      <div class=\"field\">\n        <label for=\"motionVArf\">Heave Rate</label>\n        <div class=\"field-value\"><span id=\"motionVArfVal\">0,0</span><span class=\"unit\">m/s</span></div>\n        <input type=\"range\" id=\"motionVArf\" min=\"0\" max=\"30\" value=\"0\" step=\"1\">\n      </div>\n      <div class=\"field\">\n        <label for=\"motionArf\">Heave</label>\n        <div class=\"field-value\"><span id=\"motionArfVal\">0,0</span><span class=\"unit\">m</span></div>\n        <input type=\"range\" id=\"motionArf\" min=\"0\" max=\"80\" value=\"0\" step=\"1\">\n      </div>\n    </div>\n\n    <div class=\"panel verdict\" id=\"motionVerdictPanel\" style=\"margin-top:18px; margin-bottom:0;\">\n      <div class=\"verdict-top\">\n        <div class=\"verdict-label\" id=\"motionVerdictLabel\">\u2014</div>\n      </div>\n      <div class=\"verdict-reason\" id=\"motionVerdictReason\">Selecione a categoria do helic\u00f3ptero e ajuste os valores acima.</div>\n\n      <div class=\"metrics cols-4\" style=\"margin-top:16px;\">\n        <div class=\"metric\">\n          <div class=\"m-label\">Pitch e Roll \u2014 limite</div>\n          <div class=\"m-value\" id=\"limitBCOut\">\u2014</div>\n        </div>\n        <div class=\"metric\">\n          <div class=\"m-label\">Inc \u2014 limite</div>\n          <div class=\"m-value\" id=\"limitIncOut\">\u2014</div>\n        </div>\n        <div class=\"metric\">\n          <div class=\"m-label\">Heave Rate \u2014 limite</div>\n          <div class=\"m-value\" id=\"limitVArfOut\">\u2014</div>\n        </div>\n        <div class=\"metric\">\n          <div class=\"m-label\">Heave \u2014 limite</div>\n          <div class=\"m-value\" id=\"limitArfOut\">\u2014</div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ===================== ANEXOS / CIRCUITOS POR TIPO ===================== -->\n  <div class=\"panel\" id=\"panel-09\">\n    <div class=\"panel-label\"><span class=\"num\">09</span> Circuitos de Tr\u00e1fego</div>\n    <div class=\"annex-menu\" id=\"annexMenu\">\n      <button class=\"annex-btn\" data-annex=\"circuito-noturno\">\n        <span class=\"annex-btn-title\">AW139</span>\n      </button>\n      <button class=\"annex-btn\" data-annex=\"anexo-c\">\n        <span class=\"annex-btn-title\">AW189</span>\n      </button>\n      <button class=\"annex-btn\" data-annex=\"anexo-d\">\n        <span class=\"annex-btn-title\">H175</span>\n      </button>\n      <button class=\"annex-btn\" data-annex=\"anexo-e\">\n        <span class=\"annex-btn-title\">SK92</span>\n      </button>\n      <button class=\"annex-btn\" data-annex=\"anexo-f\">\n        <span class=\"annex-btn-title\">H160</span>\n      </button>\n      <button class=\"annex-btn\" data-annex=\"anexo-g\">\n        <span class=\"annex-btn-title\">H145</span>\n      </button>\n      <button class=\"annex-btn\" data-annex=\"anexo-h\">\n        <span class=\"annex-btn-title\">H225</span>\n      </button>\n    </div>\n  </div>\n\n  <!-- ===================== RELAT\u00d3RIOS ===================== -->\n  <div class=\"panel result\" id=\"panel-10\">\n    <div class=\"panel-label\"><span class=\"num\">10</span> Relat\u00f3rios</div>\n\n    <button type=\"button\" class=\"report-print-btn\" id=\"reportPrintBtn\">Gerar Relat\u00f3rio</button>\n\n    <div id=\"reportActions\" style=\"display:none; margin-top:16px;\">\n      <div style=\"display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:10px;\">\n        <div class=\"note\" style=\"margin-bottom:0;\">Relat\u00f3rio gerado \u2014 confira abaixo.</div>\n        <button type=\"button\" class=\"report-close-btn\" id=\"reportCloseBtn\" aria-label=\"Fechar relat\u00f3rio\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button>\n      </div>\n      <div class=\"report-preview-wrap\">\n        <div id=\"reportPreviewBody\" class=\"report-preview-body\"></div>\n      </div>\n      <div style=\"display:flex; justify-content:center; margin-top:14px;\">\n        <button type=\"button\" class=\"report-share-btn\" id=\"reportShareBtn\">Enviar</button>\n      </div>\n      <div class=\"note\" id=\"reportShareNote\" style=\"margin-top:10px; display:none;\"></div>\n    </div>\n  </div>\n\n  <div style=\"display:flex; justify-content:center; margin-top:6px;\">\n    <button type=\"button\" class=\"topo-btn\" id=\"topoBtn\">Topo</button>\n  </div>\n\n  <!-- ===================== ANNEX IMAGE MODAL ===================== -->\n  <div class=\"annex-modal-overlay\" id=\"annexModalOverlay\">\n    <div class=\"annex-modal\">\n      <div class=\"annex-modal-header\">\n        <span id=\"annexModalTitle\">\u2014</span>\n        <button class=\"annex-modal-close\" id=\"annexModalClose\" aria-label=\"Fechar\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button>\n      </div>\n      <div class=\"annex-modal-body\" id=\"annexModalBody\">\n        <!-- conte\u00fado injetado via JS -->\n      </div>\n    </div>\n  </div>\n\n  <!-- ===================== CHECKLIST MODAL ===================== -->\n  <div class=\"annex-modal-overlay\" id=\"clistModalOverlay\">\n    <div class=\"annex-modal\">\n      <div class=\"annex-modal-header\">\n        <span id=\"clistModalTitle\">\u2014</span>\n        <button class=\"annex-modal-close\" id=\"clistModalClose\" aria-label=\"Fechar\"><svg viewBox=\"0 0 24 24\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button>\n      </div>\n      <div class=\"annex-modal-body\" id=\"clistModalBody\">\n        <!-- conte\u00fado injetado via JS -->\n      </div>\n    </div>\n  </div>\n\n</div>\n\n<div id=\"diagBanner\" style=\"display:none; position:fixed; left:8px; right:8px; bottom:8px; z-index:9999; background:#3a0a0a; border:1px solid #ff3b3b; color:#fff; font-family:monospace; font-size:11px; padding:10px 12px; border-radius:8px; max-height:40vh; overflow:auto; white-space:pre-wrap;\"></div>\n\n\n\n\n\n\n\n", "scripts": ["\n  window.addEventListener('error', function(e){\n    var b = document.getElementById('diagBanner');\n    if (!b) return;\n    b.style.display = 'block';\n    b.textContent += 'ERRO: ' + e.message + '  (linha ' + e.lineno + ')\\n';\n  });\n\n  (function(){\n    var backBtn = document.getElementById('ndlBackBtn');\n    if (!backBtn) return;\n    backBtn.addEventListener('click', function(){\n      var realBackBtn = window.document.getElementById('backBtn');\n      if (realBackBtn) { realBackBtn.click(); }\n    });\n  })();\n", "\n(function(){\n  // ---------- imagem de capa embutida em base64 ----------\n  \n\n  // ---------- campo 01: registro de hor\u00e1rios e trajeto ----------\n  var FLOG_STORAGE_KEY = 'ndlFlightLogV1';\n  var FLOG_FIELD_IDS = [\n    'flogAcionamento','flogTempoDecolagem',\n    'flogOrigem1','flogDestino1','flogPartida1','flogDecolagem1','flogPouso1','flogCorte1',\n    'flogOrigem2','flogDestino2','flogPartida2','flogDecolagem2','flogPouso2','flogCorte2'\n  ];\n\n  // ---------- tripula\u00e7\u00e3o (Piloto / Co-Piloto): persistem entre voos/sess\u00f5es,\n  // n\u00e3o s\u00e3o apagadas pelo \"Limpar\" do campo 01 nem pelo \"Novo Voo\" ----------\n  var CREW_STORAGE_KEY = 'ndlCrewV1';\n  var CREW_FIELD_IDS = ['crewPiloto', 'crewCoPiloto'];\n  function saveCrew(){\n    var data = {};\n    CREW_FIELD_IDS.forEach(function(id){\n      var el = document.getElementById(id);\n      if (el) data[id] = el.value;\n    });\n    try { localStorage.setItem(CREW_STORAGE_KEY, JSON.stringify(data)); } catch(e){}\n  }\n  function loadCrew(){\n    var raw;\n    try { raw = localStorage.getItem(CREW_STORAGE_KEY); } catch(e){ raw = null; }\n    if (!raw) return;\n    var data;\n    try { data = JSON.parse(raw); } catch(e){ return; }\n    CREW_FIELD_IDS.forEach(function(id){\n      var el = document.getElementById(id);\n      if (el && typeof data[id] === 'string') el.value = data[id];\n    });\n  }\n  loadCrew();\n  CREW_FIELD_IDS.forEach(function(id){\n    var el = document.getElementById(id);\n    if (el) el.addEventListener('input', saveCrew);\n  });\n\n  function fillCurrentTime(input){\n    var now = new Date();\n    var hh = String(now.getHours()).padStart(2,'0');\n    var mm = String(now.getMinutes()).padStart(2,'0');\n    input.value = hh + ':' + mm;\n    saveFlightLog();\n    validateTimeSequence();\n  }\n\n  // formata automaticamente o que for digitado (s\u00f3 n\u00fameros) no padr\u00e3o HH:MM\n  function formatTimeInput(input){\n    var digits = input.value.replace(/\\D/g,'').slice(0,4);\n    var out = digits;\n    if (digits.length >= 3){\n      out = digits.slice(0,2) + ':' + digits.slice(2);\n    }\n    input.value = out;\n  }\n\n  // persiste os dados no localStorage do dispositivo: ficam salvos entre sess\u00f5es\n  // (fechar/abrir o app) e s\u00f3 s\u00e3o apagados ao tocar no bot\u00e3o \"Limpar\".\n  function updateFlogClearBtnState(){\n    var btn = document.getElementById('flogClearBtn');\n    if (!btn) return;\n    var anyFilled = FLOG_FIELD_IDS.some(function(id){\n      var el = document.getElementById(id);\n      return el && el.value;\n    });\n    btn.classList.toggle('flog-clean', !anyFilled);\n  }\n\n  function saveFlightLog(){\n    var data = {};\n    FLOG_FIELD_IDS.forEach(function(id){\n      var el = document.getElementById(id);\n      if (el) data[id] = el.value;\n    });\n    try { localStorage.setItem(FLOG_STORAGE_KEY, JSON.stringify(data)); } catch(e){}\n    updateNovoVooState();\n    updateFlogClearBtnState();\n  }\n\n  function loadFlightLog(){\n    var raw;\n    try { raw = localStorage.getItem(FLOG_STORAGE_KEY); } catch(e){ raw = null; }\n    if (!raw) return;\n    var data;\n    try { data = JSON.parse(raw); } catch(e){ return; }\n    FLOG_FIELD_IDS.forEach(function(id){\n      var el = document.getElementById(id);\n      if (el && typeof data[id] === 'string') el.value = data[id];\n    });\n  }\n\n  function clearFlightLog(){\n    FLOG_FIELD_IDS.forEach(function(id){\n      var el = document.getElementById(id);\n      if (el) el.value = '';\n    });\n    var tempoEl = document.getElementById('flogTempoDecolagem');\n    if (tempoEl) tempoEl.classList.remove('flog-alert');\n    document.querySelectorAll('.flog-time.flog-seq-warn').forEach(function(el){ el.classList.remove('flog-seq-warn'); });\n    resetCronometro();\n    try { localStorage.removeItem(FLOG_STORAGE_KEY); } catch(e){}\n    updateNovoVooState();\n    updateFlogClearBtnState();\n  }\n\n  // ---------- cron\u00f4metro (campo 01) ----------\n  // Inicia ao tocar em Acionamento, para ao tocar (pela 1\u00aa vez) em Partida da 1\u00aa perna,\n  // e fica vermelho ap\u00f3s 45 minutos decorridos. Zera junto com \"Limpar\"/\"Novo Voo\".\n  var cronometroTimer = null;\n  var cronometroStartMs = null;\n  function cronometroFormat(elapsedSec){\n    var h = Math.floor(elapsedSec/3600);\n    var m = Math.floor((elapsedSec%3600)/60);\n    var s = elapsedSec%60;\n    return String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0');\n  }\n  function cronometroTick(){\n    var el = document.getElementById('flogCronometro');\n    if (!el || cronometroStartMs === null) return;\n    var elapsedSec = Math.floor((Date.now() - cronometroStartMs) / 1000);\n    el.value = cronometroFormat(elapsedSec);\n    el.classList.toggle('flog-alert', elapsedSec > 45*60);\n  }\n  function startCronometro(){\n    if (cronometroTimer !== null) return; // j\u00e1 em andamento\n    cronometroStartMs = Date.now();\n    cronometroTick();\n    cronometroTimer = setInterval(cronometroTick, 1000);\n  }\n  function stopCronometro(){\n    if (cronometroTimer === null) return;\n    clearInterval(cronometroTimer);\n    cronometroTimer = null;\n  }\n  function resetCronometro(){\n    stopCronometro();\n    cronometroStartMs = null;\n    var el = document.getElementById('flogCronometro');\n    if (el){ el.value = '--:--:--'; el.classList.remove('flog-alert'); }\n  }\n\n  // calcula Tempo para Decolagem = Partida (1\u00aa perna) - Acionamento, em HH:MM\n  // fica vermelho se o intervalo for maior que 45 minutos\n  function computeTempoDecolagem(){\n    var acionamentoEl = document.getElementById('flogAcionamento');\n    var partida1El = document.getElementById('flogPartida1');\n    var outEl = document.getElementById('flogTempoDecolagem');\n    if (!/^\\d{2}:\\d{2}$/.test(acionamentoEl.value) || !/^\\d{2}:\\d{2}$/.test(partida1El.value)) return;\n    var a = acionamentoEl.value.split(':').map(Number);\n    var p = partida1El.value.split(':').map(Number);\n    var startMin = a[0]*60 + a[1];\n    var endMin = p[0]*60 + p[1];\n    var diff = endMin - startMin;\n    if (diff < 0) diff += 24*60; // atravessou a meia-noite\n    var dh = String(Math.floor(diff/60)).padStart(2,'0');\n    var dm = String(diff % 60).padStart(2,'0');\n    outEl.value = dh + ':' + dm;\n    outEl.classList.toggle('flog-alert', diff > 45);\n    saveFlightLog();\n  }\n\n  function applyTempoDecolagemAlertFromValue(){\n    var outEl = document.getElementById('flogTempoDecolagem');\n    if (!outEl || !outEl.value) return;\n    var parts = outEl.value.split(':').map(Number);\n    if (parts.length !== 2 || isNaN(parts[0]) || isNaN(parts[1])) return;\n    var totalMin = parts[0]*60 + parts[1];\n    outEl.classList.toggle('flog-alert', totalMin > 45);\n  }\n\n  // ---------- sequ\u00eancia l\u00f3gica dos hor\u00e1rios ----------\n  // Acionamento -> Partida -> Decolagem -> Pouso -> Corte (cada perna) deve\n  // ser cronologicamente crescente. Se algum campo estiver fora de ordem,\n  // ele \u00e9 destacado (aviso visual), sem bloquear a digita\u00e7\u00e3o.\n  function toMinutes(v){\n    if (!/^\\d{2}:\\d{2}$/.test(v)) return null;\n    var p = v.split(':').map(Number);\n    return p[0]*60 + p[1];\n  }\n  function validateSequenceChain(ids){\n    var last = null;\n    ids.forEach(function(id){\n      var el = document.getElementById(id);\n      if (!el) return;\n      var mins = toMinutes(el.value);\n      if (mins === null){ el.classList.remove('flog-seq-warn'); return; }\n      if (last !== null && mins < last){\n        el.classList.add('flog-seq-warn');\n      } else {\n        el.classList.remove('flog-seq-warn');\n      }\n      last = mins;\n    });\n  }\n  function validateTimeSequence(){\n    validateSequenceChain(['flogAcionamento','flogPartida1','flogDecolagem1','flogPouso1','flogCorte1']);\n    validateSequenceChain(['flogPartida2','flogDecolagem2','flogPouso2','flogCorte2']);\n  }\n\n  loadFlightLog();\n  applyTempoDecolagemAlertFromValue();\n  validateTimeSequence();\n  updateFlogClearBtnState();\n\n  document.querySelectorAll('input.flog-time').forEach(function(input){\n    // toque num campo vazio preenche com a hora atual do device; se j\u00e1 tiver\n    // valor, o toque s\u00f3 posiciona o cursor para edi\u00e7\u00e3o manual\n    input.addEventListener('click', function(){\n      if (input.id === 'flogAcionamento') startCronometro();\n      if (input.id === 'flogPartida1') stopCronometro();\n      if (!input.value){\n        fillCurrentTime(input);\n        if (input.id === 'flogPartida1') computeTempoDecolagem();\n      }\n    });\n    // digita\u00e7\u00e3o manual: formata automaticamente e recalcula/valida\n    input.addEventListener('input', function(){\n      formatTimeInput(input);\n      saveFlightLog();\n      if (input.id === 'flogAcionamento' || input.id === 'flogPartida1') computeTempoDecolagem();\n      validateTimeSequence();\n    });\n    input.addEventListener('blur', function(){\n      validateTimeSequence();\n    });\n  });\n  document.querySelectorAll('input.flog-text').forEach(function(input){\n    input.addEventListener('input', saveFlightLog);\n  });\n  var flogClearBtn = document.getElementById('flogClearBtn');\n  if (flogClearBtn){\n    flogClearBtn.addEventListener('click', clearFlightLog);\n  }\n\n\n  // ---------- imagem do Anexo B (Circuito Noturno AW139) embutida em base64 ----------\n  var ANNEX_B_IMAGE_B64 = '';\n\n  // ---------- imagem do Anexo C (AW189 Offshore Night Approach) embutida em base64 ----------\n  var ANNEX_C_IMAGE_B64 = '';\n\n  // ---------- imagem do Anexo E (SK92 Offshore Night Approach) embutida em base64 ----------\n  var ANNEX_E_IMAGE_B64 = '';\n\n  // ---------- imagem do Anexo H (H225 Offshore Night Approach) embutida em base64 ----------\n  var ANNEX_H_IMAGE_B64 = '';\n\n  // ---------- AW139: p\u00e1ginas 2 e 3 (figuras do PDF AW139_NOTURNO_BRISTOW) ----------\n  var ANNEX_B2_PT_IMAGE_B64 = '';\n  var ANNEX_B2_EN_IMAGE_B64 = '';\n  var ANNEX_B3_IMAGE_B64 = '';\n\n  // ---------- estrutura de dados dos anexos (circuitos de tr\u00e1fego por tipo) ----------\n  var ANNEX_DATA = {\n    'circuito-noturno': { title: 'AW139', image: 'ANNEX_B_IMAGE_B64', pages: [ ['ANNEX_B_IMAGE_B64'], [['ANNEX_B2_PT_IMAGE_B64', 'ANNEX_B2_EN_IMAGE_B64'], 'ANNEX_B3_IMAGE_B64'] ] },\n    'anexo-c': { title: 'AW189', image: 'ANNEX_C_IMAGE_B64' },\n    'anexo-d': { title: 'H175', image: null },\n    'anexo-e': { title: 'SK92', image: 'ANNEX_E_IMAGE_B64' },\n    'anexo-f': { title: 'H160', image: null },\n    'anexo-g': { title: 'H145', image: null },\n    'anexo-h': { title: 'H225', image: 'ANNEX_H_IMAGE_B64' }\n  };\n\n  // ---------- state ----------\n  var state = {\n    flightType: 'medevac', // medevac | treinamento \u2014 define o limite de trav\u00e9s (20kt / 10kt)\n    deckPos: 'plataforma',   // plataforma | popa | meianau | proa | superestrutura\n    shipHdg: 0,              // proa da UM, graus verdadeiros/magn\u00e9ticos (Helideck Report)\n    windDirTrue: 0,          // dire\u00e7\u00e3o do vento, graus verdadeiros/magn\u00e9ticos (de onde vem)\n    windDir: 0,              // CALCULADO: dire\u00e7\u00e3o do vento relativa \u00e0 proa (0 = vento de proa)\n    windSpd: 0,\n    heliCategory: 'A',       // A | B \u2014 categoria do helic\u00f3ptero (item 6.8)\n    motionBC: 0,             // balan\u00e7o e caturro informado (graus, x10 no slider)\n    motionInc: 0,            // inclina\u00e7\u00e3o informada (graus, x10 no slider)\n    motionVArf: 0,           // velocidade de arfagem informada (m/s, x10 no slider)\n    motionArf: 0             // arfagem informada (m, x10 no slider)\n  };\n  window.state = state;\n\n  // ---------- item 6.8: limites de movimento do helideque (tabelas) ----------\n  // Tabela original (NORMAM-223), aplic\u00e1vel a voos MEDEVAC \u2014 opera\u00e7\u00e3o noturna.\n  var MOTION_LIMITS_MEDEVAC = {\n    A: { 1: {bc:3.0, inc:3.5, varf:1.0, arf:4.0}, 2: {bc:2.0, inc:2.5, varf:0.5, arf:1.5}, 3: null },\n    B: { 1: {bc:4.0, inc:4.5, varf:1.0, arf:4.0}, 2: {bc:2.0, inc:2.5, varf:0.5, arf:1.5}, 3: null }\n  };\n  // Tabela j\u00e1 reduzida em 25%, aplic\u00e1vel a voos de treinamento noturno (item 6.8).\n  var MOTION_LIMITS_TREINAMENTO = {\n    A: { 1: {bc:2.3, inc:2.6, varf:0.8, arf:3.0}, 2: {bc:1.5, inc:1.9, varf:0.4, arf:1.1}, 3: null },\n    B: { 1: {bc:3.0, inc:3.4, varf:0.8, arf:3.0}, 2: {bc:1.5, inc:1.9, varf:0.4, arf:1.1}, 3: null }\n  };\n\n  // ---------- geometry constants (b\u00fassola/diagrama principal) ----------\n  var CX = 220, CY = 210, SHIP_LEN = 300, SHIP_W = 90, ringR = 168;\n\n  // ---------- elements ----------\n  var flightTypeToggle = document.getElementById('flightTypeToggle');\n  var deckPosRow = document.getElementById('deckPosRow');\n  var baseClassOut = document.getElementById('baseClassOut');\n  var deckSvgEl = document.getElementById('deckSvg');\n\n  // ---------- elementos do painel 07 (item 6.8 \u2014 limites de movimento do helideque) ----------\n  var heliCategoryRow = document.getElementById('heliCategoryRow');\n  var motionBCInput = document.getElementById('motionBC');\n  var motionIncInput = document.getElementById('motionInc');\n  var motionVArfInput = document.getElementById('motionVArf');\n  var motionArfInput = document.getElementById('motionArf');\n  var motionBCVal = document.getElementById('motionBCVal');\n  var motionIncVal = document.getElementById('motionIncVal');\n  var motionVArfVal = document.getElementById('motionVArfVal');\n  var motionArfVal = document.getElementById('motionArfVal');\n  var motionFlightTypeOut = document.getElementById('motionFlightTypeOut');\n  var motionClassOut = document.getElementById('motionClassOut');\n  var motionTableOut = document.getElementById('motionTableOut');\n  var motionVerdictPanel = document.getElementById('motionVerdictPanel');\n  var motionVerdictLabel = document.getElementById('motionVerdictLabel');\n  var motionVerdictReason = document.getElementById('motionVerdictReason');\n  var limitBCOut = document.getElementById('limitBCOut');\n  var limitIncOut = document.getElementById('limitIncOut');\n  var limitVArfOut = document.getElementById('limitVArfOut');\n  var limitArfOut = document.getElementById('limitArfOut');\n\n  // ---------- elementos do painel de anexos / circuitos de tr\u00e1fego ----------\n  var annexMenu = document.getElementById('annexMenu');\n  var annexModalOverlay = document.getElementById('annexModalOverlay');\n  var annexModalTitle = document.getElementById('annexModalTitle');\n  var annexModalClose = document.getElementById('annexModalClose');\n  var annexModalBody = document.getElementById('annexModalBody');\n\n  var ANNEX_IMAGE_MAP = {\n    'ANNEX_B_IMAGE_B64': ANNEX_B_IMAGE_B64,\n    'ANNEX_B2_PT_IMAGE_B64': ANNEX_B2_PT_IMAGE_B64,\n    'ANNEX_B2_EN_IMAGE_B64': ANNEX_B2_EN_IMAGE_B64,\n    'ANNEX_B3_IMAGE_B64': ANNEX_B3_IMAGE_B64,\n    'ANNEX_C_IMAGE_B64': ANNEX_C_IMAGE_B64,\n    'ANNEX_E_IMAGE_B64': ANNEX_E_IMAGE_B64,\n    'ANNEX_H_IMAGE_B64': ANNEX_H_IMAGE_B64\n  };\n\n  // anexos com v\u00e1rias p\u00e1ginas (ex.: AW139): cada p\u00e1gina tem 1 ou mais figuras empilhadas\n  // e bot\u00f5es pequenos PR\u00d3XIMO / ANTERIOR no final, para manter as figuras no maior tamanho\n  function renderAnnexPage(annexKey, idx){\n    var annex = ANNEX_DATA[annexKey];\n    var pages = annex.pages;\n    var en = !!(window.AW && window.AW.lang === 'en');\n    var html = '';\n    pages[idx].forEach(function(ref){\n      if (Array.isArray(ref)) ref = en ? ref[1] : ref[0];\n      var b64 = ANNEX_IMAGE_MAP[ref];\n      var mime = b64.substring(0,4) === 'iVBO' ? 'image/png' : 'image/jpeg';\n      html += '<img src=\"data:' + mime + ';base64,' + b64 + '\" alt=\"' + annex.title + '\">';\n    });\n    var hasPrev = idx > 0, hasNext = idx < pages.length - 1;\n    if (hasPrev || hasNext){\n      html += '<div class=\"annex-next-wrap\">';\n      if (hasPrev) html += '<button type=\"button\" class=\"annex-next-btn\" id=\"annexPrevBtn\">' + (en ? 'PREVIOUS' : 'ANTERIOR') + '</button>';\n      if (hasNext) html += '<button type=\"button\" class=\"annex-next-btn\" id=\"annexNextBtn\">' + (en ? 'NEXT' : 'PR\u00d3XIMO') + '</button>';\n      html += '</div>';\n    }\n    annexModalBody.classList.remove('annex-empty');\n    annexModalBody.innerHTML = html;\n    annexModalBody.scrollTop = 0;\n    if (hasPrev) document.getElementById('annexPrevBtn').addEventListener('click', function(){ renderAnnexPage(annexKey, idx - 1); });\n    if (hasNext) document.getElementById('annexNextBtn').addEventListener('click', function(){ renderAnnexPage(annexKey, idx + 1); });\n  }\n\n  function openAnnexModal(annexKey){\n    var annex = ANNEX_DATA[annexKey];\n    if (!annex) return;\n    annexModalTitle.textContent = annex.title;\n    var imageB64 = annex.image ? ANNEX_IMAGE_MAP[annex.image] : null;\n    if (annex.pages){\n      renderAnnexPage(annexKey, 0);\n      annexModalOverlay.classList.add('open');\n      return;\n    }\n    if (imageB64){\n      var mime = imageB64.substring(0,4) === 'iVBO' ? 'image/png' : 'image/jpeg';\n      annexModalBody.innerHTML = '<img src=\"data:' + mime + ';base64,' + imageB64 + '\" alt=\"' + annex.title + '\">';\n    } else {\n      annexModalBody.innerHTML = '';   // sem imagem associada: campo totalmente vazio\n    }\n    annexModalBody.classList.toggle('annex-empty', !imageB64);\n    annexModalOverlay.classList.add('open');\n  }\n\n  function closeAnnexModal(){\n    annexModalOverlay.classList.remove('open');\n  }\n\n  annexMenu.querySelectorAll('.annex-btn').forEach(function(btn){\n    btn.addEventListener('click', function(){\n      openAnnexModal(btn.getAttribute('data-annex'));\n    });\n  });\n  annexModalClose.addEventListener('click', closeAnnexModal);\n  annexModalOverlay.addEventListener('click', function(e){\n    if (e.target === annexModalOverlay) closeAnnexModal();\n  });\n\n  // ---------- campo 02: Checklists ----------\n  var CLIST_STORAGE_KEY = 'ndlChecklistsV1';\n\n  var CLIST_DATA = {\n    gestor: {\n      title: 'Autoriza\u00e7\u00e3o do Gestor',\n      mode: 'any', // verde quando pelo menos 1 estiver marcado\n      items: [\n        'AUTORIZA\u00c7\u00c3O OBTIDA'\n      ]\n    },\n    voo: {\n      title: 'Prepara\u00e7\u00e3o para o Voo',\n      mode: 'all', // verde somente quando todos estiverem marcados\n      items: [\n        'Plano de voo ida e volta aprovados.',\n        'Para confec\u00e7\u00e3o dos planos de voo, deve constar no item 18 RMK / VOO DE TREINAMENTO AUTORIZADO ANAC SBXX CFM - Em caso de voo de treinamento - ou item 18 RMK / TREN (Transporte de enfermo) ou / TROV (Transporte de \u00f3rg\u00e3os vitais) - em caso de voo MEDVAC.',\n        'Os planos de ida e volta devem ser feitos VFR de/para aeroportos que n\u00e3o operem IFR.',\n        'Os planos de ida e volta devem ser feitos Y e Z para aeroportos que operem IFR.',\n        'Para treinamentos nos aeroportos de SBME, SBCB e SBJR \u00e9 preciso solicitar que a Coordena\u00e7\u00e3o de Voo avise antecipadamente aos administradores do aeroporto. Nos demais aeroportos, dever\u00e1 ser verificada a necessidade de se coordenar com a empresa administradora.',\n        'Pegar iPads e conferir suas cargas, atualizar aplicativos.',\n        'App de navega\u00e7\u00e3o atualizado e informa\u00e7\u00f5es meteorol\u00f3gicas para rota, destino e alternativa.',\n        'Imprimir flight preview, conferir dados do voo e helideck report.',\n        'Preencher Flight Risk Assessment (F-OPR 34).'\n      ]\n    },\n    aeronave: {\n      title: 'Prepara\u00e7\u00e3o da Aeronave',\n      mode: 'all',\n      items: [\n        'Remo\u00e7\u00e3o de todas as amarras, capas, protetores e bloqueios.',\n        'Funcionamento das lanternas de m\u00e3o, luzes de cabine e far\u00f3is da aeronave.',\n        'Inexist\u00eancia de material solto na cabine.',\n        'Checklist completo (tratar como primeiro voo do dia).',\n        'Ajuste do alt\u00edmetro, funcionamento do RADALT, TAWS e radar meteorol\u00f3gico.',\n        'Confirma\u00e7\u00e3o de operacionalidade do sistema de Flight Following.'\n      ]\n    }\n  };\n\n  var clistState = {}; // ex.: { 'gestor_0': true, 'voo_2': false, ... }\n\n  function saveClistState(){\n    try { localStorage.setItem(CLIST_STORAGE_KEY, JSON.stringify(clistState)); } catch(e){}\n  }\n  function loadClistState(){\n    var raw;\n    try { raw = localStorage.getItem(CLIST_STORAGE_KEY); } catch(e){ raw = null; }\n    if (!raw) return;\n    try { clistState = JSON.parse(raw) || {}; } catch(e){ clistState = {}; }\n  }\n  loadClistState();\n  // migra\u00e7\u00e3o \u00fanica: o checklist do gestor passou de 4 itens para 1 (\"AUTORIZA\u00c7\u00c3O OBTIDA\");\n  // descarta as marca\u00e7\u00f5es antigas para n\u00e3o aparecer como j\u00e1 autorizado\n  (function(){\n    var MIG = 'ndlGestorUmItemV1', done = false;\n    try { done = localStorage.getItem(MIG) === '1'; } catch(e){}\n    if (!done) {\n      Object.keys(clistState).forEach(function(k){ if (k.indexOf('gestor_') === 0) delete clistState[k]; });\n      saveClistState();\n      try { localStorage.setItem(MIG, '1'); } catch(e){}\n    }\n  })();\n\n  function clistCheckedCount(key){\n    var data = CLIST_DATA[key];\n    var count = 0;\n    for (var i=0;i<data.items.length;i++){\n      if (clistState[key+'_'+i]) count++;\n    }\n    return count;\n  }\n\n  function updateClistButton(key){\n    var data = CLIST_DATA[key];\n    var total = data.items.length;\n    var checked = clistCheckedCount(key);\n    var btn = document.getElementById('clistBtn' + key.charAt(0).toUpperCase() + key.slice(1));\n    var countEl = document.getElementById('clistCount' + key.charAt(0).toUpperCase() + key.slice(1));\n    if (countEl) countEl.textContent = checked + '/' + total;\n    var isGo = (data.mode === 'any') ? (checked >= 1) : (checked === total);\n    if (btn) btn.classList.toggle('clist-go', isGo);\n  }\n\n  function updateClistClearBtnState(){\n    var btn = document.getElementById('clistClearBtn');\n    if (!btn) return;\n    // conta s\u00f3 os itens que existem HOJE (ignora res\u00edduos de vers\u00f5es antigas\n    // do checklist que possam ter ficado presos no localStorage)\n    var anyChecked = Object.keys(CLIST_DATA).some(function(key){\n      return clistCheckedCount(key) > 0;\n    });\n    btn.classList.toggle('clist-clean', !anyChecked);\n  }\n\n  function updateAllClistButtons(){\n    Object.keys(CLIST_DATA).forEach(updateClistButton);\n    updateChecklistPendingAlert();\n    updateNovoVooState();\n    updateClistClearBtnState();\n  }\n\n  // ---------- alerta fixo no topo: AUTORIZA\u00c7\u00c3O DO GESTOR pendente ----------\n  var topbarAlert = document.getElementById('topbarAlert');\n  function updateChecklistPendingAlert(){\n    var checkedGestor = clistCheckedCount('gestor');\n    topbarAlert.style.display = (checkedGestor === 0) ? 'block' : 'none';\n    updateTopbarHeight();\n  }\n\n  var clistModalOverlay = document.getElementById('clistModalOverlay');\n  var clistModalTitle = document.getElementById('clistModalTitle');\n  var clistModalClose = document.getElementById('clistModalClose');\n  var clistModalBody = document.getElementById('clistModalBody');\n  var clistModalCurrentKey = null;\n\n  function renderClistModalBody(key){\n    var data = CLIST_DATA[key];\n    clistModalBody.innerHTML = '';\n    data.items.forEach(function(text, i){\n      var id = key + '_' + i;\n      var row = document.createElement('div');\n      row.className = 'clist-item' + (clistState[id] ? ' checked' : '');\n      row.setAttribute('data-id', id);\n      var flag = document.createElement('div');\n      flag.className = 'clist-flag';\n      var label = document.createElement('div');\n      label.className = 'clist-item-text';\n      label.textContent = text;\n      row.appendChild(flag);\n      row.appendChild(label);\n      row.addEventListener('click', function(){\n        clistState[id] = !clistState[id];\n        row.classList.toggle('checked', !!clistState[id]);\n        saveClistState();\n        updateClistButton(key);\n        updateChecklistPendingAlert();\n        updateNovoVooState();\n        updateClistClearBtnState();\n      });\n      clistModalBody.appendChild(row);\n    });\n  }\n\n  function openClistModal(key){\n    clistModalCurrentKey = key;\n    clistModalTitle.textContent = CLIST_DATA[key].title;\n    renderClistModalBody(key);\n    clistModalOverlay.classList.add('open');\n  }\n  function closeClistModal(){\n    clistModalOverlay.classList.remove('open');\n    clistModalCurrentKey = null;\n  }\n\n  document.querySelectorAll('.clist-btn').forEach(function(btn){\n    btn.addEventListener('click', function(){\n      openClistModal(btn.getAttribute('data-clist'));\n    });\n  });\n  clistModalClose.addEventListener('click', closeClistModal);\n  clistModalOverlay.addEventListener('click', function(e){\n    if (e.target === clistModalOverlay) closeClistModal();\n  });\n\n  document.getElementById('clistClearBtn').addEventListener('click', function(){\n    // apaga tudo (n\u00e3o s\u00f3 os \u00edndices de hoje), eliminando qualquer res\u00edduo de\n    // vers\u00f5es antigas do checklist que possa ter ficado preso no localStorage\n    clistState = {};\n    saveClistState();\n    updateAllClistButtons();\n    if (clistModalCurrentKey) renderClistModalBody(clistModalCurrentKey);\n  });\n\n  updateAllClistButtons();\n\n  function normDeg(d){ return ((d % 360) + 360) % 360; }\n\n  function recomputeRelativeWind(){\n    state.windDir = normDeg(state.windDirTrue - state.shipHdg);\n  }\n\n  function updateBaseClassDisplay(){\n    var base = baseClassFromPos(state.deckPos);\n    baseClassOut.textContent = 'CLASSE ' + base;\n    baseClassOut.classList.remove('warn','bad','good');\n    if (base === 3) baseClassOut.classList.add('bad');\n    else if (base === 2) baseClassOut.classList.add('warn');\n    else baseClassOut.classList.add('good');\n    renderMotionLimits();\n  }\n\n  // ---------- item 6.8: c\u00e1lculo e exibi\u00e7\u00e3o dos limites de movimento do helideque ----------\n  function renderMotionLimits(){\n    var cls = classify();\n    var helideckClass = cls.effective;\n    var flightTypeLabel = state.flightType === 'medevac' ? 'MEDEVAC' : 'Treinamento';\n    var tableLabel = state.flightType === 'medevac'\n      ? 'NORMAM-223 (original)'\n      : 'NORMAM-223 reduzida 25% (treino)';\n\n    motionFlightTypeOut.textContent = flightTypeLabel;\n    motionClassOut.textContent = 'Classe ' + helideckClass + (cls.reclassified ? ' (reclassificada de ' + cls.base + ')' : '');\n    motionTableOut.textContent = tableLabel;\n\n    var limits = motionLimitsFor(state.flightType, state.heliCategory, helideckClass);\n\n    motionVerdictPanel.classList.remove('go','caution','no-go');\n\n    var reclassNote = cls.reclassified\n      ? ' Helideque <b>reclassificado de Classe '+cls.base+' para Classe '+helideckClass+'</b> em fun\u00e7\u00e3o do vento de alheta/popa informado \u2014 os par\u00e2metros de movimento utilizados s\u00e3o os da <b>Classe '+helideckClass+'</b>.'\n      : '';\n\n    if (!limits){\n      motionVerdictPanel.classList.add('no-go');\n      motionVerdictLabel.textContent = 'OPERA\u00c7\u00c3O NOTURNA N\u00c3O PERMITIDA';\n      motionVerdictReason.innerHTML = 'Para helideque <b>Classe '+helideckClass+'</b>'+(cls.reclassified ? ' (reclassificada de Classe '+cls.base+')' : '')+', a SOP 43 (item 6.8) n\u00e3o permite opera\u00e7\u00f5es noturnas nesta condi\u00e7\u00e3o. N\u00e3o h\u00e1 limites de movimento aplic\u00e1veis \u2014 o voo deve ser <b>CANCELADO</b>.'+reclassNote;\n      limitBCOut.textContent = '\u2014';\n      limitIncOut.textContent = '\u2014';\n      limitVArfOut.textContent = '\u2014';\n      limitArfOut.textContent = '\u2014';\n      return;\n    }\n\n    limitBCOut.textContent = '\u00b1'+limits.bc.toFixed(1).replace('.',',')+'\u00b0';\n    limitIncOut.textContent = limits.inc.toFixed(1).replace('.',',')+'\u00b0';\n    limitVArfOut.textContent = limits.varf.toFixed(1).replace('.',',')+' m/s';\n    limitArfOut.textContent = limits.arf.toFixed(1).replace('.',',')+' m';\n\n    var bc = state.motionBC/10, inc = state.motionInc/10, varf = state.motionVArf/10, arf = state.motionArf/10;\n\n    var exceeded = [];\n    if (bc > limits.bc) exceeded.push('Pitch e Roll ('+bc.toFixed(1).replace('.',',')+'\u00b0 > \u00b1'+limits.bc.toFixed(1).replace('.',',')+'\u00b0)');\n    if (inc > limits.inc) exceeded.push('Inclina\u00e7\u00e3o ('+inc.toFixed(1).replace('.',',')+'\u00b0 > '+limits.inc.toFixed(1).replace('.',',')+'\u00b0)');\n    if (varf > limits.varf) exceeded.push('Heave Rate ('+varf.toFixed(1).replace('.',',')+' m/s > '+limits.varf.toFixed(1).replace('.',',')+' m/s)');\n    if (arf > limits.arf) exceeded.push('Heave ('+arf.toFixed(1).replace('.',',')+' m > '+limits.arf.toFixed(1).replace('.',',')+' m)');\n\n    if (exceeded.length > 0){\n      motionVerdictPanel.classList.add('no-go');\n      motionVerdictLabel.textContent = 'HMS FORA DOS LIMITES';\n      motionVerdictReason.innerHTML = 'Categoria '+state.heliCategory+', Classe '+helideckClass+', voo de '+flightTypeLabel+'. Par\u00e2metro(s) acima do limite: <b>'+exceeded.join('; ')+'</b>. A opera\u00e7\u00e3o n\u00e3o deve ser realizada nestas condi\u00e7\u00f5es de movimento da UM.'+reclassNote;\n    } else {\n      motionVerdictPanel.classList.add('go');\n      motionVerdictLabel.textContent = 'HMS DENTRO DOS LIMITES';\n      motionVerdictReason.innerHTML = 'Categoria '+state.heliCategory+', Classe '+helideckClass+', voo de '+flightTypeLabel+'. Todos os par\u00e2metros informados est\u00e3o dentro dos limites da tabela aplic\u00e1vel ('+tableLabel+').'+reclassNote;\n    }\n  }\n\n  heliCategoryRow.querySelectorAll('.qbtn').forEach(function(btn){\n    btn.addEventListener('click', function(){\n      state.heliCategory = btn.getAttribute('data-cat');\n      heliCategoryRow.querySelectorAll('.qbtn').forEach(function(b){ b.classList.remove('active'); });\n      btn.classList.add('active');\n      renderMotionLimits();\n      updateNovoVooState();\n    });\n  });\n  heliCategoryRow.querySelector('[data-cat=\"A\"]').classList.add('active');\n\n  function bindMotionSlider(input, valEl, stateKey){\n    input.addEventListener('input', function(){\n      var raw = parseInt(input.value, 10);\n      state[stateKey] = raw;\n      valEl.textContent = (raw/10).toFixed(1).replace('.',',');\n      renderMotionLimits();\n      updateNovoVooState();\n    });\n  }\n  bindMotionSlider(motionBCInput, motionBCVal, 'motionBC');\n  bindMotionSlider(motionIncInput, motionIncVal, 'motionInc');\n  bindMotionSlider(motionVArfInput, motionVArfVal, 'motionVArf');\n  bindMotionSlider(motionArfInput, motionArfVal, 'motionArf');\n\n  // ---------- tipo de voo: define o limite de trav\u00e9s (20kt MEDEVAC / 10kt treinamento) ----------\n  function crosswindLimitFor(flightType){\n    return flightType === 'medevac' ? 20 : 10;\n  }\n  window.crosswindLimitFor = crosswindLimitFor;\n\n  flightTypeToggle.querySelectorAll('.ft-btn').forEach(function(btn){\n    btn.addEventListener('click', function(){\n      state.flightType = btn.getAttribute('data-type');\n      flightTypeToggle.querySelectorAll('.ft-btn').forEach(function(b){ b.classList.remove('active'); });\n      btn.classList.add('active');\n      render();\n      renderMotionLimits();\n      updateNovoVooState();\n    });\n  });\n  // default active\n  flightTypeToggle.querySelector('[data-type=\"medevac\"]').classList.add('active');\n\n  // ---------- campo 02: auto-ajuste de fonte dos bot\u00f5es MEDEVAC / Treinamento ----------\n  // Mede o espa\u00e7o realmente dispon\u00edvel no device (largura da tela em uso) e reduz a\n  // fonte gradualmente at\u00e9 o texto caber sem cortar. Roda sempre que o app abre e\n  // tamb\u00e9m quando a tela gira/redimensiona, para se adaptar a qualquer aparelho.\n  function fitLabelToWidth(el, maxSizePx, minSizePx){\n    el.style.fontSize = maxSizePx + 'px';\n    var size = maxSizePx;\n    var guard = 0;\n    while (el.scrollWidth > el.clientWidth + 1 && size > minSizePx && guard < 60){\n      size -= 0.5;\n      el.style.fontSize = size + 'px';\n      guard++;\n    }\n    // \u00faltimo recurso: se ainda n\u00e3o coube nem no tamanho m\u00ednimo, permite quebrar\n    // a linha em vez de deixar o texto cortado\n    if (el.scrollWidth > el.clientWidth + 1){\n      el.style.whiteSpace = 'normal';\n    } else {\n      el.style.whiteSpace = 'nowrap';\n    }\n  }\n\n  function fitFlightTypeLabels(){\n    flightTypeToggle.querySelectorAll('.ft-btn-title').forEach(function(el){\n      fitLabelToWidth(el, 24, 12);\n    });\n    flightTypeToggle.querySelectorAll('.ft-btn-sub').forEach(function(el){\n      fitLabelToWidth(el, 11, 7.5);\n    });\n  }\n\n  fitFlightTypeLabels();\n  window.addEventListener('resize', fitFlightTypeLabels);\n  window.addEventListener('orientationchange', function(){\n    setTimeout(fitFlightTypeLabels, 150);\n  });\n  if (document.fonts && document.fonts.ready){\n    document.fonts.ready.then(fitFlightTypeLabels);\n  }\n\n\n  deckPosRow.querySelectorAll('.deck-pos-btn').forEach(function(btn){\n    btn.addEventListener('click', function(){\n      state.deckPos = btn.getAttribute('data-pos');\n      deckPosRow.querySelectorAll('.deck-pos-btn').forEach(function(b){ b.classList.remove('active'); });\n      btn.classList.add('active');\n      updateBaseClassDisplay();\n      render();\n      updateNovoVooState();\n    });\n  });\n  // default active\n  deckPosRow.querySelector('[data-pos=\"plataforma\"]').classList.add('active');\n\n  // ---------- proa da UM e vento: agora controlados pelo widget \"B\u00fassola de Setores\" ----------\n  // (script independente no final do body). As fun\u00e7\u00f5es abaixo s\u00e3o a ponte: o widget\n  // externo chama window.NDL_setShipHdg / NDL_setWindDirTrue / NDL_setWindSpd sempre\n  // que o usu\u00e1rio gira a UM, arrasta a seta do vento, toca num setor ou muda a intensidade.\n  function setShipHdg(deg){\n    state.shipHdg = normDeg(Math.round(deg));\n    recomputeRelativeWind();\n    render();\n    renderMotionLimits();\n    updateNovoVooState();\n  }\n  function setWindDirTrue(deg){\n    state.windDirTrue = normDeg(Math.round(deg));\n    recomputeRelativeWind();\n    render();\n    renderMotionLimits();\n    updateNovoVooState();\n  }\n  function setWindSpd(spd){\n    state.windSpd = Math.max(0, Math.round(spd));\n    render();\n    renderMotionLimits();\n    updateNovoVooState();\n  }\n  window.NDL_setShipHdg = setShipHdg;\n  window.NDL_setWindDirTrue = setWindDirTrue;\n  window.NDL_setWindSpd = setWindSpd;\n\n  recomputeRelativeWind();\n  updateBaseClassDisplay();\n  setShipHdg(0);\n\n  function motionLimitsFor(flightType, heliCategory, helideckClass){\n    var table = flightType === 'medevac' ? MOTION_LIMITS_MEDEVAC : MOTION_LIMITS_TREINAMENTO;\n    var byCategory = table[heliCategory];\n    if (!byCategory) return null;\n    return byCategory[helideckClass]; // pode ser null (Classe 3 \u2014 n\u00e3o permitido)\n  }\n\n  // ---------- helideck base class from position ----------\n  function baseClassFromPos(pos){\n    if (pos === 'plataforma') return 1;\n    if (pos === 'fpso') return 1;\n    if (pos === 'popa') return 2;\n    if (pos === 'meianau') return 2;\n    if (pos === 'proa') return 3;\n    if (pos === 'superestrutura') return 3;\n    return 3;\n  }\n\n  // ---------- sector classification ----------\n  // windDir: 0 = from bow (headwind), 90 = from starboard beam, 180 = from stern, 270 = from port beam\n  // \"alheta\" (quarter) zones: roughly 112.5-157.5 and 202.5-247.5 (around 135/225)\n  // \"popa\" zone: around 180 (157.5 - 202.5)\n  function isAlhetaOrPopa(dir){\n    var d = ((dir % 360)+360)%360;\n    return d >= 112.5 && d <= 247.5;\n  }\n\n  function classify(){\n    var base = baseClassFromPos(state.deckPos);\n    // S\u00f3 considerar a dire\u00e7\u00e3o do vento para fins de reclassifica\u00e7\u00e3o quando houver\n    // intensidade de vento de fato informada. Com vento zerado (n\u00e3o reportado),\n    // a dire\u00e7\u00e3o relativa n\u00e3o tem significado operacional e n\u00e3o deve reclassificar\n    // a UM apenas por efeito colateral de girar a proa.\n    var alhetaPopa = state.windSpd > 0 && isAlhetaOrPopa(state.windDir);\n    var effective = base;\n    var reclassified = false;\n\n    if (base === 2 && alhetaPopa){\n      effective = 3; reclassified = true;\n    } else if (base === 3 && alhetaPopa){\n      effective = 2; reclassified = true;\n    }\n    // base 1 stays 1 regardless (SOP doesn't define reclassification for Class 1)\n\n    return { base: base, effective: effective, reclassified: reclassified, alhetaPopa: alhetaPopa };\n  }\n\n  // crosswind component relative to approach/final course.\n  // Approximate: final approach course is aligned with the SLO bisector (bow-stern axis, 0/180),\n  // except when alheta/popa wind forces operational class-3 treatment -> approach would be across structure.\n  function crosswindComponent(dir, spd){\n    var d = ((dir % 360)+360)%360;\n    // angle relative to bow-stern axis (0 or 180 = headwind/tailwind axis = aligned w/ SLO)\n    var rel = Math.min(Math.abs(d-0), Math.abs(d-180), Math.abs(d-360));\n    var rad = rel * Math.PI/180;\n    return Math.abs(spd * Math.sin(rad));\n  }\n\n  // ---------- render SVG ----------\n\n  function polar(cx,cy,r,deg){\n    // deg: 0 = up (bow), clockwise\n    var rad = (deg-90) * Math.PI/180;\n    return [cx + r*Math.cos(rad), cy + r*Math.sin(rad)];\n  }\n\n  function arcPath(cx,cy,r,startDeg,endDeg){\n    var p1 = polar(cx,cy,r,startDeg);\n    var p2 = polar(cx,cy,r,endDeg);\n    var large = (endDeg-startDeg) > 180 ? 1 : 0;\n    return 'M '+cx+' '+cy+' L '+p1[0]+' '+p1[1]+' A '+r+' '+r+' 0 '+large+' 1 '+p2[0]+' '+p2[1]+' Z';\n  }\n\n  function deckPosOnShip(pos){\n    // returns [x,y] of deck H marker, bow is at top (deg 0 / -y), stern at bottom\n    if (pos === 'plataforma') return [CX, CY];\n    if (pos === 'proa') return [CX, CY - SHIP_LEN*0.36];\n    if (pos === 'meianau') return [CX, CY];\n    if (pos === 'popa') return [CX, CY + SHIP_LEN*0.34];\n    if (pos === 'fpso') return [CX, CY + SHIP_LEN*0.34];\n    if (pos === 'superestrutura') return [CX, CY - SHIP_LEN*0.10];\n    return [CX, CY];\n  }\n\n  function render(){\n    var cls = classify();\n    var deckXY = deckPosOnShip(state.deckPos);\n    var deckX = deckXY[0], deckY = deckXY[1]; // posi\u00e7\u00e3o do helideque NO REFERENCIAL DO NAVIO (proa=0, sempre p/ cima antes da rota\u00e7\u00e3o)\n\n    var svgParts = [];\n    svgParts.push('<defs>',\n      '<radialGradient id=\"seaGrad\" cx=\"50%\" cy=\"50%\" r=\"75%\">',\n        '<stop offset=\"0%\" stop-color=\"#1c3f7a\"/>',\n        '<stop offset=\"100%\" stop-color=\"#0a1530\"/>',\n      '</radialGradient>',\n      '<marker id=\"arrowHead\" markerWidth=\"10\" markerHeight=\"10\" refX=\"6\" refY=\"3\" orient=\"auto\" markerUnits=\"strokeWidth\">',\n        '<path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#ffc400\"/>',\n      '</marker>',\n    '</defs>');\n\n    svgParts.push('<rect x=\"0\" y=\"0\" width=\"440\" height=\"470\" fill=\"url(#seaGrad)\"/>');\n\n    // ---------- fixed compass ring (N up, does NOT rotate) ----------\n    svgParts.push('<circle cx=\"'+CX+'\" cy=\"'+CY+'\" r=\"'+ringR+'\" fill=\"none\" stroke=\"#2e5fa8\" stroke-width=\"2\"/>');\n    [70,120,170].forEach(function(r){\n      svgParts.push('<circle cx=\"'+CX+'\" cy=\"'+CY+'\" r=\"'+r+'\" fill=\"none\" stroke=\"#13302695\" stroke-width=\"1\" stroke-dasharray=\"2 6\"/>');\n    });\n    // tick marks every 30\u00b0, fixed to compass (true/magnetic north up)\n    for (var td=0; td<360; td+=30){\n      var tp1 = polar(CX, CY, ringR, td);\n      var tp2 = polar(CX, CY, ringR-12, td);\n      svgParts.push('<line x1=\"'+tp1[0]+'\" y1=\"'+tp1[1]+'\" x2=\"'+tp2[0]+'\" y2=\"'+tp2[1]+'\" stroke=\"#4f8fe6\" stroke-width=\"2\"/>');\n    }\n    var compassCardinals = [[0,'N'],[90,'E'],[180,'S'],[270,'O']];\n    compassCardinals.forEach(function(c){\n      var clp = polar(CX, CY, ringR-26, c[0]);\n      svgParts.push('<text x=\"'+clp[0]+'\" y=\"'+(clp[1]+6)+'\" text-anchor=\"middle\" fill=\"#9fc4ff\" font-size=\"17\" font-weight=\"700\" font-family=\"JetBrains Mono, monospace\">'+c[1]+'</text>');\n    });\n\n    // ---------- rotating ship group (rotates with shipHdg around CX,CY) ----------\n    svgParts.push('<g transform=\"rotate('+state.shipHdg+' '+CX+' '+CY+')\">');\n\n    // SLO sectors em torno da letra H, refer\u00eancia de aproxima\u00e7\u00e3o (item 6.1 / p\u00e1g.10 da SOP)\n    // IMPORTANTE: a orienta\u00e7\u00e3o do SLO depende exclusivamente da posi\u00e7\u00e3o do helideque na UM\n    // (campo 1) e NUNCA do vento informado. A reclassifica\u00e7\u00e3o de classe por vento de alheta/popa\n    // (ver classify()) afeta apenas o veredito de aprova\u00e7\u00e3o/proibi\u00e7\u00e3o da opera\u00e7\u00e3o, n\u00e3o o desenho.\n    var R = 150;\n    var sectors;\n\n    if (state.deckPos === 'meianau'){\n      // Padr\u00e3o \"borboleta\": 2 faixas verdes de ~45\u00b0 nos travesses, resto vermelho.\n      var halfGreen = 22.5; // ~45\u00b0 de largura total por faixa verde\n      sectors = [\n        {a0:90-halfGreen, a1:90+halfGreen, color:'green'},\n        {a0:270-halfGreen, a1:270+halfGreen, color:'green'},\n        {a0:90+halfGreen, a1:270-halfGreen, color:'red'},\n        {a0:270+halfGreen, a1:90-halfGreen+360, color:'red'}\n      ];\n    } else {\n      // Padr\u00e3o simples: um \u00fanico setor de 210\u00b0 verde (\u00e1rea livre) e 150\u00b0 vermelho (lado da estrutura),\n      // referenciado a partir da letra H, conforme item 6.1 / figuras da p\u00e1g. 10 da SOP.\n      var redCenter = (state.deckPos === 'proa' || state.deckPos === 'superestrutura' || state.deckPos === 'plataforma') ? 180 : 0;\n\n      sectors = [\n        {a0: redCenter - 75, a1: redCenter + 75, color:'red'},      // 150\u00b0 vermelho\n        {a0: redCenter + 75, a1: redCenter + 75 + 210, color:'green'} // 210\u00b0 verde (resto do c\u00edrculo)\n      ];\n    }\n\n    sectors.forEach(function(s){\n      var fill = s.color === 'green' ? 'rgba(43,255,126,0.42)' : 'rgba(255,59,59,0.40)';\n      var stroke = s.color === 'green' ? 'rgba(43,255,126,0.9)' : 'rgba(255,59,59,0.85)';\n      svgParts.push('<path d=\"'+arcPath(deckX, deckY, R, s.a0, s.a1)+'\" fill=\"'+fill+'\" stroke=\"'+stroke+'\" stroke-width=\"1\"/>');\n    });\n\n    // ship hull silhouette (ship-relative: bow always at top before rotation)\n    if (state.deckPos === 'plataforma'){\n      // Estrutura compacta de plataforma/FPSO (2\u00aa figura, p\u00e1g.10 da SOP): corpo quadrado/industrial,\n      // sem proa/popa afiladas, com m\u00f3dulos salientes simulando equipamentos de plataforma.\n      // Posicionada dentro do setor vermelho (lado oposto \u00e0 proa/SLO), com a face voltada para o H\n      // perpendicular \u00e0 linha H\u2192estrutura \u2014 o H fica encostado na borda superior da estrutura.\n      var pW = SHIP_W * 1.55, pH = SHIP_LEN * 0.42;\n      var pX0 = deckX - pW/2, pY0 = deckY;\n      svgParts.push('<rect x=\"'+pX0+'\" y=\"'+pY0+'\" width=\"'+pW+'\" height=\"'+pH+'\" rx=\"6\" fill=\"#143058\" stroke=\"#4f8fe6\" stroke-width=\"2.5\"/>');\n      // m\u00f3dulos internos (equipamentos), posi\u00e7\u00f5es relativas ao corpo\n      svgParts.push('<rect x=\"'+(pX0+pW*0.10)+'\" y=\"'+(pY0+pH*0.12)+'\" width=\"'+(pW*0.32)+'\" height=\"'+(pH*0.30)+'\" rx=\"2\" fill=\"#1c4070\" stroke=\"#4f8fe6\" stroke-width=\"1.5\"/>');\n      svgParts.push('<rect x=\"'+(pX0+pW*0.52)+'\" y=\"'+(pY0+pH*0.08)+'\" width=\"'+(pW*0.38)+'\" height=\"'+(pH*0.40)+'\" rx=\"2\" fill=\"#1c4070\" stroke=\"#4f8fe6\" stroke-width=\"1.5\"/>');\n      svgParts.push('<rect x=\"'+(pX0+pW*0.14)+'\" y=\"'+(pY0+pH*0.56)+'\" width=\"'+(pW*0.66)+'\" height=\"'+(pH*0.32)+'\" rx=\"2\" fill=\"#1c4070\" stroke=\"#4f8fe6\" stroke-width=\"1.5\"/>');\n      // pequenas sali\u00eancias (guindastes/antenas) nas bordas\n      svgParts.push('<rect x=\"'+(pX0+pW*0.88)+'\" y=\"'+(pY0+pH*0.20)+'\" width=\"'+(pW*0.10)+'\" height=\"'+(pH*0.14)+'\" fill=\"#1c4070\" stroke=\"#4f8fe6\" stroke-width=\"1.2\"/>');\n      svgParts.push('<rect x=\"'+(pX0+pW*0.88)+'\" y=\"'+(pY0+pH*0.66)+'\" width=\"'+(pW*0.10)+'\" height=\"'+(pH*0.14)+'\" fill=\"#1c4070\" stroke=\"#4f8fe6\" stroke-width=\"1.2\"/>');\n    } else {\n      var hullPts = [\n        [CX, CY-SHIP_LEN/2],\n        [CX+SHIP_W/2, CY-SHIP_LEN/2+38],\n        [CX+SHIP_W/2, CY+SHIP_LEN/2-18],\n        [CX+SHIP_W*0.35, CY+SHIP_LEN/2],\n        [CX-SHIP_W*0.35, CY+SHIP_LEN/2],\n        [CX-SHIP_W/2, CY+SHIP_LEN/2-18],\n        [CX-SHIP_W/2, CY-SHIP_LEN/2+38]\n      ];\n      var hullD = 'M '+hullPts.map(function(p){return p[0]+' '+p[1];}).join(' L ')+' Z';\n      svgParts.push('<path d=\"'+hullD+'\" fill=\"#143058\" fill-opacity=\"0.78\" stroke=\"#4f8fe6\" stroke-width=\"2.5\"/>');\n\n      // superstructure block\n      svgParts.push('<rect x=\"'+(CX-SHIP_W*0.30)+'\" y=\"'+(CY+SHIP_LEN*0.18)+'\" width=\"'+(SHIP_W*0.60)+'\" height=\"'+(SHIP_LEN*0.22)+'\" rx=\"3\" fill=\"#1c4070\" stroke=\"#4f8fe6\" stroke-width=\"1.5\"/>');\n    }\n\n    // bow / stern labels (rotate with the ship) \u2014 n\u00e3o exibidos para plataforma/FPSO, que n\u00e3o tem proa/popa n\u00e1utica\n    if (state.deckPos !== 'plataforma'){\n      svgParts.push('<text x=\"'+CX+'\" y=\"'+(CY-SHIP_LEN/2-12)+'\" text-anchor=\"middle\" fill=\"#9fc4ff\" font-size=\"15\" font-family=\"JetBrains Mono, monospace\" letter-spacing=\"2\" transform=\"rotate('+(-state.shipHdg)+' '+CX+' '+(CY-SHIP_LEN/2-12)+')\">PROA</text>');\n      svgParts.push('<text x=\"'+CX+'\" y=\"'+(CY+SHIP_LEN/2+22)+'\" text-anchor=\"middle\" fill=\"#9fc4ff\" font-size=\"15\" font-family=\"JetBrains Mono, monospace\" letter-spacing=\"2\" transform=\"rotate('+(-state.shipHdg)+' '+CX+' '+(CY+SHIP_LEN/2+22)+')\">POPA</text>');\n    }\n\n    // helideck marker (H octagon)\n    var hr = 17;\n    var oct = [];\n    for (var i=0;i<8;i++){\n      var ang = i*45 + 22.5;\n      var p = polar(deckX, deckY, hr, ang);\n      oct.push(p[0]+','+p[1]);\n    }\n    svgParts.push('<polygon points=\"'+oct.join(' ')+'\" fill=\"#0f3a28\" stroke=\"#2bff7e\" stroke-width=\"2.5\"/>');\n    var hRotationExtra = (state.deckPos === 'meianau') ? 0 : 90;\n    svgParts.push('<text x=\"'+deckX+'\" y=\"'+(deckY+7)+'\" text-anchor=\"middle\" fill=\"#2bff7e\" font-size=\"20\" font-weight=\"700\" font-family=\"JetBrains Mono, monospace\" transform=\"rotate('+hRotationExtra+' '+deckX+' '+deckY+')\">H</text>');\n\n    // recommended final-approach course line, in ship-relative angle (still rotates with ship)\n    var approachAngleRel = nearestGreenApproach(sectors, state.windDir);\n    if (approachAngleRel !== null){\n      var farPt = polar(deckX, deckY, 175, approachAngleRel);\n      svgParts.push('<line x1=\"'+farPt[0]+'\" y1=\"'+farPt[1]+'\" x2=\"'+deckX+'\" y2=\"'+deckY+'\" stroke=\"#ffffff\" stroke-width=\"2\" stroke-dasharray=\"6 5\" opacity=\"0.85\"/>');\n      var planeTip = polar(deckX, deckY, 60, approachAngleRel);\n      svgParts.push('<circle cx=\"'+planeTip[0]+'\" cy=\"'+planeTip[1]+'\" r=\"5\" fill=\"#ffffff\"/>');\n    }\n\n    svgParts.push('</g>'); // end rotating ship group\n\n    // ---------- wind arrow: FIXED to compass (true direction), does not rotate with ship ----------\n    var windTrueDeg = state.windDirTrue;\n    var arrowHeadLen = 14;     // comprimento da ponta triangular\n    var arrowHeadWidth = 14;   // largura da base da ponta triangular\n    var shaftLen = 8;          // comprimento do cabo da flecha (entre cauda e base da ponta)\n    var tailExtra = 5;         // pequeno prolongamento do cabo al\u00e9m da cauda (efeito de \"rabo\" da flecha)\n\n    var headTipPt = polar(CX, CY, ringR, windTrueDeg);                          // ponta, encosta no anel\n    var headBasePt = polar(CX, CY, ringR + arrowHeadLen, windTrueDeg);          // base da ponta triangular\n    var tailEndPt = polar(CX, CY, ringR + arrowHeadLen + shaftLen + tailExtra, windTrueDeg); // prolongamento al\u00e9m da cauda\n\n    // cabo da flecha (linha grossa), incluindo o pequeno prolongamento na cauda\n    svgParts.push('<line x1=\"'+tailEndPt[0]+'\" y1=\"'+tailEndPt[1]+'\" x2=\"'+headBasePt[0]+'\" y2=\"'+headBasePt[1]+'\" stroke=\"#ffc400\" stroke-width=\"5\" stroke-linecap=\"round\"/>');\n\n    // ponta triangular da flecha\n    var perp = windTrueDeg + 90;\n    var leftBase = polar(headBasePt[0], headBasePt[1], arrowHeadWidth/2, perp);\n    var rightBase = polar(headBasePt[0], headBasePt[1], arrowHeadWidth/2, perp+180);\n    svgParts.push('<polygon points=\"'+headTipPt[0]+','+headTipPt[1]+' '+leftBase[0]+','+leftBase[1]+' '+rightBase[0]+','+rightBase[1]+'\" fill=\"#ffc400\" stroke=\"#cc8800\" stroke-width=\"1.5\"/>');\n\n    deckSvgEl.setAttribute('viewBox','0 0 440 470');\n    deckSvgEl.innerHTML = svgParts.join('');\n\n    // invisible draggable overlay handled separately (see compass drag handlers)\n    renderVerdict(cls, approachAngleRel);\n    updatePousoAssento();\n  }\n\n  // ---------- campo 06: Pouso / Assento (flags autom\u00e1ticas, seguem sempre a proa/vento atuais) ----------\n  function updatePousoAssento(){\n    var esqEl = document.getElementById('pouseAssentoEsquerda');\n    var dirEl = document.getElementById('pouseAssentoDireita');\n    if (!esqEl || !dirEl) return;\n\n    var esquerda = false, direita = false;\n\n    if (state.deckPos === 'fpso' || state.deckPos === 'popa'){\n      var rel = normDeg(state.windDirTrue - state.shipHdg); // graus a mais que a proa\n      if (rel === 0 || rel === 180){\n        esquerda = true; direita = true;\n      } else if (rel >= 1 && rel <= 179){\n        esquerda = true;\n      } else if (rel >= 181 && rel <= 359){\n        direita = true;\n      }\n    } else if (state.deckPos === 'proa' || state.deckPos === 'plataforma'){\n      // l\u00f3gica invertida em rela\u00e7\u00e3o a FPSO/Popa\n      var relP = normDeg(state.windDirTrue - state.shipHdg);\n      if (relP === 0 || relP === 180){\n        esquerda = true; direita = true;\n      } else if (relP >= 1 && relP <= 179){\n        direita = true;\n      } else if (relP >= 181 && relP <= 359){\n        esquerda = true;\n      }\n    } else if (state.deckPos === 'meianau'){\n      var relM = normDeg(state.windDirTrue - state.shipHdg);\n      if (relM === 90 || relM === 270){\n        esquerda = true; direita = true;\n      } else if ((relM >= 0 && relM <= 89) || (relM >= 180 && relM <= 269)){\n        direita = true;\n      } else if ((relM >= 91 && relM <= 179) || (relM >= 271 && relM <= 359)){\n        esquerda = true;\n      }\n    }\n\n    esqEl.classList.toggle('checked', esquerda);\n    dirEl.classList.toggle('checked', direita);\n  }\n\n  function angDiff(a,b){\n    var d = Math.abs(a-b) % 360;\n    return d > 180 ? 360-d : d;\n  }\n\n  function nearestGreenApproach(sectors, windFromDeg){\n    // approach should come FROM the green sector that is most upwind-aligned i.e. closest to windFromDeg\n    var greens = sectors.filter(function(s){ return s.color==='green'; });\n    if (!greens.length) return null;\n    var best = null, bestDiff = 999;\n    greens.forEach(function(s){\n      var center = ((s.a0+s.a1)/2);\n      var diff = angDiff(center, windFromDeg);\n      if (diff < bestDiff){ bestDiff = diff; best = center; }\n    });\n    return best;\n  }\n\n  // ---------- verdict logic ----------\n  function renderVerdict(cls, approachAngle){\n    var panel = document.getElementById('verdictPanel');\n    var label = document.getElementById('verdictLabel');\n    var reason = document.getElementById('verdictReason');\n    var classOut = document.getElementById('verdictClass');\n    var crossOut = document.getElementById('metricCross');\n    var compOut = document.getElementById('metricComponent');\n    var limitOut = document.getElementById('metricLimit');\n\n    var crosswindLimit = crosswindLimitFor(state.flightType);\n    var cautionThreshold = crosswindLimit * 0.7; // margem reduzida a partir de 70% do limite\n    var flightTypeLabel = state.flightType === 'medevac' ? 'MEDEVAC' : 'treinamento';\n\n    var crosswind = crosswindComponent(state.windDir, state.windSpd);\n    crossOut.textContent = crosswind.toFixed(1)+' kt';\n    limitOut.textContent = crosswindLimit+' kt';\n\n    var classLabel = 'Classe '+cls.effective + (cls.reclassified ? ' (reclassificada de '+cls.base+')' : ' (certificada)');\n    classOut.innerHTML = classLabel;\n\n    panel.classList.remove('go','caution','no-go');\n\n    if (cls.effective === 3){\n      panel.classList.add('no-go');\n      label.textContent = 'OPERA\u00c7\u00c3O NOTURNA PROIBIDA';\n      compOut.textContent = '\u2014';\n      compOut.classList.add('bad');\n      reason.innerHTML = 'Com vento de <b>'+String(state.windDir).padStart(3,'0')+'\u00b0</b> a <b>'+state.windSpd+' kt</b>, o helideque opera como <b>Classe 3</b>. A SOP 43 (item 6.1) pro\u00edbe opera\u00e7\u00f5es noturnas nesta condi\u00e7\u00e3o nas AJB. O voo deve ser <b>CANCELADO</b>.';\n      return;\n    }\n\n    compOut.classList.remove('bad');\n\n    if (crosswind > crosswindLimit){\n      panel.classList.add('no-go');\n      label.textContent = 'CANCELAR \u2014 VENTO ACIMA DO LIMITE';\n      compOut.textContent = 'ACIMA DO LIMITE';\n      compOut.classList.add('bad');\n      reason.innerHTML = 'A componente de vento de trav\u00e9s da trajet\u00f3ria de aproxima\u00e7\u00e3o \u00e9 de <b>'+crosswind.toFixed(1)+' kt</b>, acima do limite de <b>'+crosswindLimit+' kt</b> para voo de '+flightTypeLabel+' offshore noturno (item 6.1, ATEN\u00c7\u00c3O). O voo deve ser <b>CANCELADO</b> se esta for a \u00fanica aproxima\u00e7\u00e3o dispon\u00edvel dentro do SLO.';\n    } else if (crosswind > cautionThreshold){\n      panel.classList.add('caution');\n      label.textContent = 'ATEN\u00c7\u00c3O \u2014 PR\u00d3XIMO AO LIMITE';\n      compOut.textContent = 'MARGINAL';\n      reason.innerHTML = 'Componente de vento de trav\u00e9s de <b>'+crosswind.toFixed(1)+' kt</b>, dentro do limite de '+crosswindLimit+' kt ('+flightTypeLabel+') mas com margem reduzida. Confirmar alinhamento da aproxima\u00e7\u00e3o final dentro do SLO (\u00e1rea verde) e reavaliar no Helideck Report atualizado antes da partida.';\n    } else {\n      panel.classList.add('go');\n      label.textContent = 'APROXIMA\u00c7\u00c3O DENTRO DO SLO';\n      compOut.textContent = 'DENTRO DO LIMITE';\n      var approachTxt = approachAngle !== null ? Math.round(approachAngle)+'\u00b0' : '\u2014';\n      reason.innerHTML = 'Helideque classificado como <b>Classe '+cls.effective+'</b>. Componente de vento de trav\u00e9s de <b>'+crosswind.toFixed(1)+' kt</b> (limite '+crosswindLimit+' kt, '+flightTypeLabel+'). Proa de aproxima\u00e7\u00e3o final recomendada, alinhada ao SLO: aproximadamente <b>'+approachTxt+'</b> em rela\u00e7\u00e3o \u00e0 proa da UM. Confirmar refer\u00eancias visuais e ilumina\u00e7\u00e3o do helideque antes do Commited Point (LDP).';\n    }\n  }\n\n  // ---------- campo 10: Relat\u00f3rios (PDF com dados dos campos 01 a 08, incluindo 07) ----------\n  function pousoAssentoReportText(){\n    var esqEl = document.getElementById('pouseAssentoEsquerda');\n    var dirEl = document.getElementById('pouseAssentoDireita');\n    var esq = esqEl && esqEl.classList.contains('checked');\n    var dir = dirEl && dirEl.classList.contains('checked');\n    if (esq && dir) return 'Direita e Esquerda';\n    if (dir) return 'Direita';\n    if (esq) return 'Esquerda';\n    return '\u2014';\n  }\n\n  function buildReportSections(){\n    function val(id){ var el = document.getElementById(id); return el ? el.value : ''; }\n    function txt(id){ var el = document.getElementById(id); return el ? el.textContent.trim() : '\u2014'; }\n    function activeTxt(sel){ var el = document.querySelector(sel); return el ? el.textContent.trim().replace(/\\s+/g,' ') : '\u2014'; }\n\n    var sections = [];\n\n    sections.push({\n      campo: '01', titulo: 'Registro de Hor\u00e1rios e Trajeto',\n      itens: [\n        ['Acionamento', val('flogAcionamento') || '\u2014'],\n        ['Cron\u00f4metro', val('flogCronometro') || '--:--:--'],\n        ['Tempo para Decolagem', val('flogTempoDecolagem') || '\u2014'],\n        ['1\u00aa Perna \u2014 Origem', val('flogOrigem1') || '\u2014'],\n        ['1\u00aa Perna \u2014 Destino', val('flogDestino1') || '\u2014'],\n        ['1\u00aa Perna \u2014 Partida', val('flogPartida1') || '\u2014'],\n        ['1\u00aa Perna \u2014 Decolagem', val('flogDecolagem1') || '\u2014'],\n        ['1\u00aa Perna \u2014 Pouso', val('flogPouso1') || '\u2014'],\n        ['1\u00aa Perna \u2014 Corte', val('flogCorte1') || '\u2014'],\n        ['2\u00aa Perna \u2014 Origem', val('flogOrigem2') || '\u2014'],\n        ['2\u00aa Perna \u2014 Destino', val('flogDestino2') || '\u2014'],\n        ['2\u00aa Perna \u2014 Partida', val('flogPartida2') || '\u2014'],\n        ['2\u00aa Perna \u2014 Decolagem', val('flogDecolagem2') || '\u2014'],\n        ['2\u00aa Perna \u2014 Pouso', val('flogPouso2') || '\u2014'],\n        ['2\u00aa Perna \u2014 Corte', val('flogCorte2') || '\u2014']\n      ]\n    });\n\n    var clistItens = [];\n    Object.keys(CLIST_DATA).forEach(function(key){\n      var d = CLIST_DATA[key];\n      var checked = clistCheckedCount(key);\n      var total = d.items.length;\n      var isGo = (d.mode === 'any') ? (checked >= 1) : (checked === total);\n      clistItens.push([d.title, checked + '/' + total + ' \u2014 ' + (isGo ? 'OK' : 'PENDENTE')]);\n    });\n    sections.push({ campo: '02', titulo: 'Checklists', itens: clistItens });\n\n    sections.push({\n      campo: '03', titulo: 'Tipo de Voo',\n      itens: [['Tipo selecionado', activeTxt('.ft-btn.active .ft-btn-title')]]\n    });\n\n    sections.push({\n      campo: '04', titulo: 'Posi\u00e7\u00e3o do helideque na UM',\n      itens: [\n        ['Posi\u00e7\u00e3o selecionada', activeTxt('.deck-pos-btn.active')],\n        ['Classe certificada', txt('baseClassOut')]\n      ]\n    });\n\n    sections.push({\n      campo: '05', titulo: 'Proa da UM & Vento',\n      itens: [\n        ['Proa da UM', String(state.shipHdg).padStart(3,'0') + '\u00b0'],\n        ['Dire\u00e7\u00e3o do vento (verdadeira)', String(state.windDirTrue).padStart(3,'0') + '\u00b0'],\n        ['Intensidade do vento', state.windSpd + ' kt'],\n        ['Vento relativo \u00e0 proa', String(state.windDir).padStart(3,'0') + '\u00b0']\n      ]\n    });\n\n    sections.push({\n      campo: '06', titulo: 'B\u00fassola \u2014 SLO e Veredito de Vento',\n      itens: [\n        ['Veredito', txt('verdictLabel')],\n        ['Classe operacional', txt('verdictClass').replace(/\\s+/g,' ')],\n        ['Vento de trav\u00e9s', txt('metricCross')],\n        ['Componente', txt('metricComponent')],\n        ['Limite', txt('metricLimit')],\n        ['Pouso / Assento', pousoAssentoReportText()]\n      ]\n    });\n\n    (function(){\n      var wccHdgEl2 = document.getElementById('wccInpHdg');\n      var wccDirEl2 = document.getElementById('wccInpDir');\n      var wccHdg = wccHdgEl2 ? wccHdgEl2.value.trim() : '';\n      var wccDir = wccDirEl2 ? wccDirEl2.value.trim() : '';\n      var wccSpdEl = document.getElementById('wccInpSpd');\n      var wccSpd = wccSpdEl && wccSpdEl.value ? wccSpdEl.value + ' kt' : '\u2014';\n      var wccHasResult = document.getElementById('wccOutCross');\n      var itens = [\n        ['Proa de Aproxima\u00e7\u00e3o', wccHdg || '\u2014'],\n        ['Dire\u00e7\u00e3o do Vento', wccDir || '\u2014'],\n        ['Intensidade do Vento', wccSpd]\n      ];\n      if (wccHasResult) {\n        itens.push(['Vento de Trav\u00e9s', txt('wccOutCross') + ' ' + txt('wccOutCrossHint')]);\n        itens.push([txt('wccOutHeadLabel') || 'Vento de Proa/Cauda', txt('wccOutHead')]);\n        itens.push(['\u00c2ngulo Relativo', txt('wccOutAngle')]);\n      }\n      var banner = document.getElementById('wccLimitBanner');\n      if (banner && banner.style.display === 'block' && banner.textContent) {\n        itens.push(['\u26a0 Alerta', banner.textContent.trim()]);\n      }\n      sections.push({\n        campo: '07', titulo: 'Gr\u00e1fico de Componentes de Vento',\n        itens: itens\n      });\n    })();\n\n    sections.push({\n      campo: '08', titulo: 'Limites de Movimento do Helideque',\n      itens: [\n        ['Categoria do helic\u00f3ptero', activeTxt('#heliCategoryRow .qbtn.active')],\n        ['Pitch e Roll', (state.motionBC/10).toFixed(1) + '\u00b0'],\n        ['Inclina\u00e7\u00e3o', (state.motionInc/10).toFixed(1) + '\u00b0'],\n        ['Heave Rate', (state.motionVArf/10).toFixed(1) + ' m/s'],\n        ['Heave', (state.motionArf/10).toFixed(1) + ' m'],\n        ['Tipo de voo (limites)', txt('motionFlightTypeOut')],\n        ['Classe da UM (limites)', txt('motionClassOut')],\n        ['Tabela aplic\u00e1vel', txt('motionTableOut')],\n        ['Veredito de movimento', txt('motionVerdictLabel')],\n        ['Pitch e Roll \u2014 limite', txt('limitBCOut')],\n        ['Inc \u2014 limite', txt('limitIncOut')],\n        ['Heave Rate \u2014 limite', txt('limitVArfOut')],\n        ['Heave \u2014 limite', txt('limitArfOut')]\n      ]\n    });\n\n    return sections;\n  }\n\n  function renderReportPreviewHtml(sections, targetEl){\n    var piloto = (document.getElementById('crewPiloto').value || '');\n    var coPiloto = (document.getElementById('crewCoPiloto').value || '');\n    var html = '';\n    html += '<h3>SOP 43 \u2014 Relat\u00f3rio de Voo Noturno Offshore</h3>';\n    html += '<div class=\"rp-item\"><span class=\"rp-label\">Piloto</span><span class=\"rp-value rp-value-bold\">' + piloto.toUpperCase() + '</span></div>';\n    html += '<div class=\"rp-item\"><span class=\"rp-label\">Co-Piloto</span><span class=\"rp-value rp-value-bold\">' + coPiloto.toUpperCase() + '</span></div>';\n    html += '<div class=\"rp-meta\">Gerado em: ' + new Date().toLocaleString('pt-BR') + '</div>';\n    sections.forEach(function(sec){\n      html += '<div class=\"rp-section\">';\n      html += '<div class=\"rp-section-title\">Campo ' + sec.campo + ' \u2014 ' + sec.titulo + '</div>';\n      sec.itens.forEach(function(item){\n        html += '<div class=\"rp-item\"><span class=\"rp-label\">' + item[0] + '</span><span class=\"rp-value\">' + String(item[1]).toUpperCase() + '</span></div>';\n      });\n      html += '</div>';\n    });\n    (targetEl || reportPreviewBody).innerHTML = html;\n  }\n\n  var reportPrintBtn = document.getElementById('reportPrintBtn');\n  var reportActions = document.getElementById('reportActions');\n  var reportPreviewBody = document.getElementById('reportPreviewBody');\n  var reportShareBtn = document.getElementById('reportShareBtn');\n  var reportShareNote = document.getElementById('reportShareNote');\n  var currentReportSections = null;\n\n  reportPrintBtn.addEventListener('click', function(){\n    currentReportSections = buildReportSections();\n    renderReportPreviewHtml(currentReportSections);\n    reportActions.style.display = 'block';\n    reportShareNote.style.display = 'none';\n    reportActions.scrollIntoView({ behavior:'smooth', block:'start' });\n  });\n\n  document.getElementById('reportCloseBtn').addEventListener('click', function(){\n    reportActions.style.display = 'none';\n  });\n\n  // ---------- gerador de PDF 100% embutido (sem biblioteca externa/CDN) ----------\n  // Monta um arquivo .pdf v\u00e1lido manualmente (texto simples, fontes padr\u00e3o do PDF),\n  // e aciona o download nativo do navegador \u2014 funciona offline, sem depender de\n  // window.print() nem de nenhuma rede externa.\n  function buildSimplePdfBlob(sections){\n    var PAGE_W = 595, PAGE_H = 842, MARGIN = 40;\n\n    var PUNCT_MAP = {\n      '\\u2014': String.fromCharCode(0x97), // em dash \u2014\n      '\\u2013': String.fromCharCode(0x96), // en dash \u2013\n      '\\u2018': String.fromCharCode(0x91), // ' esquerda\n      '\\u2019': String.fromCharCode(0x92), // ' direita\n      '\\u201C': String.fromCharCode(0x93), // \" esquerda\n      '\\u201D': String.fromCharCode(0x94)  // \" direita\n    };\n    function toLatin1(s){\n      var out = '';\n      for (var i = 0; i < s.length; i++){\n        var ch = s[i];\n        if (PUNCT_MAP[ch]){ out += PUNCT_MAP[ch]; continue; }\n        var code = s.charCodeAt(i);\n        out += (code <= 255) ? String.fromCharCode(code) : '-';\n      }\n      return out;\n    }\n    function esc(s){\n      return toLatin1(String(s)).replace(/\\\\/g,'\\\\\\\\').replace(/\\(/g,'\\\\(').replace(/\\)/g,'\\\\)');\n    }\n    function approxCharsForSize(size){\n      return Math.max(10, Math.floor((PAGE_W - MARGIN*2) / (size * 0.52)));\n    }\n    function wrapLine(text, size){\n      var maxChars = approxCharsForSize(size);\n      text = String(text);\n      if (text.length <= maxChars) return [text];\n      var words = text.split(' ');\n      var lines = [], cur = '';\n      words.forEach(function(w){\n        var test = cur ? (cur + ' ' + w) : w;\n        if (test.length > maxChars){\n          if (cur) lines.push(cur);\n          cur = w;\n        } else {\n          cur = test;\n        }\n      });\n      if (cur) lines.push(cur);\n      return lines;\n    }\n\n    // 1) monta a lista plana de linhas (com quebra de texto)\n    var flat = [];\n    function addLine(text, size, bold){\n      wrapLine(text, size).forEach(function(l){\n        flat.push({ text:l, size:size, bold:!!bold });\n      });\n    }\n    addLine('SOP 43 - Relatorio de Voo Noturno Offshore', 15, true);\n    var pilotoNome = (document.getElementById('crewPiloto').value || '').toUpperCase();\n    var coPilotoNome = (document.getElementById('crewCoPiloto').value || '').toUpperCase();\n    addLine('Piloto: ' + pilotoNome + '   |   Co-Piloto: ' + coPilotoNome, 10, true);\n    addLine('Gerado em: ' + new Date().toLocaleString('pt-BR'), 9, false);\n    flat.push({ text:'', size:8, bold:false });\n    sections.forEach(function(sec){\n      flat.push({ text:'', size:6, bold:false });\n      addLine('CAMPO ' + sec.campo + ' - ' + sec.titulo.toUpperCase(), 12, true);\n      sec.itens.forEach(function(item){\n        addLine(item[0] + ': ' + String(item[1]).toUpperCase(), 10, false);\n      });\n    });\n\n    // 2) pagina\u00e7\u00e3o\n    var usableH = PAGE_H - MARGIN*2;\n    var pages = [];\n    var cur = [];\n    var curH = 0;\n    flat.forEach(function(ln){\n      var h = ln.size * 1.35;\n      if (curH + h > usableH && cur.length){\n        pages.push(cur);\n        cur = [];\n        curH = 0;\n      }\n      cur.push(ln);\n      curH += h;\n    });\n    pages.push(cur);\n\n    // 3) monta o stream de conte\u00fado de cada p\u00e1gina\n    var contentStreams = pages.map(function(pageLines){\n      var y = PAGE_H - MARGIN;\n      var parts = ['BT'];\n      pageLines.forEach(function(ln){\n        y -= ln.size * 1.35;\n        var fontName = ln.bold ? '/F2' : '/F1';\n        parts.push(fontName + ' ' + ln.size + ' Tf');\n        parts.push('1 0 0 1 ' + MARGIN + ' ' + y.toFixed(2) + ' Tm');\n        parts.push('(' + esc(ln.text) + ') Tj');\n      });\n      parts.push('ET');\n      return parts.join('\\n');\n    });\n\n    // 4) monta os objetos do PDF\n    var pageObjIds = [], contentObjIds = [];\n    var startId = 3;\n    pages.forEach(function(_, i){\n      pageObjIds.push(startId + i*2);\n      contentObjIds.push(startId + i*2 + 1);\n    });\n    var fontF1Id = startId + pages.length*2;\n    var fontF2Id = fontF1Id + 1;\n    var maxId = fontF2Id;\n\n    var objects = {};\n    objects[1] = '<< /Type /Catalog /Pages 2 0 R >>';\n    objects[2] = '<< /Type /Pages /Kids [' + pageObjIds.map(function(id){ return id + ' 0 R'; }).join(' ') + '] /Count ' + pages.length + ' >>';\n    pages.forEach(function(_, i){\n      objects[pageObjIds[i]] = '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ' + PAGE_W + ' ' + PAGE_H + '] /Resources << /Font << /F1 ' + fontF1Id + ' 0 R /F2 ' + fontF2Id + ' 0 R >> >> /Contents ' + contentObjIds[i] + ' 0 R >>';\n    });\n    objects[fontF1Id] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';\n    objects[fontF2Id] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';\n\n    // 5) serializa com offsets de bytes (xref)\n    var out = '%PDF-1.4\\n';\n    var offsets = new Array(maxId + 1).fill(0);\n\n    function appendObj(id, body){\n      offsets[id] = out.length;\n      out += id + ' 0 obj\\n' + body + '\\nendobj\\n';\n    }\n    function appendStreamObj(id, streamText){\n      offsets[id] = out.length;\n      out += id + ' 0 obj\\n<< /Length ' + streamText.length + ' >>\\nstream\\n' + streamText + '\\nendstream\\nendobj\\n';\n    }\n\n    appendObj(1, objects[1]);\n    appendObj(2, objects[2]);\n    pages.forEach(function(_, i){\n      appendObj(pageObjIds[i], objects[pageObjIds[i]]);\n      appendStreamObj(contentObjIds[i], contentStreams[i]);\n    });\n    appendObj(fontF1Id, objects[fontF1Id]);\n    appendObj(fontF2Id, objects[fontF2Id]);\n\n    var xrefStart = out.length;\n    out += 'xref\\n0 ' + (maxId + 1) + '\\n';\n    out += '0000000000 65535 f \\n';\n    for (var id = 1; id <= maxId; id++){\n      out += String(offsets[id] || 0).padStart(10,'0') + ' 00000 n \\n';\n    }\n    out += 'trailer\\n<< /Size ' + (maxId + 1) + ' /Root 1 0 R >>\\nstartxref\\n' + xrefStart + '\\n%%EOF';\n\n    var bytes = new Uint8Array(out.length);\n    for (var i = 0; i < out.length; i++) bytes[i] = out.charCodeAt(i) & 0xFF;\n    return new Blob([bytes], { type:'application/pdf' });\n  }\n\n  function shareBlob(blob, filename){\n    var file = new File([blob], filename, { type:'application/pdf' });\n    if (navigator.canShare && navigator.canShare({ files:[file] })){\n      return navigator.share({\n        files:[file],\n        title:'Relat\u00f3rio NDL',\n        text:'Relat\u00f3rio de voo \u2014 SOP 43'\n      }).then(function(){ return 'shared'; }).catch(function(err){\n        if (err && err.name === 'AbortError') return 'cancelled'; // usu\u00e1rio cancelou o menu \u2014 n\u00e3o \u00e9 erro\n        throw err;\n      });\n    }\n    // dispositivo/navegador sem suporte a compartilhamento de arquivos: abre o\n    // PDF numa nova aba como alternativa, para o usu\u00e1rio enviar manualmente\n    var url = URL.createObjectURL(blob);\n    window.open(url, '_blank');\n    setTimeout(function(){ URL.revokeObjectURL(url); }, 60000);\n    return Promise.resolve('fallback-open');\n  }\n\n  reportShareBtn.addEventListener('click', function(){\n    // gera os dados na hora, mesmo que \"Gerar Relat\u00f3rio\" n\u00e3o tenha sido clicado antes \u2014\n    // assim o bot\u00e3o nunca fica sem fazer nada\n    if (!currentReportSections) currentReportSections = buildReportSections();\n    reportShareNote.style.display = 'none';\n    try {\n      var blob = buildSimplePdfBlob(currentReportSections);\n      var filename = 'Relatorio_NDL_' + new Date().toISOString().slice(0,10) + '.pdf';\n      shareBlob(blob, filename).then(function(result){\n        reportShareNote.style.display = 'block';\n        if (result === 'shared'){\n          reportShareNote.textContent = 'Relat\u00f3rio enviado.';\n        } else if (result === 'cancelled'){\n          reportShareNote.style.display = 'none';\n        } else {\n          reportShareNote.textContent = 'Este navegador n\u00e3o permite enviar o arquivo diretamente por e-mail/WhatsApp. O PDF \"' + filename + '\" foi aberto em uma nova aba \u2014 use o \u00edcone de compartilhar de l\u00e1 para envi\u00e1-lo.';\n        }\n      }).catch(function(err){\n        reportShareNote.style.display = 'block';\n        reportShareNote.textContent = 'N\u00e3o foi poss\u00edvel enviar o PDF (' + (err && err.message ? err.message : err) + ').';\n      });\n    } catch (err){\n      reportShareNote.style.display = 'block';\n      reportShareNote.textContent = 'N\u00e3o foi poss\u00edvel gerar o PDF para envio (' + (err && err.message ? err.message : err) + ').';\n    }\n  });\n\n  // ---------- Novo Voo: limpa todos os campos de uma vez ----------\n  function isEverythingClean(){\n    for (var i=0;i<FLOG_FIELD_IDS.length;i++){\n      var el = document.getElementById(FLOG_FIELD_IDS[i]);\n      if (el && el.value) return false;\n    }\n    for (var k in clistState){ if (clistState[k]) return false; }\n    if (state.flightType !== 'medevac') return false;\n    if (state.deckPos !== 'plataforma') return false;\n    if (state.shipHdg !== 0) return false;\n    if (state.windDirTrue !== 0) return false;\n    if (state.windSpd !== 0) return false;\n    var wccHdgEl = document.getElementById('wccInpHdg');\n    if (wccHdgEl && wccHdgEl.value) return false;\n    var wccDirEl = document.getElementById('wccInpDir');\n    if (wccDirEl && wccDirEl.value) return false;\n    var wccSpdEl = document.getElementById('wccInpSpd');\n    if (wccSpdEl && wccSpdEl.value && wccSpdEl.value !== '0') return false;\n    if (state.heliCategory !== 'A') return false;\n    if (state.motionBC !== 0) return false;\n    if (state.motionInc !== 0) return false;\n    if (state.motionVArf !== 0) return false;\n    if (state.motionArf !== 0) return false;\n    return true;\n  }\n\n  function updateNovoVooState(){\n    var btn = document.getElementById('novoVooBtn');\n    if (!btn) return;\n    btn.classList.toggle('dirty', !isEverythingClean());\n  }\n  window.NDL_updateNovoVooState = updateNovoVooState;\n\n  function resetEverything(){\n    // campo 01\n    clearFlightLog();\n\n    // campo 02\n    clistState = {};\n    saveClistState();\n    updateAllClistButtons();\n\n    // campo 03\n    state.flightType = 'medevac';\n    flightTypeToggle.querySelectorAll('.ft-btn').forEach(function(b){ b.classList.remove('active'); });\n    flightTypeToggle.querySelector('[data-type=\"medevac\"]').classList.add('active');\n\n    // campo 04\n    state.deckPos = 'plataforma';\n    deckPosRow.querySelectorAll('.deck-pos-btn').forEach(function(b){ b.classList.remove('active'); });\n    deckPosRow.querySelector('[data-pos=\"plataforma\"]').classList.add('active');\n    updateBaseClassDisplay();\n\n    // campo 05 (proa da UM + vento)\n    state.shipHdg = 0;\n    state.windDirTrue = 0;\n    state.windSpd = 0;\n    recomputeRelativeWind();\n    if (window.NDL_resetCompassWidget) window.NDL_resetCompassWidget();\n\n    // campo 07 (gr\u00e1fico de componentes de vento)\n    if (window.wccClearAll) window.wccClearAll();\n\n    // campo 08\n    state.heliCategory = 'A';\n    heliCategoryRow.querySelectorAll('.qbtn').forEach(function(b){ b.classList.remove('active'); });\n    heliCategoryRow.querySelector('[data-cat=\"A\"]').classList.add('active');\n    state.motionBC = 0; motionBCInput.value = 0; motionBCVal.textContent = '0,0';\n    state.motionInc = 0; motionIncInput.value = 0; motionIncVal.textContent = '0,0';\n    state.motionVArf = 0; motionVArfInput.value = 0; motionVArfVal.textContent = '0,0';\n    state.motionArf = 0; motionArfInput.value = 0; motionArfVal.textContent = '0,0';\n\n    render();\n    renderMotionLimits();\n    updateNovoVooState();\n  }\n\n  document.getElementById('novoVooBtn').addEventListener('click', resetEverything);\n\n  document.getElementById('topoBtn').addEventListener('click', function(){\n    var scroller = (window.document.getElementById('app-frame')) || window;\n    if (scroller === window) { window.scrollTo({ top: 0, behavior: 'smooth' }); }\n    else { scroller.scrollTo({ top: 0, behavior: 'smooth' }); }\n  });\n\n  // ---------- barra fixa: altura din\u00e2mica + \u00edndice de navega\u00e7\u00e3o ----------\n  var topbarEl = document.getElementById('topbar');\n  function updateTopbarHeight(){\n    if (!topbarEl) return;\n    document.documentElement.style.setProperty('--topbar-h', topbarEl.offsetHeight + 'px');\n  }\n  window.addEventListener('resize', updateTopbarHeight);\n  updateTopbarHeight();\n\n  var topnavSelect = document.getElementById('topnavSelect');\n  topnavSelect.addEventListener('change', function(){\n    var target = document.getElementById('panel-' + topnavSelect.value);\n    var scroller = window.document.getElementById('app-frame');\n    if (target && scroller){\n      var frameRect = scroller.getBoundingClientRect();\n      var targetRect = target.getBoundingClientRect();\n      var y = scroller.scrollTop + (targetRect.top - frameRect.top) - (topbarEl.offsetHeight + 10);\n      scroller.scrollTo({ top: y, behavior: 'smooth' });\n    } else if (target){\n      var y2 = target.getBoundingClientRect().top + window.pageYOffset - (topbarEl.offsetHeight + 10);\n      window.scrollTo({ top: y2, behavior: 'smooth' });\n    }\n  });\n  if ('IntersectionObserver' in window){\n    var panelEls = document.querySelectorAll('.panel[id^=\"panel-\"]');\n    var navObserver = new IntersectionObserver(function(entries){\n      entries.forEach(function(entry){\n        if (entry.isIntersecting){\n          var n = entry.target.id.replace('panel-','');\n          topnavSelect.value = n;\n        }\n      });\n    }, { rootMargin: '-40% 0px -55% 0px' });\n    panelEls.forEach(function(p){ navObserver.observe(p); });\n  }\n\n  updateNovoVooState();\n\n  render();\n})();\n", "\n// ===================== B\u00fassola de Setores (campo 05: proa da UM + vento) =====================\n// Script independente (escopo global pr\u00f3prio) para evitar qualquer conflito de nomes com o\n// script principal do app. A integra\u00e7\u00e3o acontece s\u00f3 pelas pontes window.NDL_setShipHdg /\n// window.NDL_setWindDirTrue / window.NDL_setWindSpd, chamadas sempre que o usu\u00e1rio interage.\n(function(){\n  const svgNS = \"http://www.w3.org/2000/svg\";\n  const cx = 200, cy = 200;\n  // marca que o usu\u00e1rio realmente interagiu (arrastou/tocou/clicou) com a\n  // proa ou o vento \u2014 usado pelo app principal para s\u00f3 calcular Pouso/Assento\n  // depois da 1\u00aa sele\u00e7\u00e3o manual, nunca no estado inicial \"de f\u00e1brica\".\n  function markUserTouched(){\n    // (funcionalidade de \"exigir toque antes de calcular\" foi removida \u2014 Pouso/Assento\n    // agora segue sempre a proa/vento atuais, inclusive na abertura do app)\n  }\n  const shipGroup = document.getElementById('sopShipGroup');\n  const ticksG = document.getElementById('sopTicks');\n  const cardinalsG = document.getElementById('sopCardinals');\n  const proaValueEl = document.getElementById('sopProaValue');\n  const proaCompassEl = document.getElementById('sopProaCompass');\n  const windValueEl = document.getElementById('sopWindValue');\n  const windSectorEl = document.getElementById('sopWindSector');\n  const windIntensityEl = document.getElementById('sopWindIntensity');\n  const windArrowGroup = document.getElementById('sopWindArrowGroup');\n  const svgRoot = document.getElementById('sopSvgRoot');\n\n  if (!shipGroup || !svgRoot) return; // painel n\u00e3o presente nesta p\u00e1gina\n\n  for(let i=0;i<=100;i++){\n    const opt = document.createElement('option');\n    opt.value = i;\n    opt.textContent = i + ' kt';\n    windIntensityEl.appendChild(opt);\n  }\n  windIntensityEl.value = 0;\n\n  let windArrowAngle = 0; // 0 = alinhado com o vento verdadeiro padr\u00e3o do app (000\u00b0)\n\n  let rotation = 0;\n  let selectedSector = null;\n\n  function polarPt(angleDeg, radius, ox=cx, oy=cy){\n    const rad = angleDeg * Math.PI/180;\n    return { x: ox + radius*Math.sin(rad), y: oy - radius*Math.cos(rad) };\n  }\n\n  function compassLetter(deg){\n    const dirs = [\"N\",\"NE\",\"E\",\"SE\",\"S\",\"SW\",\"W\",\"NW\"];\n    return dirs[Math.round(((deg%360)+360)%360/45)%8];\n  }\n  function pad3(n){ return String(Math.round(((n%360)+360)%360)).padStart(3,'0'); }\n\n  // ---- fixed compass ring: ticks + cardinal letters ----\n  for(let a=0;a<360;a+=15){\n    const major = a % 90 === 0;\n    const semi = a % 45 === 0;\n    const r1 = 188;\n    const r2 = major ? 168 : (semi ? 174 : 179);\n    const p1 = polarPt(a, r1), p2 = polarPt(a, r2);\n    const line = document.createElementNS(svgNS,'line');\n    line.setAttribute('x1',p1.x); line.setAttribute('y1',p1.y);\n    line.setAttribute('x2',p2.x); line.setAttribute('y2',p2.y);\n    line.setAttribute('stroke', major ? '#c9a35c' : '#3a4a5c');\n    line.setAttribute('stroke-width', major ? 2.4 : 1.3);\n    ticksG.appendChild(line);\n  }\n  const cardinalNames = {0:'N',45:'NE',90:'E',135:'SE',180:'S',225:'SW',270:'W',315:'NW'};\n  Object.entries(cardinalNames).forEach(([a,name])=>{\n    const p = polarPt(Number(a), 152);\n    const t = document.createElementNS(svgNS,'text');\n    t.setAttribute('x',p.x); t.setAttribute('y',p.y+4);\n    t.setAttribute('text-anchor','middle');\n    t.setAttribute('font-size', name.length>1 ? 11 : 14);\n    t.setAttribute('font-weight','700');\n    t.setAttribute('fill', name==='N' ? '#e0a83e' : '#9fb2c4');\n    t.textContent = name;\n    cardinalsG.appendChild(t);\n  });\n\n  // ---- ship hull (rotates) ----\n  const hull = document.createElementNS(svgNS,'path');\n  hull.setAttribute('d','M200,60 L234,138 L242,296 Q242,328 200,340 Q158,328 158,296 L166,138 Z');\n  hull.setAttribute('fill','#b6864f');\n  hull.setAttribute('stroke','#7a2a1f');\n  hull.setAttribute('stroke-width','5');\n  hull.setAttribute('class','ship-drag');\n  shipGroup.appendChild(hull);\n\n  const deckInner = document.createElementNS(svgNS,'path');\n  deckInner.setAttribute('d','M200,72 L226,140 L233,292 Q233,318 200,328 Q167,318 167,292 L174,140 Z');\n  deckInner.setAttribute('fill','#c9a06a');\n  deckInner.setAttribute('stroke','none');\n  deckInner.setAttribute('class','ship-drag');\n  shipGroup.appendChild(deckInner);\n\n  const greenHatch = document.createElementNS(svgNS,'rect');\n  greenHatch.setAttribute('x',178); greenHatch.setAttribute('y',96);\n  greenHatch.setAttribute('width',44); greenHatch.setAttribute('height',36);\n  greenHatch.setAttribute('rx',3);\n  greenHatch.setAttribute('fill','#4f7a3a');\n  greenHatch.setAttribute('stroke','#33501f');\n  greenHatch.setAttribute('stroke-width','1.5');\n  greenHatch.setAttribute('class','ship-drag');\n  shipGroup.appendChild(greenHatch);\n\n  const whiteFwd = document.createElementNS(svgNS,'rect');\n  whiteFwd.setAttribute('x',172); whiteFwd.setAttribute('y',150);\n  whiteFwd.setAttribute('width',56); whiteFwd.setAttribute('height',30);\n  whiteFwd.setAttribute('rx',5);\n  whiteFwd.setAttribute('fill','#ece6d6');\n  whiteFwd.setAttribute('stroke','#9a9382');\n  whiteFwd.setAttribute('stroke-width','1.5');\n  whiteFwd.setAttribute('class','ship-drag');\n  shipGroup.appendChild(whiteFwd);\n\n  const craneBase = document.createElementNS(svgNS,'circle');\n  craneBase.setAttribute('cx',200); craneBase.setAttribute('cy',204);\n  craneBase.setAttribute('r',9);\n  craneBase.setAttribute('fill','#1c1c1c');\n  craneBase.setAttribute('class','ship-drag');\n  shipGroup.appendChild(craneBase);\n  const craneBoom = document.createElementNS(svgNS,'line');\n  craneBoom.setAttribute('x1',200); craneBoom.setAttribute('y1',204);\n  craneBoom.setAttribute('x2',224); craneBoom.setAttribute('y2',186);\n  craneBoom.setAttribute('stroke','#1c1c1c');\n  craneBoom.setAttribute('stroke-width','5');\n  craneBoom.setAttribute('stroke-linecap','round');\n  craneBoom.setAttribute('class','ship-drag');\n  shipGroup.appendChild(craneBoom);\n\n  const cargoColors = ['#c0392b','#2f6fa8','#d9a72c'];\n  cargoColors.forEach((color,i)=>{\n    const box = document.createElementNS(svgNS,'rect');\n    box.setAttribute('x', 176 + i*22);\n    box.setAttribute('y', 224);\n    box.setAttribute('width', 18);\n    box.setAttribute('height', 30);\n    box.setAttribute('rx', 2);\n    box.setAttribute('fill', color);\n    box.setAttribute('stroke', '#00000033');\n    box.setAttribute('stroke-width', '1');\n    box.setAttribute('class','ship-drag');\n    shipGroup.appendChild(box);\n  });\n\n  const whiteAft = document.createElementNS(svgNS,'rect');\n  whiteAft.setAttribute('x',174); whiteAft.setAttribute('y',266);\n  whiteAft.setAttribute('width',52); whiteAft.setAttribute('height',44);\n  whiteAft.setAttribute('rx',5);\n  whiteAft.setAttribute('fill','#ece6d6');\n  whiteAft.setAttribute('stroke','#9a9382');\n  whiteAft.setAttribute('stroke-width','1.5');\n  whiteAft.setAttribute('class','ship-drag');\n  shipGroup.appendChild(whiteAft);\n\n  // ---- sectors ----\n  const sectors = [\n    {name:'Proa', angle:0},\n    {name:'Bochecha (Boreste)', angle:45},\n    {name:'Trav\u00e9s (Boreste)', angle:90},\n    {name:'Alheta (Boreste)', angle:135},\n    {name:'Popa', angle:180},\n    {name:'Alheta (Bombordo)', angle:225},\n    {name:'Trav\u00e9s (Bombordo)', angle:270},\n    {name:'Bochecha (Bombordo)', angle:315},\n  ];\n\n  const labelEls = [];\n  sectors.forEach(sec=>{\n    const end = polarPt(sec.angle, 168);\n    const labelPos = polarPt(sec.angle, 192);\n\n    const hit = document.createElementNS(svgNS,'line');\n    hit.setAttribute('x1',cx); hit.setAttribute('y1',cy);\n    hit.setAttribute('x2',end.x); hit.setAttribute('y2',end.y);\n    hit.setAttribute('class','sector-hit');\n\n    const line = document.createElementNS(svgNS,'line');\n    line.setAttribute('x1',cx); line.setAttribute('y1',cy);\n    line.setAttribute('x2',end.x); line.setAttribute('y2',end.y);\n    line.setAttribute('class','sector-line');\n    line.dataset.angle = sec.angle;\n    line.dataset.name = sec.name;\n\n    const dot = document.createElementNS(svgNS,'circle');\n    dot.setAttribute('cx',end.x); dot.setAttribute('cy',end.y);\n    dot.setAttribute('r',3.2);\n    dot.setAttribute('class','sector-dot');\n\n    const label = document.createElementNS(svgNS,'text');\n    label.setAttribute('x',labelPos.x); label.setAttribute('y',labelPos.y);\n    label.setAttribute('class','sector-label');\n    const words = sec.name.split(' (');\n    label.textContent = words[0];\n    if(words[1]){\n      const tspan = document.createElementNS(svgNS,'tspan');\n      tspan.setAttribute('x',labelPos.x);\n      tspan.setAttribute('dy','11');\n      tspan.textContent = '('+words[1];\n      label.appendChild(tspan);\n    }\n    labelEls.push({el:label, x:labelPos.x, y:labelPos.y});\n\n    function activate(){\n      markUserTouched();\n      document.querySelectorAll('.sopdial .sector-line').forEach(l=>l.classList.remove('active'));\n      line.classList.add('active');\n      selectedSector = sec;\n      updateWindLabel();\n    }\n    hit.addEventListener('click', activate);\n    line.addEventListener('click', activate);\n\n    shipGroup.appendChild(hit);\n    shipGroup.appendChild(line);\n    shipGroup.appendChild(dot);\n    shipGroup.appendChild(label);\n  });\n\n  // ---- seta de vento ----\n  const arrowTailR = 226, arrowHeadBaseR = 200, arrowTipR = 182;\n  const aTail = polarPt(0, arrowTailR);\n  const aBase = polarPt(0, arrowHeadBaseR);\n  const aTip = polarPt(0, arrowTipR);\n  const aLeft = { x: aBase.x - 13, y: aBase.y };\n  const aRight = { x: aBase.x + 13, y: aBase.y };\n\n  const arrowHit = document.createElementNS(svgNS,'line');\n  arrowHit.setAttribute('x1',aTail.x); arrowHit.setAttribute('y1',aTail.y);\n  arrowHit.setAttribute('x2',aTip.x); arrowHit.setAttribute('y2',aTip.y);\n  arrowHit.setAttribute('class','wind-arrow-hit');\n  windArrowGroup.appendChild(arrowHit);\n\n  const arrowShaft = document.createElementNS(svgNS,'line');\n  arrowShaft.setAttribute('x1',aTail.x); arrowShaft.setAttribute('y1',aTail.y);\n  arrowShaft.setAttribute('x2',aBase.x); arrowShaft.setAttribute('y2',aBase.y);\n  arrowShaft.setAttribute('class','wind-arrow-shaft');\n  windArrowGroup.appendChild(arrowShaft);\n\n  const arrowHead = document.createElementNS(svgNS,'polygon');\n  arrowHead.setAttribute('points', `${aTip.x},${aTip.y} ${aLeft.x},${aLeft.y} ${aRight.x},${aRight.y}`);\n  arrowHead.setAttribute('class','wind-arrow-head');\n  windArrowGroup.appendChild(arrowHead);\n\n  // label \"VENTO\" desenhada sobre a haste da seta, girando junto com ela\n  const shaftMid = polarPt(0, (arrowTailR + arrowHeadBaseR) / 2);\n  const arrowLabel = document.createElementNS(svgNS,'text');\n  arrowLabel.setAttribute('x', shaftMid.x);\n  arrowLabel.setAttribute('y', shaftMid.y);\n  arrowLabel.setAttribute('text-anchor','middle');\n  arrowLabel.setAttribute('dominant-baseline','middle');\n  arrowLabel.setAttribute('transform', `rotate(90 ${shaftMid.x} ${shaftMid.y})`);\n  arrowLabel.setAttribute('class','wind-arrow-label');\n  arrowLabel.textContent = 'VENTO';\n  windArrowGroup.appendChild(arrowLabel);\n\n  function updateWindArrowTransform(){\n    windArrowGroup.setAttribute('transform', `rotate(${windArrowAngle} ${cx} ${cy})`);\n  }\n  updateWindArrowTransform();\n\n  function setWindFromArrow(){\n    selectedSector = null;\n    document.querySelectorAll('.sopdial .sector-line').forEach(l=>l.classList.remove('active'));\n    const bearing = ((windArrowAngle % 360)+360)%360;\n    windValueEl.value = pad3(bearing)+'\u00b0 '+compassLetter(bearing);\n    windSectorEl.textContent = 'definido pela seta';\n    if (window.NDL_setWindDirTrue) window.NDL_setWindDirTrue(bearing);\n  }\n\n  const VBOX = 460, ARROW_CENTER = 230;\n  function arrowAngleFromEvent(evt){\n    const rect = svgRoot.getBoundingClientRect();\n    const clientX = evt.touches ? evt.touches[0].clientX : evt.clientX;\n    const clientY = evt.touches ? evt.touches[0].clientY : evt.clientY;\n    const x = ((clientX - rect.left)/rect.width)*VBOX;\n    const y = ((clientY - rect.top)/rect.height)*VBOX;\n    const dx = x - ARROW_CENTER, dy = y - ARROW_CENTER;\n    return (Math.atan2(dx, -dy) * 180/Math.PI + 360) % 360;\n  }\n\n  let arrowDragging = false;\n  function arrowStartDrag(evt){\n    markUserTouched();\n    arrowDragging = true;\n    windArrowGroup.classList.add('dragging');\n    arrowMoveDrag(evt);\n    evt.preventDefault();\n  }\n  function arrowMoveDrag(evt){\n    if(!arrowDragging) return;\n    windArrowAngle = arrowAngleFromEvent(evt);\n    updateWindArrowTransform();\n    setWindFromArrow();\n    evt.preventDefault();\n  }\n  function arrowEndDrag(){\n    arrowDragging = false;\n    windArrowGroup.classList.remove('dragging');\n  }\n  arrowHit.addEventListener('mousedown', arrowStartDrag);\n  window.addEventListener('mousemove', arrowMoveDrag);\n  window.addEventListener('mouseup', arrowEndDrag);\n  arrowHit.addEventListener('touchstart', arrowStartDrag, {passive:false});\n  window.addEventListener('touchmove', arrowMoveDrag, {passive:false});\n  window.addEventListener('touchend', arrowEndDrag);\n\n  function updateWindLabel(){\n    if(!selectedSector) return;\n    const bearing = ((selectedSector.angle + rotation) % 360 + 360) % 360;\n    windValueEl.value = pad3(bearing)+'\u00b0 '+compassLetter(bearing);\n    windSectorEl.textContent = selectedSector.name;\n    if (window.NDL_setWindDirTrue) window.NDL_setWindDirTrue(bearing);\n  }\n\n  // ---- girar a proa arrastando a UM ----\n  let shipDragging = false;\n  function shipStartDrag(evt){\n    markUserTouched();\n    shipDragging = true;\n    shipMoveDrag(evt);\n    evt.preventDefault();\n    evt.stopPropagation();\n  }\n  function shipMoveDrag(evt){\n    if(!shipDragging) return;\n    rotation = arrowAngleFromEvent(evt);\n    update();\n    evt.preventDefault();\n  }\n  function shipEndDrag(){ shipDragging = false; }\n\n  document.querySelectorAll('.sopdial .ship-drag').forEach(el=>{\n    el.addEventListener('mousedown', shipStartDrag);\n    el.addEventListener('touchstart', shipStartDrag, {passive:false});\n  });\n  window.addEventListener('mousemove', shipMoveDrag);\n  window.addEventListener('mouseup', shipEndDrag);\n  window.addEventListener('touchmove', shipMoveDrag, {passive:false});\n  window.addEventListener('touchend', shipEndDrag);\n\n  function update(){\n    shipGroup.setAttribute('transform', `rotate(${rotation} ${cx} ${cy})`);\n    labelEls.forEach(l=>{\n      l.el.setAttribute('transform', `rotate(${-rotation} ${l.x} ${l.y})`);\n    });\n    const b = ((rotation % 360)+360)%360;\n    const displayB = b === 0 ? 360 : b;\n    proaValueEl.value = pad3(displayB)+'\u00b0';\n    proaCompassEl.textContent = compassLetter(b) === 'N' ? 'Norte' : compassLetter(b);\n    updateWindLabel();\n    if (window.NDL_setShipHdg) window.NDL_setShipHdg(b);\n  }\n  update();\n  setWindFromArrow(); // sincroniza o vento inicial (000\u00b0) com o app\n\n  // ---- digita\u00e7\u00e3o direta nos campos Proa da UM e Dire\u00e7\u00e3o do vento ----\n  function parseDeg(txt){\n    const m = String(txt).replace(',', '.').match(/-?\\d+(\\.\\d+)?/);\n    return m ? parseFloat(m[0]) : NaN;\n  }\n  function commitProa(){\n    const v = parseDeg(proaValueEl.value);\n    if (isNaN(v)) { update(); return; }\n    markUserTouched();\n    rotation = ((v % 360) + 360) % 360;\n    update();\n  }\n  function commitWind(){\n    const v = parseDeg(windValueEl.value);\n    if (isNaN(v)) { setWindFromArrow(); return; }\n    markUserTouched();\n    windArrowAngle = ((v % 360) + 360) % 360;\n    updateWindArrowTransform();\n    setWindFromArrow();\n  }\n  [[proaValueEl, commitProa], [windValueEl, commitWind]].forEach(function(par){\n    const el = par[0], commit = par[1];\n    el.addEventListener('focus', function(){ setTimeout(function(){ try { el.select(); } catch(e){} }, 0); });\n    el.addEventListener('change', commit);\n    el.addEventListener('keydown', function(e){ if (e.key === 'Enter') { e.preventDefault(); el.blur(); } });\n  });\n\n  windIntensityEl.addEventListener('change', function(){\n    const spd = parseInt(windIntensityEl.value, 10) || 0;\n    if (window.NDL_setWindSpd) window.NDL_setWindSpd(spd);\n  });\n\n  // exposto para o bot\u00e3o \"Novo Voo\" (script principal) zerar a proa e o vento\n  // visualmente aqui tamb\u00e9m, j\u00e1 que este widget mant\u00e9m seu pr\u00f3prio estado.\n  window.NDL_resetCompassWidget = function(){\n    rotation = 0;\n    windArrowAngle = 0;\n    selectedSector = null;\n    windIntensityEl.value = 0;\n    document.querySelectorAll('.sopdial .sector-line').forEach(function(l){ l.classList.remove('active'); });\n    updateWindArrowTransform();\n    update();\n    setWindFromArrow();\n  };\n\n  function startRepeat(step){\n    markUserTouched();\n    rotation += step; update();\n    let delay = 400;\n    let timeoutId, intervalId;\n    timeoutId = setTimeout(()=>{\n      intervalId = setInterval(()=>{ rotation += step; update(); }, 60);\n    }, delay);\n    function stop(){\n      clearTimeout(timeoutId);\n      clearInterval(intervalId);\n      window.removeEventListener('mouseup', stop);\n      window.removeEventListener('touchend', stop);\n      window.removeEventListener('touchcancel', stop);\n    }\n    window.addEventListener('mouseup', stop);\n    window.addEventListener('touchend', stop);\n    window.addEventListener('touchcancel', stop);\n  }\n\n  // ---- mini-bot\u00f5es (canto superior direito da label \"Proa da UM\") ----\n  const miniMinus = document.getElementById('sopMiniMinus');\n  const miniPlus = document.getElementById('sopMiniPlus');\n  const miniZero = document.getElementById('sopMiniZero');\n  miniMinus.addEventListener('mousedown', (e)=>{ e.preventDefault(); startRepeat(-1); });\n  miniMinus.addEventListener('touchstart', (e)=>{ e.preventDefault(); startRepeat(-1); }, {passive:false});\n  miniPlus.addEventListener('mousedown', (e)=>{ e.preventDefault(); startRepeat(1); });\n  miniPlus.addEventListener('touchstart', (e)=>{ e.preventDefault(); startRepeat(1); }, {passive:false});\n  miniZero.addEventListener('click', ()=>{ markUserTouched(); rotation = 0; update(); });\n\n  // ---- mini-bot\u00f5es (canto superior direito da label \"Dire\u00e7\u00e3o do vento\") ----\n  function setWindArrowAngleDeg(deg){\n    windArrowAngle = ((deg % 360) + 360) % 360;\n    updateWindArrowTransform();\n    setWindFromArrow();\n  }\n  function startRepeatWind(step){\n    markUserTouched();\n    setWindArrowAngleDeg(windArrowAngle + step);\n    let delay = 400;\n    let timeoutId, intervalId;\n    timeoutId = setTimeout(()=>{\n      intervalId = setInterval(()=>{ setWindArrowAngleDeg(windArrowAngle + step); }, 60);\n    }, delay);\n    function stop(){\n      clearTimeout(timeoutId);\n      clearInterval(intervalId);\n      window.removeEventListener('mouseup', stop);\n      window.removeEventListener('touchend', stop);\n      window.removeEventListener('touchcancel', stop);\n    }\n    window.addEventListener('mouseup', stop);\n    window.addEventListener('touchend', stop);\n    window.addEventListener('touchcancel', stop);\n  }\n  const windMiniMinus = document.getElementById('sopWindMiniMinus');\n  const windMiniPlus = document.getElementById('sopWindMiniPlus');\n  const windMiniZero = document.getElementById('sopWindMiniZero');\n  windMiniMinus.addEventListener('mousedown', (e)=>{ e.preventDefault(); startRepeatWind(-1); });\n  windMiniMinus.addEventListener('touchstart', (e)=>{ e.preventDefault(); startRepeatWind(-1); }, {passive:false});\n  windMiniPlus.addEventListener('mousedown', (e)=>{ e.preventDefault(); startRepeatWind(1); });\n  windMiniPlus.addEventListener('touchstart', (e)=>{ e.preventDefault(); startRepeatWind(1); }, {passive:false});\n  windMiniZero.addEventListener('click', ()=>{ markUserTouched(); setWindArrowAngleDeg(0); });\n})();\n", "\n  // ================= CAMPO 07: Gr\u00e1fico de Componentes de Vento (QRH AW139) =================\n  (function(){\n    var WCC_CHART_LEFT   = 115;\n    var WCC_CHART_RIGHT  = 1347;\n    var WCC_CHART_BOTTOM = 1317;\n    var WCC_CHART_TOP    = 102;\n    var WCC_MAXKT         = 60; // alcance real do chart impresso\n    var WCC_SCALE_X       = (WCC_CHART_RIGHT - WCC_CHART_LEFT) / WCC_MAXKT;\n    var WCC_SCALE_Y       = (WCC_CHART_BOTTOM - WCC_CHART_TOP)  / WCC_MAXKT;\n\n    var wccSpdSel = document.getElementById('wccInpSpd');\n    if (wccSpdSel) {\n      for (var i = 0; i <= WCC_MAXKT; i++) {\n        var opt = document.createElement('option');\n        opt.value = String(i);\n        opt.textContent = i + ' kt';\n        wccSpdSel.appendChild(opt);\n      }\n    }\n\n    // ---- bot\u00f5es < 0 > de incremento/decremento (Proa de Aproxima\u00e7\u00e3o e Dire\u00e7\u00e3o do Vento) ----\n    function wccWrapDeg(v){ return ((v % 360) + 360) % 360; }\n    function wccPad3(n){ return String(Math.round(n)).padStart(3, '0') + '\u00b0'; }\n\n    function wccMakeStepper(inputId, minusId, plusId, zeroId){\n      var input = document.getElementById(inputId);\n      var minusBtn = document.getElementById(minusId);\n      var plusBtn = document.getElementById(plusId);\n      var zeroBtn = document.getElementById(zeroId);\n      if (!input || !minusBtn || !plusBtn || !zeroBtn) return;\n\n      function currentVal(){\n        var v = parseFloat(input.value);\n        return isNaN(v) ? 0 : v;\n      }\n      function setVal(v){\n        input.value = wccPad3(wccWrapDeg(v));\n      }\n      function step(delta){\n        setVal(currentVal() + delta);\n      }\n      function startRepeat(delta){\n        step(delta);\n        var timeoutId, intervalId;\n        timeoutId = setTimeout(function(){\n          intervalId = setInterval(function(){ step(delta); }, 60);\n        }, 400);\n        function stop(){\n          clearTimeout(timeoutId);\n          clearInterval(intervalId);\n          window.removeEventListener('mouseup', stop);\n          window.removeEventListener('touchend', stop);\n          window.removeEventListener('touchcancel', stop);\n        }\n        window.addEventListener('mouseup', stop);\n        window.addEventListener('touchend', stop);\n        window.addEventListener('touchcancel', stop);\n      }\n      minusBtn.addEventListener('mousedown', function(e){ e.preventDefault(); startRepeat(-1); });\n      minusBtn.addEventListener('touchstart', function(e){ e.preventDefault(); startRepeat(-1); }, {passive:false});\n      plusBtn.addEventListener('mousedown', function(e){ e.preventDefault(); startRepeat(1); });\n      plusBtn.addEventListener('touchstart', function(e){ e.preventDefault(); startRepeat(1); }, {passive:false});\n      zeroBtn.addEventListener('click', function(){ setVal(0); wccUpdateBtnState(); });\n      input.addEventListener('input', wccUpdateBtnState);\n      input.addEventListener('blur', function(){\n        if (input.value !== '') setVal(currentVal());\n        wccUpdateBtnState();\n      });\n    }\n\n    function wccUpdateBtnState(){\n      var hdgEl = document.getElementById('wccInpHdg');\n      var dirEl = document.getElementById('wccInpDir');\n      var spdEl = document.getElementById('wccInpSpd');\n      var anyFilled = !!(hdgEl && hdgEl.value) || !!(dirEl && dirEl.value) || !!(spdEl && spdEl.value && spdEl.value !== '0');\n      var calcBtn = document.getElementById('wccCalcBtn');\n      var clearBtn = document.getElementById('wccClearBtn');\n      if (calcBtn) calcBtn.classList.toggle('flog-clean', !anyFilled);\n      if (clearBtn) clearBtn.classList.toggle('flog-clean', !anyFilled);\n      if (window.NDL_updateNovoVooState) window.NDL_updateNovoVooState();\n    }\n\n    wccMakeStepper('wccInpHdg', 'wccHdgMiniMinus', 'wccHdgMiniPlus', 'wccHdgMiniZero');\n    wccMakeStepper('wccInpDir', 'wccDirMiniMinus', 'wccDirMiniPlus', 'wccDirMiniZero');\n    var wccSpdSelForState = document.getElementById('wccInpSpd');\n    if (wccSpdSelForState) wccSpdSelForState.addEventListener('change', wccUpdateBtnState);\n    wccUpdateBtnState();\n\n    function wccToPx(cw, hw) {\n      return [ WCC_CHART_LEFT + cw * WCC_SCALE_X, WCC_CHART_BOTTOM - hw * WCC_SCALE_Y ];\n    }\n\n    function wccClearOutputs() {\n      var svg = document.getElementById('wccSvgOverlay');\n      if (svg) svg.innerHTML = '';\n      var res = document.getElementById('wccPanelResult');\n      if (res) res.classList.remove('active');\n      var content = document.getElementById('wccResultContent');\n      if (content) content.innerHTML = '<div class=\"wcc-placeholder\">Preencha os campos acima e toque em CALCULAR</div>';\n      var warn = document.getElementById('wccWarningBox');\n      if (warn) warn.style.display = 'none';\n      wccUpdateLimitBanner(null);\n    }\n\n    function wccShowError(msg) {\n      wccClearOutputs();\n      var b = document.getElementById('wccErrorBox');\n      b.textContent = '\u26a0 ' + msg;\n      b.style.display = 'block';\n    }\n\n    function wccShowWarning(msg) {\n      var b = document.getElementById('wccWarningBox');\n      b.textContent = '\u26a0 ' + msg;\n      b.style.display = 'block';\n    }\n\n    function wccCalculate() {\n      var errorBox = document.getElementById('wccErrorBox');\n      errorBox.style.display = 'none';\n      document.getElementById('wccWarningBox').style.display = 'none';\n\n      var hdg = parseFloat(document.getElementById('wccInpHdg').value);\n      var dir = parseFloat(document.getElementById('wccInpDir').value);\n      var spd = parseFloat(document.getElementById('wccInpSpd').value);\n\n      if (isNaN(hdg) || hdg < 0 || hdg > 359) { wccShowError('Proa deve ser 0\u00b0 \u2013 359\u00b0.'); return; }\n      if (isNaN(dir) || dir < 0 || dir > 360)  { wccShowError('Dire\u00e7\u00e3o deve ser 0\u00b0 \u2013 360\u00b0.'); return; }\n      if (isNaN(spd)) { wccShowError('Selecione a intensidade do vento.'); return; }\n\n      hdg = Math.round(hdg);\n      dir = Math.round(dir);\n\n      var rel = dir - hdg;\n      while (rel >  180) rel -= 360;\n      while (rel < -180) rel += 360;\n\n      var absRel = Math.abs(rel);\n      var side   = rel >= 0 ? 'direita' : 'esquerda';\n      var cw = spd * Math.sin((absRel * Math.PI) / 180);\n      var hw = spd * Math.cos((absRel * Math.PI) / 180);\n\n      var offChartTail = hw < 0;              // vento de cauda: fora do quadrante impresso\n      var offChartSpeed = spd > WCC_MAXKT;    // acima da escala do chart\n\n      if (offChartTail) {\n        wccClearOutputs();\n        wccShowWarning('Vento de cauda (' + (Math.round(Math.abs(hw)*10)/10) + ' kt) \u2014 fora do quadrante do chart, que cobre apenas vento de proa. Componente de trav\u00e9s pelo c\u00e1lculo trigonom\u00e9trico: ' + (Math.round(cw*10)/10) + ' kt pela ' + side + '.');\n        wccShowResult(Math.round(cw*10)/10, Math.round(hw*10)/10, side, absRel, true);\n        return;\n      }\n\n      if (offChartSpeed) {\n        wccShowWarning('Intensidade (' + spd + ' kt) acima do limite impresso do chart (' + WCC_MAXKT + ' kt). N\u00fameros calculados corretamente; desenho n\u00e3o representa esta condi\u00e7\u00e3o.');\n      }\n\n      wccDrawOverlay(cw, hw, spd);\n      wccShowResult(Math.round(cw*10)/10, Math.round(hw*10)/10, side, absRel, false);\n    }\n\n    function wccDrawOverlay(cw, hw, spd) {\n      var svg = document.getElementById('wccSvgOverlay');\n      svg.innerHTML = '';\n      if (spd === 0) return;\n\n      var cwC = Math.max(0, Math.min(cw, WCC_MAXKT));\n      var hwC = Math.max(0, Math.min(hw, WCC_MAXKT));\n      var spdC = Math.min(spd, WCC_MAXKT);\n\n      var sol = wccToPx(cwC, hwC);\n      var solX = sol[0], solY = sol[1];\n      var arcRx = spdC * WCC_SCALE_X;\n      var arcRy = spdC * WCC_SCALE_Y;\n      var arcStartX = WCC_CHART_LEFT;\n      var arcStartY = WCC_CHART_BOTTOM - spdC * WCC_SCALE_Y;\n\n      function el(tag, attrs) {\n        var e = document.createElementNS('http://www.w3.org/2000/svg', tag);\n        for (var k in attrs) e.setAttribute(k, attrs[k]);\n        svg.appendChild(e);\n      }\n\n      el('path', { d:'M ' + arcStartX + ' ' + arcStartY + ' A ' + arcRx + ' ' + arcRy + ' 0 0 1 ' + solX + ' ' + solY,\n        fill:'none', stroke:'rgba(0,100,255,0.35)', 'stroke-width':'24' });\n      el('path', { d:'M ' + arcStartX + ' ' + arcStartY + ' A ' + arcRx + ' ' + arcRy + ' 0 0 1 ' + solX + ' ' + solY,\n        fill:'none', stroke:'#0066ff', 'stroke-width':'6', 'stroke-dasharray':'16 8' });\n\n      el('line', { x1:WCC_CHART_LEFT, y1:WCC_CHART_BOTTOM, x2:solX, y2:solY,\n        stroke:'rgba(0,100,255,0.35)', 'stroke-width':'24' });\n      el('line', { x1:WCC_CHART_LEFT, y1:WCC_CHART_BOTTOM, x2:solX, y2:solY,\n        stroke:'#0066ff', 'stroke-width':'6', 'stroke-dasharray':'16 8' });\n\n      el('line', { x1:solX, y1:solY, x2:solX, y2:WCC_CHART_TOP,\n        stroke:'rgba(255,0,0,0.35)', 'stroke-width':'24' });\n      el('line', { x1:solX, y1:solY, x2:solX, y2:WCC_CHART_TOP,\n        stroke:'#ff0000', 'stroke-width':'6', 'stroke-dasharray':'14 7' });\n\n      el('line', { x1:solX, y1:solY, x2:WCC_CHART_RIGHT, y2:solY,\n        stroke:'rgba(0,200,50,0.35)', 'stroke-width':'24' });\n      el('line', { x1:solX, y1:solY, x2:WCC_CHART_RIGHT, y2:solY,\n        stroke:'#00dd33', 'stroke-width':'6', 'stroke-dasharray':'14 7' });\n\n      el('circle', { cx:solX,            cy:solY,            r:'20', fill:'rgba(0,100,255,0.25)' });\n      el('circle', { cx:solX,            cy:solY,            r:'12', fill:'#0066ff',  stroke:'white', 'stroke-width':'3.5' });\n      el('circle', { cx:solX,            cy:WCC_CHART_TOP,   r:'11', fill:'#ff0000',  stroke:'white', 'stroke-width':'3' });\n      el('circle', { cx:WCC_CHART_RIGHT, cy:solY,            r:'11', fill:'#00dd33',  stroke:'white', 'stroke-width':'3' });\n    }\n\n    function wccShowResult(cw, hw, side, absRel, offChart) {\n      document.getElementById('wccPanelResult').classList.add('active');\n      var hwColor = hw >= 0 ? '#2ecc71' : '#e03a3a';\n      var hwLabel = hw >= 0 ? 'VENTO DE PROA' : 'VENTO DE CAUDA';\n      var sideTxt = (Math.abs(cw) < 0.05) ? '' : (' \u2014 pela ' + side);\n      document.getElementById('wccResultContent').innerHTML =\n        '<div class=\"wcc-result-inner\">' +\n          '<div class=\"wcc-result-col\">' +\n            '<div class=\"wcc-field-label\">VENTO DE TRAV\u00c9S</div>' +\n            '<div class=\"wcc-big-num\" id=\"wccOutCross\" style=\"color:#e03a3a\">' + cw + '</div>' +\n            '<div class=\"wcc-hint\" id=\"wccOutCrossHint\">kt' + sideTxt + '</div>' +\n          '</div>' +\n          '<div class=\"wcc-result-col\">' +\n            '<div class=\"wcc-field-label\" id=\"wccOutHeadLabel\">' + hwLabel + '</div>' +\n            '<div class=\"wcc-mid-num\" id=\"wccOutHead\" style=\"color:' + hwColor + '\">' + Math.abs(hw) + ' kt</div>' +\n          '</div>' +\n          '<div class=\"wcc-result-col\">' +\n            '<div class=\"wcc-field-label\">\u00c2NGULO RELATIVO</div>' +\n            '<div class=\"wcc-mid-num\" id=\"wccOutAngle\" style=\"color:#0099ff\">' + Math.round(absRel) + '\u00b0</div>' +\n          '</div>' +\n        '</div>';\n      wccUpdateLimitBanner({ cw: cw, hw: hw });\n    }\n\n    // ---- tarja de limite de vento de trav\u00e9s, alinhada de borda a borda do painel ----\n    function wccUpdateLimitBanner(data) {\n      var banner = document.getElementById('wccLimitBanner');\n      if (!banner) return;\n\n      if (!data) {\n        banner.style.display = 'none';\n        banner.textContent = '';\n        return;\n      }\n\n      var absCw = Math.abs(data.cw);\n      var hw = data.hw;\n      var msg = null;\n\n      var flightType = (window.state && window.state.flightType) ? window.state.flightType : 'medevac';\n      var limit = (typeof window.crosswindLimitFor === 'function') ? window.crosswindLimitFor(flightType) : 20;\n\n      if (flightType === 'treinamento') {\n        if (absCw > limit) {\n          msg = 'POUSO N\u00c3O PERMITIDO!!! LIMITE DE VENTO TRAV\u00c9S \u00c9 DE ' + limit + ' kt.';\n        }\n      } else {\n        if (absCw > 20) {\n          msg = 'POUSO N\u00c3O PERMITIDO!!! LIMITE DE VENTO TRAV\u00c9S \u00c9 DE 20 kt.';\n        } else if (absCw > 10 && hw < 5) {\n          msg = 'POUSO N\u00c3O PERMITIDO!!! PARA VENTO DE TRAV\u00c9S ACIMA DE 10 kt, \u00c9 NECESS\u00c1RIO UMA COMPONENTE DE PROA DE NO M\u00cdNIMO 5 kt.';\n        }\n      }\n\n      if (!msg) {\n        banner.style.display = 'none';\n        banner.textContent = '';\n        return;\n      }\n\n      banner.textContent = msg;\n      banner.style.display = 'block';\n\n      var panel = document.getElementById('panel-07');\n      if (panel) {\n        var cs = window.getComputedStyle(panel);\n        var padLeft = parseFloat(cs.paddingLeft) || 0;\n        var padRight = parseFloat(cs.paddingRight) || 0;\n        banner.style.marginLeft = '-' + padLeft + 'px';\n        banner.style.marginRight = '-' + padRight + 'px';\n        banner.style.width = 'auto';\n      }\n    }\n\n    function wccClearAll() {\n      var hdgInput = document.getElementById('wccInpHdg');\n      if (hdgInput) hdgInput.value = '';\n      var dirInput = document.getElementById('wccInpDir');\n      if (dirInput) dirInput.value = '';\n      var spdSel = document.getElementById('wccInpSpd');\n      if (spdSel) spdSel.value = '0';\n      var errorBox = document.getElementById('wccErrorBox');\n      if (errorBox) errorBox.style.display = 'none';\n      wccClearOutputs();\n      wccUpdateBtnState();\n    }\n    window.wccClearAll = wccClearAll;\n\n    var wccBtn = document.getElementById('wccCalcBtn');\n    if (wccBtn) wccBtn.addEventListener('click', wccCalculate);\n    var wccClearBtnEl = document.getElementById('wccClearBtn');\n    if (wccClearBtnEl) wccClearBtnEl.addEventListener('click', wccClearAll);\n  })();\n"]};
